quests[25635] = { id = 25635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Schlachtfeld", description = "<Überall um Euch herum liegen Relikte der wilden Schlacht. Die Nagaskelette überraschen Euch nicht, aber die Waffen und Überreste ihrer offensichtlichen Gegner dafür viel mehr.>\n\n<Inmitten der Knochen entdeckt Ihr ein auffälliges Stück Metall, das aus einem der Schädel herausragt. Es ist schwer zu sagen, zu welcher Art Waffe das Metall einst gehört haben mag, aber es steht weit genug hervor, dass Ihr es als Beweis mitnehmen könnt.>\n\n<Irgendjemand in der Höhle ist an dieser Erkenntnis sicher interessiert.>", sourceObjective = "Bringt das Bruchstück zurück zur Höhle.", sourceObjectiveStatus = "unverified-source-field" }
quests[25636] = { id = 25636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schildkrötensuppe für die Seele", description = "Mack ist immer nur kurz bei Bewusstsein.\n\nWenn er es schaffen soll, braucht er unsere volle Unterstützung.\n\nIch kenne ein gutes Rezept für Schildkrötensuppe, das ihn sicher aufwärmen wird.\n\nBringt mir ein wenig Schildkrötenfleisch. Ich kümmere mich dann um den Rest.", sourceObjective = "Sammelt 4 Stück Schildkrötenfleisch von gesprenkelten Meeresschildkröten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25637] = { id = 25637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf den Ruf des Tiefenlords", description = "Tiefenlord Zin'jatar hat uns berichtet, dass der Anführer der Kvaldir sich gezeigt hat. Begebt Euch zu ihm. Er befindet sich am gegenüberliegenden Ende der Terrasse über uns, auf der mittleren Ebene der Ruinen: Die Terrasse von Nar'shola.\n\nTötet alle Kvaldir, die Euch im Weg stehen. Wir möchten, dass der Widerhall dieser Niederlage in ihren Köpfen gellt, auf dass sie es nicht wagen, zurückzukehren und unser Vorhaben hier zu stören.\n\nEuer hingebungsvoller Einsatz bleibt nicht unbemerkt, meine Kriegsmaid. Geht und wisst, dass Ihr meinen Segen habt.", sourceObjective = "Tötet 16 Kvaldir auf der Terrasse von Nar'shola, der mittleren Ebene der Ruinen.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", completion = "Wie schön, dass Ihr Euch mir anschließt, Kriegsmaid. Kampfgeräusche untermalten Eure Ankunft. Welch süßer Klang in meinen Ohren.", sourceObjectiveStatus = "unverified-source-field" }
quests[25638] = { id = 25638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine verzweifelte Bitte", description = "Die Nachricht in dieser Flasche ist nass aber immer noch lesbar.\n\nDer Schreiber behauptet, aus einem Nagagefängnis unter dem Meer entkommen zu sein.\n\nEr fürchtet deutlich um sein Leben. Ihr fragt Euch, ob es sich dabei um einen Eurer kürzlich entführten Schiffskameraden handeln könnte.\n\nDa Ihr nicht wisst, wie Ihr den Flüchtling finden sollt, beschließt Ihr, Euren Fund Erunak zu zeigen.", sourceObjective = "Bringt die durchnässte Notiz zu Erunak am Tiefgang.\n\nBereitgestellter Gegenstand:", completion = "Wenn sie noch am Leben ist, kann ich diese arme Seele vielleicht finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25640] = { id = 25640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer frei: Scherwindmine!", description = "Wir 'aben entdeckt die Ort von die große Goblinbomb', die Ihr 'abt gefunden in Silberwindzuflucht.\n\nIhr Eusch erinnern an Boog? Die Gnom, die Ihr 'abt gerettet von die Orcwagen? Er und Minx 'aben gefunden die Bomb' in die Scherwindmine. Ihr müsst ge'en dort'in toute de suite... sofort, {name}! Sie werden warten auf Eusch.", sourceObjective = "Sprecht mit Boog dem \"Zahnradflüsterer\" an der Scherwindmine im Steinkrallengebirge.", completion = "Schön, Euch wiederzusehen, {name}. Danke für die Rettung im Eschental. Sehr schade um die ganzen Gnome, die wir verloren haben.\n\nSeid Ihr bereit, an die Arbeit zu gehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[25641] = { id = 25641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muiseknachschub", description = "Ich habe alles getan, was ich für Euch tun konnte. Aber ich bin noch nicht mächtig genug, um mit etwas mächtigerem als Hippogryphenmuisek zu arbeiten - vor dem Desaster, das dadurch entstehen könnte, verschone ich Euch zuerst.\n\nWährend Ihr beschäftigt wart, habe ich den Hippogryphenmuisek fertiggestellt. Bringt es zu meinem Meister, dem Hexenmeister Uzer'i in Camp Mojache. Er kann damit mächtige Waffen herstellen und hoffentlich wird er von meinen bisherigen Leistungen beeindruckt sein.", sourceObjective = "Bringt das Gefäß für Hippogryphenmuisek zu Hexendoktor Uzer'i in Camp Mojache in Feralas.", progress = "Ihr kommt mir bekannt vor...", completion = "Gute Arbeit, in der Tat... von meiner eigenen Tochter hätte ich allerdings auch nicht weniger erwartet. Sie wird noch eine gute Hexe werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25642] = { id = 25642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schaut ihnen nicht in die Augen", description = "Zieht Euren Kopf ein, {name}. Wir wollen keine ungebetene Aufmerksamkeit auf uns lenken.\n\nAnscheinend beladen die Orcs den Ballon mit irgendeinem Erz aus der Mine. Geht dort hinein und nehmt den Orcs das Erz weg. Bringt mir alles, das ihr tragen könnt und ich werde es zur Untersuchung zum Professor schicken.\n\nBevor Ihr geht noch ein Ratschlag: Ihr könnt die Krom'gar leicht umgehen, weil sie (1) dumm wie Bohnenstroh sind und (2) nichts sehen können, wenn sie Erz tragen. Natürlich müsst Ihr sie töten, um an das Erz zu kommen.", sourceObjective = "Sammelt 10 Proben azurblaues Eisenerz ein.", progress = "Bringt mir die Erzproben!", completion = "Ich hoffe, das hat Euch nicht zu viel Mühe bereitet. Mit diesen Proben sollten wir in der Lage sein herauszufinden, was sie mit dem Erz und der großen Bombe vorhaben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25643] = { id = 25643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Graunebelruinen", description = "Ich werde von Visionen heimgesucht, {name}. Visionen eines großen Machtsymbols, das in die Hände eines dunklen Wesens fällt. Ich sehe ein Amulett, von den uralten Elfen gehalten... das in Vergessenheit geraten ist und alles in seiner Umgebung in Ruinen verwandelt, bis die Dämonen es durch Betrug und Bosheit erhalten.\n\nJede Nacht schleichen sich diese Bilder wieder und wieder in meine Träume. Die Geister schicken uns eine Warnung. Ich bin zu alt und die Kriegerhelden des Lagers sind damit beschäftigt, uns zu beschützen. Ich bitte Euch, folgt meinen Visionen in Richtung Süden zu den Graunebelruinen und macht das Amulett ausfindig.", sourceObjective = "Sucht in den Graunebelruinen nach dem Amulett, das der Weise Bleichlauf beschrieben hat.", completion = "<Als Ihr Euch dem Podest nähert, merkt Ihr, dass es leer ist. Kälte füllt den Raum und eine leise Stimme ertönt...>", sourceObjectiveStatus = "unverified-source-field" }
quests[25644] = { id = 25644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Zwielichtei", description = "Dieses Ei ist anders als alles, was Ihr je gesehen habt. Die durchsichtige Schale scheint das Licht um sie herum zu brechen.\n\nDaneben findet Ihr eine Nachricht, die die Ankunft einer fruchtbaren Brutmutter im Zirkel des Aszendenten beschreibt.\n\nVielleicht solltet Ihr Aronus das hier zeigen.", sourceObjective = "Bringt das reine Zwielichtei zu Aronus an den Toren von Sothann auf dem Hyjal.\n\nBereitgestellter Gegenstand:", completion = "Ihr habt richtig gehandelt, mir dies zu bringen, {name}. Dies ist eine große Bedrohung für uns, der wir uns unverzüglich und furchtlos stellen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25645] = { id = 25645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zum Weisen Bleichlauf zurück", description = "Das sanfte Leuchten bei dem Podest wird heller und Ihr könnt eine einfache Kette erkennen, die dort zurückgelassen wurde. Das muss das Amulett sein, wegen dem Euch der Weise Bleichlauf hergeschickt hat...", sourceObjective = "Bringt das Graunebelamulett zum Weisen Bleichlauf.", progress = "Ihr seid zurückgekehrt. Was habt Ihr gefunden?", completion = "Ich bin ein Narr... ich wurde in die Irre geleitet. Dies ist nur ein rostiges Stück Schmuck - meine Visionen haben sich zweifellos bewahrheitet.\n\nVergebt mir, {name}. Ich werde dafür beten, dass Ihr über diese Dämonin siegen werdet, so wie Ihr über Verinias gesiegt habt, solltet Ihr sie jemals wiedertreffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25646] = { id = 25646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Säuberung der Scherwindmine", description = "Die Horde hat die Scherwindmine eingenommen. Ich bin nicht sicher, was diese Orcs hier herausschleppen oder warum sie hier sind, aber ich weiß, das kann nichts Gutes bedeuten. Geht dort hinein und schaltet die Führung aus. Ohne die Goblinaufseher werden diese Peons noch nutzloser sein.\n\nWährend Ihr dort drin seid, haltet die Augen offen, ob Ihr noch weitere Informationen findet, was die Horde dort in den Minen treibt.\n\nViel Glück.", sourceObjective = "Tötet 6 Vorarbeiter der Scherwindmine.", completion = "Gute Arbeit, ich konnte ihre schrillen Schreie von hier aus hören! Ihr habt den ganzen Ort auf den Kopf gestellt!\n\nHabt Ihr noch weitere Informationen über die Vorgänge in der Mine gefunden?", sourceObjectiveStatus = "unverified-source-field" }
quests[25647] = { id = 25647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unleserlicher Orcbrief", description = "Ihr habt ein Pergament mit einem beeindruckenden Hordensiegel darauf gefunden. Leider ist der Rest des Dokuments vollkommen unverständlich, weil es auf Orcisch ist.\n\nBringt den Brief zu Boog. Vielleicht weiß er etwas damit anzufangen!", sourceObjective = "Bringt den unleserlichen Orcbrief zu Boog dem \"Zahnradflüsterer\" an der Scherwindmine im Steinkrallengebirge.", progress = "Was habt Ihr da für mich?", completion = "<Boog nimmt Euch den Brief ab und studiert ihn.>\n\nInteressant.\n\n<Boog riecht an dem Pergament.>\n\nHrm... Beunruhigend...\n\n<Boog faltet das Papier auf der Hälfte und schaut Euch an.>\n\nIch verstehe absolut gar nichts von dem, was da geschrieben steht - wenn es überhaupt geschrieben ist. Könnte auch Klopapier sein. Riecht auf jeden Fall so.", sourceObjectiveStatus = "unverified-source-field" }
quests[25648] = { id = 25648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jenseits von Durotar", description = "Hmpfff... Eure Dienste werden anscheinend anderswo benötigt. Ag'tor Blutfaust sucht nach Rekruten, die die Unternehmungen der Horde in Azshara nördlich von Orgrimmar unterstützen.\n\nIhr habt sicherlich noch Arbeit hier in Durotar und ich hörte, dass man Euch bald um Hilfe im Brachland bitten wird. Also ich an Eurer Stelle würde nirgendwo hingehen, aber wenn Ihr unbedingt das Schicksal herausfordern wollt... Azshara wartet.", sourceObjective = "Meldet Euch bei Ag'tor Blutfaust am Hinteren Tor von Orgrimmar in Azshara.", completion = "Gut, Ihr seid hier. Willkommen in Azshara, der Bühne für den nächsten Akt der ruhmreichen Zukunft der Horde. Und jetzt an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25649] = { id = 25649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minx wird's schon richten", description = "Die gute Nachricht ist, dass Minx fließend Orcisch spricht und sie ist in der Nähe. Geht zurück in die Mine und findet sie. Sie ist wahrscheinlich etwas tiefer in der Mine und steht nutzlos herum.\n\nVergesst das Pergament nicht.", sourceObjective = "Bringt den unleserlichen Orcbrief zu Minx in der Scherwindmine im Steinkrallengebirge.", progress = "Was habt Ihr da für mich?", completion = "<Minx nimmt Euch den Brief ab und studiert ihn.>\n\nOha.\n\n<Minx riecht an dem Pergament.>\n\nIst ja widerlich!\n\n<Minx faltet das Papier auf der Hälfte und schaut Euch an.>\n\nDie gute Nachricht ist - es ist kein Klopapier. Die schlechte Nachricht ist, dass die Tinte auf diesem Papier eine Mischung aus Kododung und Blut ist. Und das ist noch nicht das Schlimmste...", sourceObjectiveStatus = "unverified-source-field" }
quests[25650] = { id = 25650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehle des Oberkommandos", description = "Bei dem Brief handelt es sich um Befehle des Hordenoberkommandos. Jemand mit Namen Oberanführer Krom'gar hat angeordnet, dass diese Mine \"ausgeräumt\" werden soll, um einen Splitter von etwas zu erhalten, das \"azurblaues Eisenerz\" heißt. Wahrscheinlich erhält man diesen Splitter, wenn man das Erz abbaut.\n\nEs wird noch schlimmer. Sie haben vor, diesen azurblauen Splitter mit Sprengstoffen in der riesigen Bombe zu vermischen und dann die Scherwindfeste in die Luft zu jagen.\n\nWir dürfen keine Zeit mehr verlieren, {name}! Nehmt diese Übersetzung des Briefs und kehrt zu Boog zurück! Er wird wissen, was als Nächstes zu tun ist.", sourceObjective = "Bringt den übersetzten Orcbrief zu Boog dem \"Zahnradflüsterer\" an der Scherwindmine im Steinkrallengebirge.", progress = "Nun? Was steht da?", completion = "<Schweißperlen laufen Boog über die viel zu große Stirn, während er den übersetzten Brief liest.>\n\nDas ist übel. Richtig, richtig übel. Ihr müsst Lord Brachweiher in der Scherwindfeste warnen.\n\nWas zur…? Er BEWEGT sich! Der Goblinballon hebt ab! Wir kommen zu spät!", sourceObjectiveStatus = "unverified-source-field" }
quests[25651] = { id = 25651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh süßer Wahnsinn!", description = "Also, ich habe nachgedacht…\n\nWenn jemand total durchgeknallt ist, weiß er das dann?\n\nIch könnte zum Beispiel schwören, dass ich ein Fass mit Schießpulver von den Kanonenkugeln hier gesammelt habe, aber es ist einfach unauffindbar.\n\nIch erinnere mich noch genau daran, wie ich die Kanonenkugeln von den Gilblins westlich von hier stibitzt habe.\n\nVielleicht stimmen die Gerüchte ja... vielleicht habe ich wirklich nicht mehr alle Tassen im Schrank.", sourceObjective = "Sammelt 50 gestohlene Kanonenkugeln auf Gurboggels Fels und von Hamsterern der Gilblin. Benutzt die Kanonenkugeln, um ein Fass mit Schießpulver herzustellen.", progress = "Ihr wollt nichts mit mir zu tun haben, {race}.\n\nIch bin ein bisschen… meschugge.", completion = "Mein Schießpulver!\n\nIhr habt es gefunden! Ich bin also doch nicht verrückt!", sourceObjectiveStatus = "unverified-source-field" }
quests[25652] = { id = 25652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschlagnahmt den Ballon!", description = "Wir dürfen keine Zeit verlieren, {name}. Ihr müsst diesen Heißluftballon beschlagnahmen und aufhalten!\n\nWie? Keine Ahnung! Wir haben keine Zeit, uns um Details zu streiten! Schnappt Euch die Strickleiter und klettert hinauf! Dann prügelt einfach auf alles ein, wenn Ihr drin seid!\n\nWenn Ihr den Ballon irgendwie anhalten könnt und überlebt, meldet Euch bei Lord Brachweiher in der Scherwindfeste im Westen.\n\nViel Glück, wir alle zählen auf Euch. Wenn Ihr mich jetzt entschuldigen wollt, ich muss um MEIN LEBEN RENNEN!", sourceObjective = "Fahrt mit dem Heißluftballon von Krom'gar und versucht zu verhindern, dass er die Scherwindfeste zerstört.", completion = "Unglaubliche Geschichte, mein Freund. Wenn ich es nicht mit eigenen Augen gesehen hätte, würde ich Euch nicht glauben. Ihr habt dem Ballon so viel Schaden zu gefügt, dass Ihr diese Unholde zum Rückzug gezwungen habt! Leider ist die Bedrohung noch längst nicht abgewendet! Wir haben den Angriff nur hinausgezögert. Es gibt noch viel zu tun, wenn wir die Horde davon abhalten wollen, das Steinkrallengebirge zu zerstören!", sourceObjectiveStatus = "unverified-source-field" }
quests[25653] = { id = 25653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ahnen sind mit uns", description = "Nemesis… vernichtet.\n\nIch fühle mich jung.\nMächtig.\nErleuchtet.\n\nSagt Ysera, dass meine Stärke ganz ihr gehört.\n\nDer Schattenhammer wird fallen.", sourceObjective = "Kehrt zu Ysera in Nordrassil auf dem Hyjal zurück.", completion = "Indem Ihr Tortolla von seiner letzten Last befreit habt, habt Ihr uns einen ausgezeichneten Verbündeten verschafft… und das letzte Stück unseres Plans.\n\nMacht Euch bereit, {name}. Der schwierigste Teil unserer Reise steht kurz bevor.\n\nWir werden den Kampf in ihre Feste tragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25654] = { id = 25654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkles Herz", description = "Edana Hasskralle ist die Königin der Harpyien der Nordschwingen, die in den Ruinen westlich von hier leben. Es ist ihr bösartiger Wille, der die Harpyien dazu anregt, ihre Nester inmitten der Ruinen unseres Volkes zu verteidigen.\n\nDie Harpyien können sie mit einem speziellen Horn rufen. Wenn man das Horn bei den Hasskrallensteinen im nördlichen Teil der Ruinen bläst, so erscheint Edana.\n\nZeigt diesen garstigen Kreaturen keine Gnade. Tötet Edana, und bringt mir ihr dunkles Herz.", sourceObjective = "Tötet Edana Hasskralle und erhaltet Edanas dunkles Herz.", progress = "Wir dürfen den Einfall der Harpyien in die Ruinen unserer Vorfahren nicht einfach hinnehmen.", completion = "Diese Länder werden endlich von der Bosheit der Harpyien befreit sein. Ich kann Euch nicht genug danken.", sourceObjectiveStatus = "unverified-source-field" }
quests[25655] = { id = 25655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wurmschwingenproblem", description = "Himmelsfürst Omnuron war viel zu nachgiebig mit den Harpyien der Wurmschwingen und hat ihnen sogar gestattet, sich auf diesem Berg niederzulassen. Einfach nur, weil es Wesen der Luft sind. Nun, {class}, nicht alle Wesen der Luft sind gleichrangig.\n\nAls die Angriffe auf den Hyjal begannen, verfielen die Wurmschwingen in Raserei. Sie sind direkt dort oben und greifen einen heiligen Schrein an, den sie einst verehrten.\n\nAber kein Grund zur Klage. Schließlich haben wir jetzt einen Grund, sie vom Hyjal zu vertreiben, oder?", sourceObjective = "Tötet 10 Harpyien der Wurmschwingen (Kreischerinnen oder Schnellklauen).", completion = "<Thisalee nickt zufrieden und ihre Augen leuchten.>\n\nEs ist großartig, nicht mehr an der kurzen Leine gehalten zu werden, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[25656] = { id = 25656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augen auf beim Eierklau", description = "Hinter diesen Angriffen der Wurmschwingen steckt ein Muster. Während einige Gruppen einen aufsehenerregenden Angriff auf den Schrein selbst durchführen, durchforsten andere die Nester in der Nähe und machen sich mit den Eiern aller fliegenden Wesen des Hyjal aus dem Staub.\n\nDiese Tiere stehen unter unserem Schutz. Bis wir herausgefunden haben, warum die Wurmschwingen das tun, müssen wir so viele Eier wie möglich vor ihren Klauen retten.", sourceObjective = "Sammelt 8 Hyjaleier.", progress = "<Thisalee säubert ihre Fingernägel mit einem Dolch. Sie schaut Euch erwartungsvoll an.>", completion = "Gut, das ist zumindest ein Anfang.\n\nDie Vögel, die diese Eier gelegt haben, werden sie nicht wieder annehmen. Wir werden die Küken als Waisen im Schrein aufziehen müssen. Wenn Aviana hier wäre, hätte sie diese Schandtat nie zugelassen.\n\nAber zurück zum Geschäft...", sourceObjectiveStatus = "unverified-source-field" }
quests[25657] = { id = 25657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da dap… Da dap...", description = "Da Ihr so nett zu mir wart, werde ich Euch in ein ganz besonderes Geheimnis einweihen.\n\nIch habe den größten Glitzerkram von allen gefunden, keine 50 Schritt von uns entfernt!\n\nNur eines steht noch zwischen Euch, mir und einem großen Vermögen, und das ist Nager.\n\nAber keine Sorge, ich habe einen Plan.\n\nNager liebt Maden, also habe ich eine davon mit Schießpulver gefüllt, als Falle sozusagen. Versteht Ihr?\n\nLasst sie einfach im Riff vor sich hin treiben. Sobald der Hai tot ist, sind wir reich!", sourceObjective = "Budd möchte, dass Ihr den präparierten Köder bei der rostigen Harpunenkanone im Skelettriff benutzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25658] = { id = 25658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Ewigkeit gebaut", description = "Herrin, ich habe eine Bitte der Hohepriesterin, die ich an Euch weitergeben soll. Viele der Verteidigungsanlagen der Stadt stammen noch aus der Zeit, lange bevor sie in den Wellen versank. Sie erneut zu aktivieren ist nicht schwer, wären da nicht die zahllosen Kvaldir, die uns im Weg sind.\n\nEs wurde uns berichtet, dass Ihr oben auf der Terrasse von Nar'shola kämpfen werdet. Ihr würdet meiner Herrin einen großen Dienst erweisen, wenn Ihr im Vorbeigehen diese Geräte einfach berühren könntet. Euer edles Geblüt sollte mehr als ausreichen, um sie zu reaktivieren.", sourceObjective = "Reaktiviert 6 Barrieren von Nar'shola.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", completion = "Die Barrieren von Nar'shola funktionieren einwandfrei. Ich werde die Herrin der Gezeiten sofort über Eure Hilfe informieren.\n\nVielen Dank, edle Dame.", sourceObjectiveStatus = "unverified-source-field" }
quests[25659] = { id = 25659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unvergesslich", description = "Der Anführer der Kvaldir hat sein verrottendes, hässliches Gesicht nicht weit von hier den westlichen Gang entlang gezeigt. Wenn wir ihn jetzt töten, findet die Belagerung unserer geliebten Stadt durch die Kvaldir endlich ein Ende.\n\nVorsicht, Kriegsmaid, denn er ist alles andere als ein Schwächling. Es stehen viele Kvaldir unter seinem Befehl. Einige Meerhexen der Sira'kess wurden losgeschickt, um ihn während Eures Angriffs zu schwächen, aber wenn Ihr zulasst, dass seine Kvaldir sie angreifen, werden sie unterbrochen.\n\nZeigt keine Gnade, Kriegsmaid.", sourceObjective = "Tötet Varkul den Unerbittlichen.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", progress = "Euer Feind wartet direkt den Gang entlang auf Euch. Geht und bringt ihm den Tod.", completion = "<Der General der Kvaldir bricht besiegt zusammen.>\n\n<Damit hat Lady Naz'jar die Ruinen von Vashj'ir erobert. Ihre eigentlichen Ziele kennt Ihr nicht, aber es ist klar, dass die Naga aus einem bestimmten Grund hierhergekommen sind.>\n\n<Ihr seid Euch sicher, dass der Schlüssel zum Sieg über die Naga in dieser Vision liegt. Wenn Ihr weitermachen könntet, würdet Ihr sicher die Antworten finden, aber die Magie der Wellensprecherin wird schwächer und Ihr verliert die Verbindung zur Kriegsmaid.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25660] = { id = 25660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgt", description = "Ihr meint wohl, ich lasse Euch für meinen Tod einfach so gehen, hm? Sicherlich nicht! Ich habe mein Piratenhandelsimperium mit nichts nicht aufgebaut, um Euch dabei zuzusehen, wie Ihr mich tötet.\n\nIhr werdet mir dabei helfen, wieder zum Leben zu finden. Findet meine Exfrau Ajamon im Norden des Stützpunkts. Immer der Nase nach - sie wird mit Sicherheit bei dem stinkenden Kessel sein.", sourceObjective = "Sprecht mit Ajamon Geistrufer in Südmeerstützpunkt in Tausend Nadeln.", completion = "Was wollt Ihr denn? Oh nein, ganz sicher nicht. Ich sehe, dass Ihr Tonys Geist bei Euch habt, und damit will ich wirklich nichts zu tun haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[25661] = { id = 25661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit ein bisschen Hilfe...", description = "Nun gut, ich werd' Euch helfen. So leicht wird er nicht darum kommen, mir Alimente zu zahlen! Un' außerdem muss er sich ja bald auch noch um das Kind kümmern, das er mit meiner Schwester zeugen musste!\n\nZuers' brauchen wir die Innereien seiner besten Freunde; das sind wohl die Kapitäne.\n\nGeht und stattet den drei einen Besuch ab.", sourceObjective = "Erhaltet Gruseldollys Herz, Seebär Fajardos Lungen und Lilly Landrattes Leber.", progress = "Wir brauchen ein frisches Herz, Lungen, und eine Leber. Die von seinen Kapitänen werden wohl ausreichen müssen, obwohl sie sicher nicht die frischsten sind.", completion = "<Ajamon verzieht ihr Gesicht, als sie sieht, in welchem Zustand die Organe sind.>\n\nEs geht wohl nicht anders. Ist ja nicht so, als hätte er viele Freunde gehabt. Nicht wahr, Zweihauer?", sourceObjectiveStatus = "unverified-source-field" }
quests[25662] = { id = 25662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreit unsere Schwestern", description = "Gestern Morgen habe ich eine Schwadron Jägerinnen auf eine Mission zur Scherwindklippe geschickt, damit sie Informationen über die Bewegungen der Horde im Steinkrallengebirge beschaffen. Nach Geheimdienstinformationen sind sie alle gefangen genommen worden, einschließlich der Schwadronsführerin, Jägerin Illiona.\n\nGeht nach Osten zur Scherwindklippe und tötet Infanteristen von Krom'gar, die die Klippe eingenommen haben. Nehmt ihnen die Schlüssel ab, mit denen man die Hordenkäfige, in denen unsere Schwestern sitzen, öffnen kann.\n\nTut Euer Bestes, um Illiona zu finden, sobald Ihr die Jägerinnen befreit habt.", sourceObjective = "Bringt 5 Käfigschlüssel der Horde an Euch, um 5 gefangene Jägerinnen freizulassen.", completion = "Wir haben nicht viel Zeit. Um mich hier herauszuholen, müsst Ihr Kriegsfürst Roktrog ausschalten. Er hat den Schlüssel für dieses Gefängnis.", sourceObjectiveStatus = "unverified-source-field" }
quests[25663] = { id = 25663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Gabe für Aviana", description = "Obwohl die Wächterin aller geflügelten Wesen nicht mehr körperlich unter uns weilt, höre ich sie manchmal in den rauschenden Blättern flüstern.\n\n{name}, wir verlangen viel von Euch, um diesen Berg zu beschützen. Doch bevor Ihr weitermacht, nehmt Euch einen Augenblick Zeit für die Andacht.\n\nBringt diese Nektargabe zu Avianas Grabkreis, einem Steinkreis direkt jenseits des Haupteingangs zum Schrein. Vielleicht helfen ein paar Augenblicke alleine mit der Erinnerung an Aviana Euch dabei, Euren Geist zu schärfen.", sourceObjective = "Benutzt den heiligen Nektar an Avianas Grabkreis.", progress = "<Der Geist erscheint immer wieder in Eurer Vision und verschwindet gleich darauf, als ob er hier und gleichzeitig woanders wäre.>", completion = "<Ein geflüstertes Flehen ertönt in Eurem Kopf.>\n\nWieder geboren zu werden, aber in Dunkelheit…\n\nIch wurde geraubt.\n\n<Der Geist scheint aufgewühlt, wird jedoch stumm, als das Bild wieder schwindet.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25664] = { id = 25664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gebet und ein Flügel", description = "Ein Gesicht mit Schwingen? Kann es etwa sein…?\n\n{name}, wir haben keine Zeit zu verlieren. Vielleicht habt Ihr mit Aviana selbst gesprochen, die versucht, zu uns zurückzukehren.\n\nIch benötige etwas aus Avianas Vergangenheit, um mit ihr Kontakt aufnehmen zu können. Hoch oben auf dem Gebirgskamm, der diesen Schrein überblickt, findet Ihr eine Reihe von riesigen Nestern. Sie gehören Blaithe, einem uralten Raubvogel, der einst ihr Gefährte war. Seit zehntausend Jahren vergeht er vor Kummer und hat dadurch seinen Verstand verloren.\n\nKlettert auf einen seiner Horste und benutzt diesen Lockruf, um ihn herbeizurufen. Tötet Blaithe und bringt mir eine seiner Federn.", sourceObjective = "Benutzt den riesigen Vogellockruf an einem von Blaithes Nestern oben am Rand der Welt. Tötet Blaithe und sammelt eine seiner uralten Federn.", progress = "Habt kein schlechtes Gewissen wegen Blaithes Verfassung. Der Kummer hat diesem Wesen vor Jahrhunderten die Seele geraubt. Er war nur noch ein Schatten seiner selbst, eine Bestie voll zügellosen Zorns.", completion = "Das war keine schöne Aufgabe, {name}, aber sie musste erledigt werden.\n\nWenn Aviana wirklich wieder zum Leben erweckt werden kann, kann Blaithe vielleicht eines Tages Dank Eurer Taten auch zurückkehren.\n\nUnd jetzt lasst uns sehen, ob wir mit unserer lange verlorenen Wächterin Kontakt aufnehmen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[25665] = { id = 25665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gesuch aus dem Jenseits", description = "<Ihr versteht nicht, worum der Geist Euch so dringend anfleht, aber vielleicht kann Choluna ja herausfinden, was hier vor sich geht.>\n\n<Sprecht mit Choluna innerhalb des Schreins!>", sourceObjective = "Kehrt zu Choluna im Schrein von Aviana auf dem Hyjal zurück.", completion = "Langsam, {class}! Ihr seht aus, als hättet Ihr einen Geist gesehen…", sourceObjectiveStatus = "unverified-source-field" }
quests[25666] = { id = 25666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht Euch die Hände schmutzig", description = "Lasst Euch nicht täuschen, {race}. Dieser Hai ist ganz schön gewitzt. Man überlebt hier unten nicht so lange, wenn man nicht das gewisse Etwas an Grips hat.\n\nIch will damit nur sagen, dass er sich sicher nicht so leicht reinlegen lässt. Wir müssen unseren Ansatz ein wenig überdenken.\n\nIch werde Euch jetzt noch nicht mit Details langweilen. Sammelt zunächst ein paar Innereien von diesen gigantischen Meeresraupen.\n\nMeint Ihr, Ihr schafft das?", sourceObjective = "Sammelt 5 schmierige Madeneingeweide von gigantischen Meeresraupen in der Nähe von Harrisons Ausgrabung.", sourceObjectiveStatus = "unverified-source-field" }
quests[25667] = { id = 25667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wendigos erlegen", description = "Die Wendigos im Graufelsbau südwestlich der Stadt sind uns schon lange ein Dorn im Auge. Ihre Kraft reicht zwar nicht aus, Kharanos direkt zu bedrohen, aber sie stellen Reisenden, Gebirgsjägerpatrouillen und Nachschubtransporten nach.\n\nIch werde meine Beobachter aus dem Graufelsbau abziehen, da ich sie an der Trollfront brauche. Würde es Euch etwas ausmachen, meinen Leuten bei der Verkleinerung des Wendigobestands zu helfen? Wenn sie nicht mehr so viele sind, können sie uns nicht länger angreifen.", sourceObjective = "Tötet 10 Wendigos im Graufelsbau. Ihr könnt Wendigos oder junge Wendigos töten.", completion = "Jetzt, da Ihr Euch um die Wendigos gekümmert habt, können wir unsere Bemühungen auf die Trolle der Frostmähnen im Osten konzentrieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[25668] = { id = 25668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlene Vorräte", description = "Die Frostmähnen machen im Osten Ärger und die Wendigos spüren unsere Schwäche und werden mit ihren Überfällen immer dreister. Nur einer von vier Nachschubkarren ist in letzter Zeit hier sicher angekommen. Die Wendigos haben sich mit dem Rest davongemacht und bewahren alles im Graufelsbau, einer Höhle südwestlich von hier, auf. Wenn Ihr bereit seid, dorthin zu gehen und die gestohlenen Vorräte wiederzubeschaffen, wären Euch alle Einwohner der Stadt und die Gebirgsjäger, die Kharanos verteidigen, zutiefst dankbar.", sourceObjective = "Bergt 6 gestohlene Versorgungsgüter aus dem Graufelsbau.", progress = "Habt Ihr etwas von den vermissten Vorräten gefunden?", completion = "Gut gemacht, {name}. Die Gebirgsjäger werden froh sein zu hören, dass die halben Rationen der Vergangenheit angehören. Sie benötigen all ihre Kräfte, um gegen die Frostmähnen zu kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25669] = { id = 25669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es rappelt im Säge... Werk", description = "Seid bereit, {name}! Der Kriegsfürst kommt! Tötet ihn und nehmt seinen Schlüssel an Euch. Benutzt diesen Schlüssel, um mich freizulassen.\n\nWenn wir es hier heraus schaffen, meldet das Folgende bei Lord Brachweiher in der Scherwindfeste:\n\nDie Horde hat ihre Pläne, die Scherwindfeste zu zerstören, dank der Taten eines unserer Helden abgebrochen. Jetzt beabsichtigen sie, die Bombe zum Kriegsnarbental zu bringen und auf unsere Armeen abzuwerfen, die dort gegen die Horde kämpfen.\n\nSie müssen aufgehalten werden!", sourceObjective = "Tötet Kriegsfürst Roktrog und befreit Jägerin Illiona, indem Ihr Jägerin Illionas Käfigschlüssel benutzt.", completion = "Ein Held hat also ihre Pläne vereitelt, die Scherwindfeste zu zerstören, huh? Der Held wart Ihr, {name}. Ihr seid der Stolz der Allianz!\n\nAnscheinend habt Ihr uns allen ein wenig Zeit verschafft. Ich muss Pläne schmieden für den Kampf, der vor uns liegt. Geht zu den anderen Einwohnern der Scherwindfeste und bietet ihnen Eure Dienste an. Ich werde Euch rufen, wenn ich bereit bin, unsere Verteidigungsstrategie ins Leben zu rufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25670] = { id = 25670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DA-dap-DA-dap-DA-dap", description = "Der alte Nager ist uns jetzt sicher auf den Fersen.\n\nZu Eurem Glück denke ich wie ein Hai.\n\nNager kocht vor Zorn und wir werden das zu unserem Vorteil nutzen.\n\nHier, ich habe auf meiner Schatzjagd diese Kette gefunden. Bindet sie an die Harpunenkanone.\n\nWenn Nager Euch sieht, wird er bestimmt vor Wut überschnappen. Und dann schlagen wir zu!\n\nIhr versucht, ihn alle zu machen und ich schleiche mich währenddessen dort hinein und schnappe mir den Glitzerkram.\n\nSchnell, {class}, bevor seine Zähne wieder nachwachsen!", sourceObjective = "Benutzt Budds Kette bei der rostigen Harpunenkanone im Skelettriff. Feuert die Harpune ab, wenn Nager sich über der Kanone befindet.", completion = "Es ist wirklich nicht so schlimm, wie es aussieht…", sourceObjectiveStatus = "unverified-source-field" }
quests[25671] = { id = 25671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde ausdünnen", description = "Die Zahl der Horde wächst, da Verstärkung aus dem Eschental und aus Azshara eintrifft. Diplomatie bringt bei diesen Unholden nichts. Das ist Höllschreis Horde und Höllschreis Horde will unser Blut! Wir werden nicht untätig herumsitzen und zulassen, dass sie unser Land einnehmen und unsere Leute töten. Wir müssen handeln!\n\nWir müssen die Horde ausdünnen! Betrachtet das als Eure tägliche Pflicht.\n\nGeht hinaus ins Steinkrallengebirge und tötet so viele Hordemitglieder, wie Ihr könnt. Zeigt ihnen, dass die Allianz sich nicht ergeben wird!", sourceObjective = "Tötet 20 beliebige Soldaten der Horde im Steinkrallengebirge.", completion = "Gut. Ihr Blut klebt an Höllschreis Händen. Schickt genug von ihnen in Leichensäcken zurück nach Orgrimmar und die Bevölkerung der Horde wird vielleicht reagieren.\n\n<Lord Brachweiher lacht.>\n\nWem will ich etwas vormachen? Sie sind Monster!", sourceObjectiveStatus = "unverified-source-field" }
quests[25672] = { id = 25672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kadaversammlung", description = "Diese Organe hier sind schon mal ein guter Anfang, aber wir brauchen echt noch viel mehr anderes Zeugs. Normalerweise könnte man von der Familie was nehmen, aber es sind nur noch ich und Tony, der Sohn meiner Schwester übrig, und er ist es echt nicht wert!\n\nWir müssen also 'n Ersatz finden - 'ne Menge Kadaver, um genau zu sein!\n\nUnten in der Schimmernden Tiefe sind tonnenweise welche zu finden; die sind da, seit das Wasser alles überflutet hat. Hat alle Kreaturen dort getötet, das Wasser. Geht dorthin und bringt mir ein paar der Kadaver.", sourceObjective = "Sammelt 10 Kreaturenkadaver.", progress = "Mensch, Ihr müsst mir end viele von den Kadavern bringen! Sonst werden wir seinen törichten Geist nie loswerden!", completion = "Oh, das is' widerlich!\n\nAber wenigstens haben wir's bald. Nur noch eine Kleinigkeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[25673] = { id = 25673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfach Alice fragen", description = "Herr Baunzer ist krank, <Onkel/Tante>. Kannst du ihm helfen? Du musst nur seinen Hut und seine Batterien finden, dann wird es ihm viel besser gehen. Ich würde sie ja selbst holen, aber ich kann Herrn Baunzer nicht alleine lassen!\n\nSein Hut wurde von den fiesen Typen der Venture Co. drüben am Wasserrad gestohlen und seine Batterien sind irgendwo in der Scherwindklippe versteckt. Du musst nur sehr gründlich nach ihnen suchen.\n\nWürdest du freundlicherweise Herrn Baunzers Sachen zurückholen, damit er den Fieslingen in der Horde eine Lektion erteilen kann?", sourceObjective = "Findet die BD-816 Kriegsmaschine, mechanisiertes Feuer, mechanisiertes Eis und mechanisierte Luft.", progress = "Herr Baunzer ist so traurig. Wir müssen ihn glücklich machen!", completion = "<Alice klatscht aufgeregt in die Hände.>\n\nHerr Baunzer, alles wird wieder gut! Hurrah!\n\n<Alice setzt fachmännisch alle Teile, die Ihr eingesammelt habt, in Baunzer ein.>\n\nOh, Herr Baunzer! Ich wusste es!", sourceObjectiveStatus = "unverified-source-field" }
quests[25674] = { id = 25674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergebener Stolz", description = "Dies hier ist eigentlich eine alte Orcstadt... eine der ältesten in Azeroth. Also, das war sie - bis die Oger uns hinausgedrängt haben.\n\nDie heutige Horde weigert sich, von Ogern besiegt zu werden. Meine Truppen und ich haben die Stadt mit Gewalt eingenommen und die Oger, die einmal hier gelebt haben, arbeiten jetzt als Sklaven. Jetzt fängt die Arbeit erst richtig an.\n\nIhr seht stark genug aus, aber ich will Beweise. Tötet einen der Oger, die uns immer noch belagern und kehrt zu mir zurück.", sourceObjective = "Tötet einen Wegelagerer der Schreckensfelsoger in der Feste Schreckensfels.", completion = "Gut gemacht, {race}. Ihr habt bewiesen, dass Ihr einen Oger niederstrecken könnt...eine beachtliche Leistung. Jetzt lasst uns doch mal sehen, ob Ihr eine Eisenmine der Allianz ebenfalls ausschalten könnt...", sourceObjectiveStatus = "unverified-source-field" }
quests[25675] = { id = 25675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogergefechte", description = "Ich habe Eure Handschrift da unten gesehen, {race}. Wie würde es Euch gefallen, noch weitere Oger zu jagen?\n\nWir haben nur diejenigen versklavt, derer wir habhaft werden konnten. Die meisten starken Oger brüten immer noch im Schreckensfelsposten und planen unser Ableben. Unsere Wachen können vereinzelte Angriffe aus dem Hinterhalt abwehren, aber wir haben uns noch nicht gut genug verschanzt und würden unter einem gut geführten Angriff schnell zusammenbrechen.\n\nGeht nach Süden zum Schreckensfelsposten und überbringt eine Nachricht, {name}. Tötet die stärksten Oger, bevor sie auf dumme Gedanken kommen.", sourceObjective = "Tötet 6 Raufer der Schreckensfelsoger und 5 Hexenmeister der Schreckensfelsoger.", completion = "Ihr habt Eure Sache heute gut gemacht, {name}. Ihr habt uns nicht nur Zeit bis zum nächsten Ogerangriff verschafft, sondern auch einige der Gefangenen eingeschüchtert, sodass sie jetzt härter arbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25676] = { id = 25676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitten ins Herz", description = "Wir haben keine Hoffnung, die Mine von Nethergarde von der Allianz zurückerobern zu können... wenigstens noch nicht. Nethergarde wird gut verteidigt und ihre Nachschubrouten sind bewährt und stark. Unser Ziel ist es daher, ihrer Wirtschaft zu schaden. Wir können die Mine nicht mit Gewalt einnehmen, aber mit präzisen Einschnitten können wir die Wirtschaftlichkeit der Mine stark einschränken.\n\nIch werde dafür sorgen, dass meine Leute vor der Mine ein Ablenkungsmanöver ausführen. Geht nach Osten, schleicht Euch in die Mine und sprecht mit Rofilian Dane über Eure Rolle.", sourceObjective = "Meldet Euch bei Rofilian Dane in der Mine von Nethergarde in den Verwüsteten Landen.", completion = "Endlich lässt sich hier mal ein Verantwortlicher blicken. Ich hoffe, Ihr habt Euch locker gemacht... Zeit für ein kleines Tänzchen, Partner.", sourceObjectiveStatus = "unverified-source-field" }
quests[25677] = { id = 25677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles meins!", description = "Überall in dieser Höhle findet Ihr unbewachte Erzhaufen, die nur darauf warten, dass man an ihnen herumpfuscht. Am liebsten würden wir das Erz natürlich stehlen, aber dazu benötigt man Minenwagen, Schutz und Arbeiter - drei Dinge, die wir nicht haben. Also werden wir stattdessen die Schürfarbeiten mit ein wenig hochgradig ätzender Säure vereiteln.\n\nNehmt diese Flasche - VORSICHTIG - und träufelt den Inhalt auf diese Erzhaufen. Denn wenn wir das Erz nicht haben können, sollen sie es auch nicht haben.", sourceObjective = "Benutzt das konzentrierte Lösemittel auf 6 Erzhaufen in der Mine von Nethergarde.", completion = "Es gibt doch nichts Besseres, als einen richtig fetten Tritt in die Geldbörse, nicht wahr, ihr Allianzdummköpfe?!", sourceObjectiveStatus = "unverified-source-field" }
quests[25678] = { id = 25678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wählt Euer Schicksal", description = "Es kostet die Allianz ungefähr fünfzig Goldstücke, einen Minenarbeiter auszubilden, zweihundert, um einen Ingenieur auszubilden und dreihundert für einen Vorarbeiter. Jeder Allianzdummkopf, den wir töten ist nicht nur ein militärischer Sieg, es ist auch ein finanzieller Sieg.\n\nJetzt geht dort hinunter und vernichtet ihre Arbeiter!", sourceObjective = "Tötet 8 Minenarbeiter von Nethergarde, 3 Ingenieure von Nethergarde und 3 Großknechte von Nethergarde.", completion = "Hervorragende Arbeit Mir gefällt, wie Ihr an die Dinge herangeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25679] = { id = 25679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Berg hinein", description = "Die nächste Phase findet an einem noch tiefer gelegenen Ort in der Mine statt. Sprecht mit Tak'arili für Eure nächste Aufgabe. Folgt einfach den Schienen der Minenwagen nach Südosten um die Kurve herum. Ihr werdet ihn am Eingang zu den höher gelegenen Kammern der Mine sehen.\n\nEs war mir ein Vergnügen, mit Euch Geschäfte zu machen, {name}", sourceObjective = "Meldet Euch bei Tak'arili tiefer in der Mine von Nethergarde in den Verwüsteten Landen.", completion = "Gut, Ihr seid schon hier. Bleibt eine Weile, kleiner {race}. Wir werden mit der Allianz ein paar Spielchen treiben.\n\nIch liebe meinen Job, Mann.", sourceObjectiveStatus = "unverified-source-field" }
quests[25680] = { id = 25680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So sind wir nicht", description = "Das Wichtigste zuerst... sieht so aus, als ob wir ein Problem hätten. Die Minenarbeiter in dem Stollen rechts laufen herum wie ein Haufen aufgescheuchter, kopfloser Hühner. Ich kann nur vermuten, dass sie zu tief gegraben und etwas Unschönes gefunden haben... einen Dämon, ein Elementar oder irgendein Tentakelbiest.\n\nTak'arili mag keine Überraschungen. Findet heraus, was das Problem ist und kümmert Euch darum, dann können wir wie geplant weitermachen.", sourceObjective = "Findet und tötet das, was die Minenarbeiter in der Mine von Nethergarde so erschreckt hat.", completion = "Also war es ein Dämon? Diese Minenarbeiter haben noch nie einen Dämonen gesehen? Wir sind in den Verwüstete Landen, Mann! Dämonen sind überall!\n\n<Tak'arili seufzt.>\n\nNaja... wenden wir uns dem guten Zeug zu, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[25681] = { id = 25681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einige Leute muss man einfach töten", description = "Wenn Ihr durch den Tunnel vor uns geht, der nach Westen führt, kommt Ihr direkt zum Büro von Chefausgrabungsleiter Hondo. Er ist hier der Obermotz und Tak'arili hat gehört, dass er ein richtig guter Minenarbeiter ist. Deshalb muss er sterben.\n\nEs gibt nur ein Problem: der Weg dorthin ist VOLL mit diesen lästigen Lakaien aus Nethergarde. Deshalb müsst Ihr Euch verkleiden. Hüpft in diese Kiste hier und schleicht Euch den Weg hinunter. Hoffentlich erregt Ihr nicht zu viel Verdacht auf dem Weg zu Eurem Opfer.", sourceObjective = "Tötet Chefausgrabungsleiter Hondo. Benutzt die unverdächtige Kiste, um Euch unterwegs zu tarnen.", completion = "Gute Arbeit, Mann! Ohne Hondo sind die Jungs hilflos. Die Mine wird schon bald uns gehören!", sourceObjectiveStatus = "unverified-source-field" }
quests[25682] = { id = 25682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission abgeschlossen", description = "Wir sind hier fertig, Mann. Wir müssen nur noch einen Bericht an Okrilla schicken. Habt Ihr gerade etwas vor?", sourceObjective = "Liefert den Minenbericht von Nethergarde bei Okrilla in der Feste Schreckensfels in den Verwüsteten Landen ab.", progress = "Ihr seid zurückgekehrt, {name}?", completion = "<Okrilla überfliegt den Bericht.>\n\nBeeindruckend, {name}. Ich hätte mich zwar nicht in dieser Kiste versteckt, aber sonst habt Ihr Eure Sache tapfer und bewundernswert gemacht. Die Schlacht, die wir heute gewonnen haben, wird uns nicht unmittelbar zugutekommen, aber der Schaden, den Ihr der Allianz zugefügt habt, wird über lange Zeit anhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25683] = { id = 25683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schreckensfelssenke", description = "Ich meinte das, was ich gesagt habe, {race}. Ihr habt mir geholfen, jetzt gebe ich weiter, was ich weiß.\n\nVor Kurzem machte ein Dämonenjäger kurz hier Halt. Er ging nach Süden und sprach von Dämonen. Eigentlich hätte ich den Nachtelfen sofort getötet, aber er schien nicht der übliche Allianzabschaum zu sein und jeder, der Dämonen tötet, ist in dem Moment nützlich für mich.\n\nIhr solltet Euch bei Lynnore und Drazial melden, zwei Blutmagier, die ich in die Richtung entsandt habe. Sie haben ihr Lager hinten in einer Ogerhöhle aufgeschlagen.", sourceObjective = "Meldet Euch bei Blutmagierin Lynnore hinten in der Schreckensfelssenke in den Verwüsteten Landen.", completion = "Okrilla hat Euch geschickt? Okrilla da Killa?\n\n<Lynnore hört sich Eure Geschichte an.>\n\nEr hieß Loramus? Es tut mir leid, aber wir haben Euren Dämonenjäger nicht gesehen... Aber wir haben Möglichkeiten, ihn zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25684] = { id = 25684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stimmt den Blutstein ab", description = "Ich gebe zu, dass wir nicht gerade den... vorteilhaftesten Ort für unsere Studien ausgewählt haben, besonders, wenn vorüberziehende Abenteurer den Wunsch haben, unbehelligt einzutreten und wieder hinauszugehen. Unsere Übereinkunft mit den Ogern ist recht wackelig und ich fürchte, wir können sie nicht dazu bewegen, Euch nicht anzugreifen, wenn Ihr Euch nähert.\n\nIch kann Euch allerdings gestatten, Euch mit einem der Blutsteinteleporter zu verbinden. Legt einfach Eure Hände auf den Stein zu meiner Rechten und Ihr werdet aus der Höhle herausteleportiert. Dann benutzt den Stein draußen, um wieder hereinzuteleportieren!", sourceObjective = "Verbindet Euch mit den Blutsteinteleportern in der Schreckensfelssenke.", completion = "Ausgezeichnet. Jetzt, da das aus dem Weg ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[25685] = { id = 25685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der erste Schritt", description = "Damit wir das Ritual, um das Ihr gebeten habt, durchführen können - und vielleicht noch weitere Rituale in Zukunft - benötigen wir Blut. Die Verwüsteten Lande sind voller Reagenzien, die wir für unsere Blutmagie brauchen... es ist nur eine Frage der richtigen Zusammenstellung.\n\n<Lynnore berät sich schnell und kurz mit Drazial.>\n\nBasilisken und Hyänen, zu gleichen Teilen. Und wir benötigen viel davon. Geht nach Osten ins Zentrum der Verwüsteten Lande. Und vergesst nicht - Ihr könnt den Teleporter benutzen!", sourceObjective = "Besorgt 9 Phiolen mit Blut einer Kicherfanghyäne und 9 Phiolen mit Blut eines Rotsteinbasilisken.", progress = "Mit Ogerblut kommt man nicht sehr weit. Habt Ihr es?", completion = "<Lynnore beäugt das Blut hungrig.>\n\nMehr als genug - und immer noch warm! Dann lasst uns das Ritual beginnen, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[25686] = { id = 25686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutritual", description = "Unser Ziel ist es, den Dämonenjäger Loramus Thalipedes zu finden. Lasst mich wissen, wenn Ihr bereit seid, das Blutritual zu beginnen. Dann zieht Euch einen Schritt zurück.", sourceObjective = "Sprecht mit Blutmagierin Lynnore, um das Blutritual zu beginnen.", completion = "Das Blutritual war ein voller Erfolg - ich kann ganz deutlich sehen, wo Loramus sich in diesem Moment befindet. Das heißt, ich kann sehen, wo seine Leichenteile sich befinden...", sourceObjectiveStatus = "unverified-source-field" }
quests[25687] = { id = 25687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht irgendeine Leiche", description = "Loramus Thalipedes ist tot. Nun, das nehme ich zurück... das ist nur eine Annahme meinerseits, aber ich weiß, dass sein Körper in drei Teilen ruht.\n\n<Lynnore denkt kurz nach.>\n\nWenn Ihr mir die drei Teile bringt, haben wir noch eine Chance. Alle drei Teile sind in der Nähe... die Schreckensfelsoger haben sie in ihren Höhlen versteckt. Um genau zu sein ist ein Teil in der Truhe, den Vorsprung hinter mir hinunter...", sourceObjective = "Findet Loramus' Kopf, Loramus' Torso und Loramus' Beine.", progress = "Vertraut mir - egal, was mit Loramus geschehen ist, wir können es beheben. Die Grenzen der Blutmagie sind bisher noch nicht ausgelotet.", completion = "Ich verstehe...ja, damit können wir arbeiten.\n\n<Lynnore schaut auf den Kopf des Nachtelfen.>\n\nLoramus Thalipedes, Dämonenjäger. Ich freue mich darauf, Euch kennenzulernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25688] = { id = 25688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Altar der Stürme", description = "Oben auf den Klippen über unserer gemütlichen Höhle befindet sich ein mächtiger Altar. Ein mächtiger DÄMONISCHER Altar, der von Kultisten bewacht wird, aber dennoch sehr große Kräfte birgt. Wenn Ihr es schafft, ihn zu erreichen, könnt Ihr damit Loramus zu uns zurückbringen.\n\nDer Altar wird wahrscheinlich Euren Bemühungen widerstehen, also müsst Ihr Loramus' Leichnam während des Rituals beschützen. Bringt den Dämonenjäger hinterher zu mir zurück.", sourceObjective = "Bringt Loramus' Leichnam zum Altar der Stürme, dann beschützt ihn während des Rituals.", completion = "Ihr... Ihr seid ein Narr! Was habt Ihr getan?", sourceObjectiveStatus = "unverified-source-field" }
quests[25689] = { id = 25689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zeit ist knapp", description = "Ich jagte einen Dämonen mit Namen Razelikh. Grol, sein Ogerhauptmann, griff mich an. Er hat mich auf dem falschen Fuß erwischt und ich starb - genau wie Grol.\n\nRazelikh hat vor, in die Verwüsteten Lande zurückzukehren und sie mit seinen Dämonen zu überwältigen. Sogar jetzt bereitet er sich darauf vor, seine Legionen zusammenzurufen, damit sie uns auslöschen.\n\n<Der Dämonenjäger zieht schnell eine Rune hervor und übergibt sie Euch.>\n\nBringt das hier zu Wazzik am Dunklen Portal im Südosten. Er wird Euch führen. Schnell! Wir haben nicht viel Zeit!", sourceObjective = "Bringt die disharmonische Rune zu Behüter Wazzik am Dunklen Portal in den Verwüsteten Landen.", progress = "Kenne ich Euch, guter {race}??", completion = "Wie bitte? LORAMUS?!\n\nOh verflixt, sprecht leise, ja? Wenn mein Boss herausfindet, dass ich für Loramus gearbeitet habe, wisst Ihr, wie schnell ich dann auf meinen vier Buchstaben lande?\n\n<Wazzik nimmt Euch die Rune ab, drückt sie gegen seine Brust, schließt seine Augen und nickt.>\n\nNun, Ihr habt nicht gelogen. An die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25690] = { id = 25690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auch Blutmagier müssen essen", description = "Entgegen dem allgemeinen Irrglauben trinken Blutelfen Blutmagier KEIN Blut. Wir essen normale Speisen wie jeder andere auch - etwas, das in der hintersten Ecke einer Ogerfeste schwierig zu bekommen ist.\n\nDie Aschmähneneber im zentralen Tal der Verwüsteten Lande sind zumindest ohne Weiteres essbar, da man ihr Fleisch nicht kochen muss. Würdet Ihr diese Eber jagen und unsere Nahrungsvorräte wieder aufstocken?", sourceObjective = "Besorgt 5 Aschmähnensteaks von Aschmähnenebern in den Verwüsteten Landen.", progress = "Ich bin ausgehungert! Wenn Ihr Euch nicht beeilt, sehe ich mich noch gezwungen, unsere Reagenzien zu trinken.", completion = "Die sind perfekt, {name}. Lynnore und ich werden in den nächsten Tagen gut zu essen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25691] = { id = 25691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verkohlte Granit des Dunklen Portals", description = "Loramus will, dass wir - äh, IHR - Granitsplitter aus den Felsbrocken um das Dunkle Portal herum sammelt. Ich weiß nicht, wofür er die Steine braucht, aber ich habe da so meinen Verdacht und der ist nicht angenehm.\n\nBenutzt diese Spitzhacke und sucht nach kleinen, zutage getretenen Steinen am Rand des Explosionskraters um das Portal.", sourceObjective = "Besorgt 24 verkohlte Granitsplitter.", progress = "Sprecht leise, ja?", completion = "Ich hoffe, das ist es, was er braucht. Wir haben wahrscheinlich nicht mehr die Zeit, dass Ihr noch einmal zurückkehrt und noch mehr schürft.", sourceObjectiveStatus = "unverified-source-field" }
quests[25692] = { id = 25692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das abscheuliche Blut der Dämonen", description = "Thalipedes möchte mehr Blut. Für mich persönlich sieht das Zeug nicht einmal aus wie Blut - eher wie flüssige Verwesung - aber das ist ohne Belang.\n\nZum Glück für Euch ist das Gebiet um das Dunkle Portal voller Dämonen. Höllenbestien, Teufelshunde und Teufelswachen - sie alle haben das, was Ihr benötigt in reichlichen Mengen.", sourceObjective = "Besorgt 7 Flaschen mit abscheulichem Dämonenblut.", progress = "Uff, was stinkt hier so? Seid Ihr das, oder das Blut?", completion = "Ihr habt ohne jeden Zweifel Dämonenblut gefunden.\n\nVon Loramus' Bitte einmal abgesehen, bin ich sicher, dass Dar'toon für Eure Bemühungen sehr dankbar ist. Sie haben schon seit einiger Zeit Schwierigkeiten, mit diesen Ablenkungen der Dämonen zurechtzukommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25693] = { id = 25693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbesserung des Steins", description = "<Wazzik packt die letzten Materialien in ein ordentlich umwickeltes Päckchen.>\n\nDas ist alles, was Loramus von uns verlangt hat. Wenn Ihr ihn seht, denkt daran, ihm zu sagen, dass ich eine große Hilfe war. Ich fürchte, er wird meinen Anteil hieran nicht erkennen.", sourceObjective = "Bringt Wazziks Paket zu Loramus Thalipedes in der Schreckensfelssenke in den Verwüsteten Landen.", progress = "{class}... Ihr kehrt zurück...", completion = "Das reicht. Wenn Ihr Wazzik noch einmal seht, sagt ihm, dass er befriedigend gearbeitet hat. Ich werde dafür sorgen, dass die Blutmagier sich an die Arbeit machen und das Steinmesser des Versiegelns herstellen. Jetzt sind Fragen unnötig. Alles wird sich zu seiner Zeit klären.\n\nSolange sie arbeiten, habe ich eine andere Aufgabe für Euch zu erledigen. Um genau zu sein sind es drei Aufgaben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25694] = { id = 25694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückendeckung", description = "Den einzigen Grund, warum Ihr mich neben Soldaten der Allianz stehen seht, ist der, dass unsere Pflicht unsere Feindschaft überwiegt - und sei es noch so gering. Man hat uns die Aufgabe übertragen, das Dunkle Portal vor unerwünschten Reisenden zu schützen. Der kürzlich aufgetretene Kataklysmus hat uns besonders verwundbar für Angriffe gemacht. Wir haben bereits Berichte über schwarze Drachen in der Gegend gehört...\n\nDa meine Leute sich auf ihre Pflichten konzentrieren müssen, brauchen wir jemanden, der die Dämonen im Zaum hält. Um das Portal herum werdet Ihr drei Hauptleute der Dämonen finden. Tötet sie.", sourceObjective = "Tötet Jarroc Flügelriss, Shahandana und Gomegaz.", completion = "Wir wissen Eure Arbeit zu schätzen, Soldat.\n\n<Der Kriegsfürst lehnt sich zu Euch hinüber und flüstert:>\n\n{race}, wenn Ihr noch interessiert seid, ich habe noch eine kleine Aufgabe für Euch...", sourceObjectiveStatus = "unverified-source-field" }
quests[25695] = { id = 25695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachhut", description = "<Kriegsherr Dar'toon spricht sehr leise.>\n\nIch habe Befehle von... oben... für die Ihr genau der Richtige seid. Ich habe gesehen, dass die Allianz regelmäßig einen Blick in den Stapel Papiere dort auf dem Fass wirft. Ich möchte, dass Ihr Euch diese Papiere anschaut und herausfindet, was sie vorhaben. Meine Pflicht und mein Posten erlauben mir nicht, solch eine fragwürdige Aufgabe durchzuführen - aber Ihr seid ein Neuankömmling und könntet unbemerkt hineinschlüpfen...", sourceObjective = "Untersucht die Pläne der Allianz am Dunklen Portal, ohne erwischt zu werden.", completion = "Ihr seid sicher, dass Euch niemand beobachtet hat? Gut.\n\n<Dar'toon hört aufmerksam Eurem Bericht über die Informationen, die Ihr gesehen habt, zu.>\n\nHmpf... das ist ziemlich harmloses Zeugs. Entweder ist die Allianz dumm genug, NICHTS gegen uns unternehmen zu wollen... oder sie verstecken ihre Informationen besser, als ich erwartet habe. Wie auch immer - gut gemacht, Soldat.", sourceObjectiveStatus = "unverified-source-field" }
quests[25696] = { id = 25696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sonnenschleiers Exkursionstrupp", description = "Ach richtig – ich habe vor ein paar Tagen eine Nachricht von jemandem erhalten. Das archäologische Institut oder so ähnlich? Sie suchen jemanden, der... etwas tun soll...\n\n<Der Kriegsherr durchwühlt einige Papiere.>\n\nAh, hier ist es! Ja, Rohan Sonnenschleier vom archäologischen Institut sucht fähige Abenteurer, die ihm bei einer archäologischen Expedition in den Süden helfen sollen.\n\nHier, nehmt das mit. Warum geht Ihr nicht und sprecht mit dem Elfen?", sourceObjective = "Meldet Euch bei Rohan Sonnenschleier bei Sonnenschleiers Exkursionstrupp in den Verwüsteten Landen.\n\nBereitgestellter Gegenstand:", completion = "Willkommen, Reisender. Danke, dass Ihr Euch auf meinen Aufruf hin gemeldet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25697] = { id = 25697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Amulett von Allistarj", description = "Als mein Meister mir half, meine Augen herauszunehmen, gab er mir das Geschenk der Sicht - einer Sicht, die weit besser ist, als Eure oder die dieser blutsüchtigen Elfen. Meine Sicht erlaubt mir, Gegenstände mit dämonischer Macht zu sehen, so wie das Amulett von Allistarj.\n\nAllistarj selbst ist tot, aber er hat sein Amulett in einer Schatzgrube in der Schlangenschlinge im Osten eingeschlossen. Zusammen mit anderen Amuletten wird dieses Relikt uns Zugang zu Razelikhs Behausung verschaffen.", sourceObjective = "Besorgt das Amulett von Allistarj aus der Schlangenschlinge in den Verwüsteten Landen.", progress = "Alistarj hat einen Teil seiner selbst in dem Amulett hinterlassen. Sogar jetzt kann ich seine Bosheit spüren.", completion = "<Lynnore untersucht das Amulett.>\n\nEr war ein Erzmagier, das spüre ich. Ich werde das Amulett für Euch aufbewahren, während Ihr die anderen sucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25698] = { id = 25698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Amulett von Sevine", description = "Das Amulett von Sevine befindet sich weit im Osten in Händen eines Murlocs, auf einer Klippe mit Ausblick über die Havarieküste. Wie es in den Besitz dieses Murlocs gelangt ist, entzieht sich meiner Kenntnis, aber ich kann mit Sicherheit sagen, dass Ihr es dort finden werdet.\n\nIch fühle eine stärkere Verbindung mit Sevine als mit den anderen Dienern Razelikhs - möglicherweise, weil sie den Altar der Stürme erbaut hat, auf dem Ihr mich wiederbelebt habt. Bringt ihr Amulett mit den anderen zu Lynnore.", sourceObjective = "Besorgt das Amulett von Sevine von Salzflopper in den Verwüsteten Landen.", progress = "Sevines Amulett - zusammen mit den anderen können wir die Anhöhe des Entweihers erreichen.", completion = "<Lynnore wiegt das Amulett in der Hand.>\n\nEin Kriegsherr... und ein mächtiger noch dazu. Ich werde das hier behalten, bis die Zeit reif ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[25699] = { id = 25699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Amulett von Grol", description = "Grol - der Oger, der mich auseinandergerissen hat.\n\n<Loramus lacht.>\n\nOffensichtlich ist Grols Leichnam durch mehrere Hände gegangen, seit wir zusammen gestorben sind, aber er ist nicht länger bei den Ogern. Seine Leiche ist zusammen mit seinem Amulett der Macht in einem Schiffswrack vor der Havarieküste im Osten. Sein Amulett ist das letzte - sobald sie vereint sind, werden die drei uns Zugang zu Razelikh gewähren und darin liegt unsere Chance, diesen Wahnsinn zu beenden.", sourceObjective = "Besorgt das Amulett von Grol von der Havarieküste in den Verwüsteten Landen.", progress = "Das dritte Amulett von Razelikhs drittem Hauptmann.", completion = "<Lynnore umklammert das Amulett.>\n\nEr war ein mächtiger Krieger. Ich werde das Amulett behalten, bis Loramus bereit ist, fortzufahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[25700] = { id = 25700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loramus Thalipedes wartet", description = "Die Verzauberung auf diesen Amuletten war nicht besonders kompliziert. Zusammengefügt wird ihre Macht Euch Zugang zu Razelikh, dem Erschaffer des Amuletts, verschaffen.\n\nIch bin bereit, dieses Ritual für Euch und Loramus durchzuführen. Sprecht noch einmal mit mir, wenn Ihr bereit seid.", sourceObjective = "Sprecht mit Blutmagierin Lynnore, um an ihrem Ritual teilzunehmen.", completion = "Wie es aussieht, sind wir bereit, uns unserem Dämon zu stellen, {name}. Wir haben den Segen des Amuletts, wir haben das Steinmesser und ich allein weiß den wahren Namen des Dämons: Rakh'likh. Zusammen könnte das genügen, den Entweiher zu besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25701] = { id = 25701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr seid Rakh'likh, Dämon", description = "Held, hört gut zu.\n\nZunächst müssen wir nach Nordosten zum tödlichen Pförtner reisen, der auf uns am nördlichen Fuß der Anhöhe des Entweihers wartet. Der Pförtner wird uns dann oben auf die Anhöhe schicken. Sobald wir dort sind, brauche ich Eure Hilfe, um Razelikh zu besiegen, denn ich fürchte, dass ich nicht stark genug bin, um ihn alleine zu schlagen.\n\nWas noch wichtiger ist - Ihr müsst das Steinmesser halten und nicht benutzen, bevor ich es Euch sage. Dieses Messer wird Razelikhs Seele in ihrem neuen, ewigen Gefängnis festsetzen.\n\nWenn wir Erfolg haben, sprecht mit Wazzik.", sourceObjective = "Sprecht mit dem tödlichen Pförtner nördlich der Anhöhe des Entweihers. Wenn Ihr oben auf der Anhöhe angelangt seid, zerstört Razelikhs Körper und benutzt dann das Steinmesser des Versiegelns, um seine Seele gefangen zu nehmen.", completion = "Ich verstehe. Also hatte Loramus das die ganze Zeit so geplant.\n\nIch hatte den richtigen Verdacht, aber ich denke, ich wollte es nicht glauben. Und jetzt ergibt seine letzte Anweisung an mich auch einen Sinn:\n\nEr sagte mir, ich solle Euch eins hiervon auswählen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25702] = { id = 25702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuhause... Weg... Naga...", description = "<Der Murloc hat Schwierigkeiten, Eure Sprache zu sprechen.>\n\nSteinteich... angegriffen. Naga kommen, einnehmen Dorf, Dorfbewohner.\n\nSalzflopper entkommen, andere nicht. Geht Süden, sprecht mit Häuptling Neptool. Vielleicht er überlebt.", sourceObjective = "Salzflopper hat Euch gebeten, mit Neptool, Häuptling der Steinteichmurlocs, zu sprechen.", completion = "<Der Murlocgeist schaut Euch traurig an.>\n\nSalzflopper hat keine Schande über sich gebracht, indem er wegrannte. Schaut hinter mich und seht selbst.\n\nDer Steinteich hatte keine Chance gegen den Angriff der Naga.", sourceObjectiveStatus = "unverified-source-field" }
quests[25703] = { id = 25703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gräueltaten", description = "<Obwohl seine Lippen sich nicht bewegen, könnt Ihr spüren, dass der Murlochäuptling mit Euch spricht.>\n\nDie Naga der Blutbrandung und die Steinteichmurlocs haben miteinander gelebt, solange wir denken können. Wir hatten unsere Meinungsverschiedenheiten, aber wir haben uns nie gegenseitig provoziert. Warum haben sie sich dann nur gegen uns gewandt?\n\n<Neptool wirft einen Blick über seine Schulter auf seine früheren Dorfbewohner.>\n\nSeht Ihr, was sie jetzt tun? Sie versklaven uns, opfern uns und zwingen uns, gegeneinander zu kämpfen. Ich werde sie aufhalten, {race}... und Ihr werdet meine Waffe sein.", sourceObjective = "Tötet 10 Barbaren der Blutbrandung und 10 Verzauberinnen der Blutbrandung.", completion = "Ihr habt Eure Sache gut gemacht, tapferer {class}. Ich bin erfreut, aber noch nicht zufrieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25704] = { id = 25704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verrückte Magus", description = "Es bleibt nur noch eine Sache, die zu tun ist. Ihr müsst in Tonys Anwesenheit jemand mit einem großen Mojo töten.\n\nNein, nicht mich!\n\nDer alte Magus Tirth is' verrückt geworden, als er versucht hat, das Wasser aufzuhalten, als der Kataklysmus hereinbrach. Jetzt sucht er die Gegend südlich vom Stützpunkt heim.\n\nNehmt diesen Seelenstab und benutzt ihn auf seinem Leichnam. Dann bringt Tony zurück, und wir verfrachten ihn zurück in seinen Körper.\n\nIhr könnt mein Geistportal für den Weg benutzen.", sourceObjective = "Extrahiert die Seele von Tirth, dem verrückten Magus.", completion = "Jetzt werden wir Tony Zweihauer zurück ins Leben bringen. Seid ihr dann beide so weit, Mann?", sourceObjectiveStatus = "unverified-source-field" }
quests[25705] = { id = 25705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falsche Götzen", description = "Neptulon der Gezeitenjäger ist unser Gott. Er war auch der Gott der Blutbrandung, aber anscheinend haben sie ihm den Rücken gekehrt. Jetzt verehren sie nur noch Azshara, ihre Nagakönigin. Ihr werdet die Abbilder Azsharas überall in ihren Siedlungen sehen, die aus Seestein gemeißelt wurden.\n\n<Der Murlocgeist betrachtet Eure Waffe.>\n\nDie Waffe wird reichen. Durchbohrt damit die Götzen der Azsh'ir. Man muss sie daran erinnern, dass unser Vater Neptulon der einzige ist, der wirklich die Meere regiert.", sourceObjective = "Zerstört 8 Götzen der Azsh'ir auf den Roten Weiten.", completion = "Ihr macht einen alten Murloc stolz, {race}.\n\nDanke und mögen die Wellen immer an Euren Füßen plätschern.", sourceObjectiveStatus = "unverified-source-field" }
quests[25706] = { id = 25706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neptools Rache", description = "Noch so viele Nagatode werden den Stamm des Steinteichs nicht wieder zurückbringen, aber die Menge der Rache wird den Geistern meines Volkes helfen, leichter ihre Ruhe zu finden.\n\nViele der mächtigeren Angehörigen der Blutbrandung haben eine Feste in den Höhlen im Nordwesten errichtet. Tötet sie im Namen Steinteichs. Die anderen Angehörigen der Blutbrandung haben hier auf unserem Strand Gladiatorenbecken und Azsh'ir Altäre errichtet, wo sie mein Volk gegeneinander kämpfen lassen und ihren falschen Gott verehren. Tötet sie im Namen des Gezeitenjägers.", sourceObjective = "Tötet 8 Akolythinnen der Blutbrandung, 8 Zeloten der Blutbrandung, 4 Glücksspieler der Blutbrandung und 4 Götzendienerinnen der Blutbrandung.", completion = "Das letzte Mitglied des Steinteichs kann heute als Geisel genommen und morgen getötet werden, Landwandler... aber sie werden die Unterwelt in dem Wissen durchqueren, dass ein tapferer {race} ihren Tod rächte. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[25707] = { id = 25707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zukunft des Steinteichs", description = "Die Steinteichkaulquappen, die sich noch auf dieser Kiste befinden, scheinen müde, verängstigt und beinahe vertrocknet zu sein. Sie müssen zum Wasser gebracht werden und zwar schnell.\n\nWenn Ihr diese Kiste vielleicht über den Strand in das Verbotene Meer weit jenseits der Küste der Roten Weiten ziehen könntet, dann haben sie eine Chance zu entkommen und die Steinteichmurlocs können vielleicht weiterleben...", sourceObjective = "Zieht die Verlassene Kiste der Blutbrandung zum Verbotenen Meer vor der Küste der Roten Weiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25708] = { id = 25708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefallene Freunde", description = "Laut Eurem Bericht klingt es nicht so, als gäbe es viele Überlebende… nur rastlose Geister. Wir müssen ihnen wenigstens zu ihrer letzten Ruhe verhelfen.\n\n<Enohar nimmt einen tiefen Schluck Schwarzbier aus ihrem Krug.>\n\nKehrt zurück zur Havarieküste und vernichtet die Geister der Worgen, die dort ihr Unwesen treiben. Dadurch befreit Ihr sie von dieser Welt, sodass sie in die nächste weiterziehen können.", sourceObjective = "Tötet 13 ertrunkene Gilneer an der Havarieküste, um ihre Geister zu befreien.", completion = "<Enohar nimmt einen Schluck aus ihrem frisch aufgefüllten Krug.>\n\nAye, das habt Ihr gut gemacht, Junge. Ihr erfüllt die Allianz mit Stolz.", sourceObjectiveStatus = "unverified-source-field" }
quests[25709] = { id = 25709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein paar Schwanzfedern ausreißen", description = "Die gestrandeten Schiffe bereiten mir jedoch noch weitere Sorgen. Sie locken unglaublich viele Geier an. Sie haben zwar die Knochen schon sauber gepickt, aber wir können nicht zulassen, dass sie die Leichen unserer Freunde noch weiter entehren.\n\nBevor ich Braumeister wurde, war ich Jäger. Hier, nehmt diesen Bogen und vor allem diese Pfeile. Ich habe sie mit einer Tinktur benetzt, die diesen Knochenpflückern eine unangenehme Überraschung bereiten sollte.", sourceObjective = "Benutzt Enohars explosive Pfeile, um 20 Schwanzfederknochenpflücker an der Havarieküste zu töten.", completion = "Es ist eine Tragödie, was sich da an der Havarieküste abgespielt hat. Und es waren nicht einmal Soldaten, sondern nur brave Bürger auf der Suche nach einem neuen Zuhause.\n\nIch glaube, wir haben alles getan, was wir konnten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25710] = { id = 25710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unwichtige Ablenkungen", description = "Nethergarde hat seit Jahren unerschütterlich dem Ansturm der Dämonen, die dieses Land heimsuchen, standgehalten. Unsere Wache endet nie, unsere Wachsamkeit lässt nie nach und unsere Tapferkeit ist unermesslich.\n\nWir haben diese Lande verteidigt, seit das Portal sich öffnete, aber jetzt hat dieses Hordengeschmeiß die Frechheit, sich uns in den Weg zu stellen? Wir haben SIE genauso beschützt wie uns selbst!\n\n<Lungertz mustert Euch.>\n\nSchauen wir mal, ob Ihr für den Kampf taugt. Tötet einen der Hordenspäher der Okril'lon, die an unseren Grenzen nagen.", sourceObjective = "Tötet einen Späher der Okril'lon außerhalb von Burg Nethergarde in den Verwüsteten Landen.", completion = "Hmm... nicht schlecht. Ihr seid schneller als die meisten meiner Leute. Bleibt in der Nähe, {name}... Vielleicht habe ich doch noch Verwendung für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[25711] = { id = 25711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schaltet die Okril'lon aus.", description = "Die Horde ist eine Landplage, derer wir uns entledigen werden, aber es ist schwieriger als erwartet. Ihr müsst dem ein Ende setzen.\n\nWestlich von Nethergarde übt die Hauptstreitmacht der Okril'lon Druck auf unsere Verteidigung aus. Im Moment besetzen sie die Mine von Nethergarde, wollen in die Versorgungslager vordringen und zum Schluss die Burg einnehmen. Ihr müsst sie dezimieren und ihren Vormarsch aufhalten, {name}.", sourceObjective = "Tötet 9 Infanteristen der Okril'lon beim Versorgungslager von Nethergarde.", completion = "Ihr seid ein Gewinn für die Allianz und die Kirin Tor, {name}. Gut gemacht.\n\nMit der Zeit werden unsere Streitkräfte die Mine zurückerobern und diese Hunde der Horde aus den Verwüsteten Landen vertreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25712] = { id = 25712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herrscher von Nethergarde", description = "Lungertz ist ein starker Anführer, aber er ist stolz. Er untertreibt den Druck, den die Horde wirklich auf uns ausübt. Ohne unsere Mine... Nethergarde ist mittellos.\n\nWir müssen die Streitkräfte der Horde JETZT aus dem Versorgungslager entfernen. Dazu müssen wir ihren Kommandanten, Hauptmann Metlek, töten. Er ist kein überragender Anführer und zieht es vor, Befehle aus den hinteren Linien heraus zu bellen, aber dennoch könnte sein Tod uns den Sieg verschaffen, den wir brauchen.", sourceObjective = "Tötet Hauptmann Metlek am Versorgungslager von Nethergarde.", completion = "Danke, {name}. Dank Eurer Bemühungen bin ich zuversichtlich, dass wir mit der Zeit die Mine von Nethergarde zurückerobern können.", sourceObjectiveStatus = "unverified-source-field" }
quests[25713] = { id = 25713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht ihre Waffen zunichte", description = "Sagt einmal... {name}, nicht wahr? Ich habe einen Vorschlag für Euch, der Explosionen beinhaltet. Interessiert?\n\nIch konnte nicht anders, als Eure Unterhaltung mit dem Rüstmeister anzuhören. Wisst Ihr... Ich arbeite an einer Sprengvorrichtung. Sie ist anderen Lebewesen gegenüber nicht sehr wirksam, aber verheerend gegen Artillerie. Wenn Ihr wieder hinausgeht, um diesen Orcs einen Besuch abzustatten, findet ein paar Vorräte der Feinde und probiert dieses Ding einmal aus. Wer weiß... vielleicht mögen sie ja auch Explosionen.", sourceObjective = "Benutzt Butterblumes Handgranate gegen 8 Waffenkisten der Okril'lon im Versorgungslager von Nethergarde.\n\nHaltet einen Sicherheitsabstand, wenn Ihr die Granaten verwendet, damit Ihr Euch nicht selbst in die Luft sprengt.", completion = "Aaah, das Geräusch, wenn Dinge \"bumm\" machen erfreut mein Herz und lässt es schneller schlagen. Ihr habt diesem Gnom den Tag versüßt, {name}", sourceObjectiveStatus = "unverified-source-field" }
quests[25714] = { id = 25714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behüter Mahar Ba", description = "Es ist Zeit für Euch, den Behüter aufzusuchen. Er ist in letzter Zeit etwas übellaunig und ich weiß nicht genau, warum.\n\nGeht oben auf den Magierturm und meldet Euch bei ihm. Ich habe hier keine Arbeit für Euch, aber ich bin sicher, dass er welche hat.", sourceObjective = "Meldet Euch bei Behüter Mahar Ba im Magierturm von Burg Nethergarde.", completion = "Meine Mitarbeiter haben das Richtige getan, Euch zu mir zu schicken. Ich habe ein Problem, das eine Bedrohung für das Sanktum von Nethergarde darstellen könnte. Ich brauche jemanden, der fähiger ist als die meisten anderen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25715] = { id = 25715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein genauerer Blick", description = "Wir haben schon unzählige Schiffe an der Küste im Südosten vorbeiziehen sehen und nie ist etwas Auffälliges passiert. Doch vor einigen Tagen warf ein Sturm mehrere Schiffe an die Küste, wo sie nun gestrandet liegen.\n\nIch würde einen Krug Nethergarde Bitter wetten, dass es Schiffe der Horde sind, wenn ich Nethergarde Bitter nicht so sehr lieben würde. Ich kann Euch jedoch mit Gold bezahlen, wenn Ihr Euch diese Schiffe genauer anseht und mir davon berichtet.", sourceObjective = "Späht die gestrandeten Schiffe an der Havarieküste in den Verwüsteten Landen aus.", completion = "Ihr habt Worgen gesehen? Das klingt nicht gut.\n\nWorgengeister? Das klingt sogar noch schlimmer.\n\nDas waren keine Schiffe der Horde… das waren gilnearische Schiffe! Und sie waren sicher auf dem Weg nach Surwich am Ende des Besudelten Walds. Das ergäbe zumindest Sinn.\n\nWir müssen ihnen helfen, {name}! Die Worgen sind unsere Verbündeten!", sourceObjectiveStatus = "unverified-source-field" }
quests[25716] = { id = 25716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kultisten an der Schwelle", description = "Möglicherweise seid Ihr schon einigen Kultisten der Schattenanbeter begegnet, die in Höhlen südwestlich von Nethergarde hausen. Sie stellen keine direkte Bedrohung für unsere Burg dar, aber ich fürchte, dass sie etwas Furchtbares planen, das Eure Vorstellungskraft übersteigt.\n\nDie rangniederen Mitglieder tragen Zauberfokusse, die eine Antwort enthalten könnten. Bringt mir einige intakte davon her, wenn Ihr sie den Kultisten aus den Händen reißen könnt.", sourceObjective = "Besorgt 6 intakte Zauberfokusse eines Schattenanbeters von Zauberklingen der Schattenanbeter und Okkultisten der Schattenanbeter in den Verwüsteten Landen.", progress = "Die Kultisten werden sich nicht so einfach von ihren Fokussen trennen. Tötet sie schnell, bevor sie Eure Absicht erahnen.", completion = "Geschickt gemacht, {name}. Jetzt werden wir sehen, ob mein Verdacht berechtigt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[25717] = { id = 25717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dämonen und der Druide", description = "Das archäologische Institut konzentriert sich auf das Auffinden und Bewahren magischer Artefakte. Diese Exkursion konzentriert sich auf die dämonischen Artefakte, die dort verborgen sind, wo sich einst die Faulende Narbe befand.\n\nEin Worgendruide hat sich dort angesiedelt und lässt einen Wald wachsen. Allerdings scheint es ihm nicht so recht zu gelingen, da die Gegend immer noch von Dämonen verseucht ist.\n\nNun wie auch immer, der Wald steht unserer Exkursion im Weg, genau wie die Dämonen. Tötet die besudelten und kehrt zurück zu mir, damit wir uns um den Druiden kümmern.", sourceObjective = "Tötet 5 Verdammniswachenzerstörer, 5 Schreckenslordschänder, 5 verderbte Dunkelwaldtreants und 3 Teufelssporensumpflords im Besudelten Wald.", progress = "Der Wald ist noch nicht von der Verderbnis befreit, {name}. Tut, was ich sage und dann können wir vielleicht mit unserer Mission fortfahren.", completion = "Ich danke Euch, {name}.\n\nIch sollte etwas ehrlicher zu Euch sein. Die Dämonen waren ein Ärgernis, aber sie sind nicht das eigentliche Problem. Dieser Worgendruide ist unser Problem", sourceObjectiveStatus = "unverified-source-field" }
quests[25718] = { id = 25718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man am besten weitermacht", description = "Dadurch, dass Ihr dort unten Dämonen getötet habt, bekamen unsere Späher genug Zeit, sich den Druiden einmal genauer anzusehen. Meine Informanten berichten mir, dass er Marl Wurmdorn heißt - er ist ein abtrünniger Druide aus Gilneas mit beachtlichen Kräften. Er wohnt in Maldraz, dem großen, verdrehten Baum mitten im Wald und irgendeine seltsame Kraft bewahrt ihn vor Unheil. Ob diese Kraft dämonischen oder natürlichen Ursprungs ist, müssen wir noch herausfinden.\n\nSprecht mit Elijah. Vielleicht hat er neue Informationen für Euch.", sourceObjective = "Meldet Euch bei Elijah Dämmerflug bei Sonnenschleiers Exkursionstrupp in den Verwüsteten Landen.", completion = "Rohan schickt EUCH, um seinen Druiden zu töten? Na schön.\n\nIhr solltet wissen: Marl Wurmdorn ist gleichermaßen Dämon wie Druide. Sogar ein Druide mit seiner Macht hat keine Chance gegen die dämonischen Energien, die dieses Land vollkommen durchziehen. Aber das ändert nichts daran, dass er für uns ein Hindernis ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[25719] = { id = 25719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonisches Gefäß", description = "Es muss einen Weg geben, Wurmdorns Aufmerksamkeit zu erregen. Etwas, das seine Trance durchbricht. Etwas, das mit Sicherheit funktioniert.\n\nDie wenigen Wildtierarten, die es geschafft haben, sich im Besudelten Wald anzusiedeln, sind zweifellos von den latenten Energien des Landes in Mitleidenschaft gezogen. Eure Aufgabe ist es, ihre Kadaverteile einzusammeln und eine Möglichkeit zu finden, sie in ein Gefäß umzuwandeln. Egal ob Wurmdorns Trance druidischer oder dämonischer Natur ist, ein Gefäß mit besudeltem Tierfleisch, das groß genug ist, sollte in der Lage sein, diese zu durchbrechen.", sourceObjective = "Tötet besudelte Schwarzbären, besudelte Nachtpirscher und besudelte Kreischer im Besudelten Wald und versucht, ihre Kadaverteile zu einem dämonischen Gefäß zusammenzusetzen.", progress = "Dämmerflugs Plan ist gut. Habt Ihr das Gefäß, {name}?", completion = "Ausgezeichnet gemacht, {name}. Wir haben, was wir brauchen, um die Trance des Worgen zu durchbrechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25720] = { id = 25720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fall des Marl Wurmdorn", description = "Wurmdorns unnatürlicher Wald bedroht den Fortschritt unserer Exkursion. Unsere Spitzhacken zerbrechen an ihren Wurzeln, sein Moos überwuchert unsere Ausgrabungsstätten und seine Tiere greifen meine Leute an. Wenn es um Ausgrabungen geht, ist mir eine dämonenverseuchte Einöde allemal lieber als ein Wald.\n\nNehmt das dämonische Gefäß und benutzt es gegen Marl Wurmdorn, um ihn aus seiner Trance zu holen. Kehrt zu mir zurück, wenn er nicht mehr unter uns weilt.", sourceObjective = "Tötet Marl Wurmdorn bei Maldraz in den Verwüsteten Landen. Ihr könnt das dämonische Gefäß benutzen, um ihn aus seiner Trance zu holen.", completion = "Jetzt, da dieser Druide von der Bildfläche verschwunden ist, können wir uns wieder unseren Ausgrabungen zuwenden. Die Welt ist voller mächtiger Artefakte, {name}. Ihr müsst nur den Willen haben, das Notwendige zu tun, um sie zu bekommen.\n\nNehmt ruhig eins von diesen hier. Das Institut für Archäologie teilt immer gerne seine Schätze mit anderen Mitgliedern der Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[25721] = { id = 25721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kämpft gegen die Flut", description = "Ich bin hier, weil Muradin selbst wusste, dass diese Messstation jemanden braucht, der diese Schwachköpfe auf Trab bringt. Sie haben alle zu viel Angst vor den Wildtieren, um überhaupt etwas zu tun. Wenn ich will, dass sie ihren Allerwertesten hochbekommen, dann muss hier ein wenig aufgeräumt werden.\n\nZunächst einmal haben wir ein Problem mit Elementaren. Die Flut hat hier so ein Durcheinander angerichtet, dass selbst das Wasser hysterisch geworden ist.\n\nIch wette, Ihr habt noch nie einem ganzen See Sinn und Verstand eingeprügelt, aber genau das verlange ich jetzt von Euch. Ihr müsst diesen Elementaren richtig eine von mir verpassen.", sourceObjective = "Tötet 10 Flutelementare.", completion = "Wer hätte das gedacht. Es gibt tatsächlich jemanden hier, der Magni keine Schande macht - sein armes Herz aus Kies sei gesegnet.\n\nAllein dafür bekommt Ihr den ersten Schluck von dem Bier, mein Junge. Aber lasst Euch das nicht zu Kopfe steigen! Wir haben noch viel mehr verfluchte Arbeit zu tun und ich werde nicht dulden, dass Ihr vorzeitig schlapp macht!", sourceObjectiveStatus = "unverified-source-field" }
quests[25722] = { id = 25722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ablagerungen, mein Lieber", description = "Die Zerstörung des Steinwerkdamms war keine Kleinigkeit. Wir sind hier, um herauszufinden, wie schlimm der Schaden ist. Eine riesige Wassermenge ist hier durchgetobt und wenn diese die Erde zu sehr gestört hat, könnte uns noch Schlimmeres bevorstehen.\n\nWir können einiges aus den Sedimenten der überfluteten Gegend ablesen. Ich brauche so viele Erdproben wie möglich. Ich würde es wirklich sehr zu schätzen wissen, wenn Ihr dort hinausgehen und noch einige Proben für mich sammeln würdet.", sourceObjective = "Sammelt 8 Flutsedimentproben ein.", progress = "Dann lasst mal das Sediment sehen.", completion = "Ah ja. Die gute Nachricht ist, sie sind perfekt. Die schlechte Nachricht ist, dass ich – sogar betrunken, wie ich bin – erkenne, dass ihre Farbe nicht dem Mutterboden hier entspricht.\n\nDas bedeutet, dass es nicht gut für diese Gegend aussieht, {name}. Aber wir müssen noch mehr Tests durchführen, bevor wir das Handtuch werfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25723] = { id = 25723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreschen bringt Glück", description = "Die hiesigen Wildtiere sind offenbar von der Flut vollkommen verstört. Dieses Moor war einmal voller Krokilisken, aber ich habe noch keinen einzigen gesehen.\n\nWas ich gesehen habe, sind Dreschadons. Die hat es hier noch nie gegeben, also muss die Flut sie direkt aus Loch Modan hergeschwemmt haben.\n\nZum Glück für uns sind sie viel leckerer als Krokilisken und mir gehen gerade die Vorräte aus. Bringt mir Dreschadonfleisch für das Lager und ich werde Euch gern dafür bezahlen.", sourceObjective = "Besorgt 8 Dreschadonbrocken von verirrten Dreschadons.", progress = "Sind sie fleischig? Schauen wir mal.", completion = "Herrlich. Die kann man bestimmt gut braten und dem Lager bleibt eine Woche Pilzkekse erspart.", sourceObjectiveStatus = "unverified-source-field" }
quests[25724] = { id = 25724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostmähnenaggression", description = "Der Kataklysmus hat das Gleichgewicht der Kräfte in Dun Morogh in Frage gestellt, {name}. Ohne Warnung tauchte eine Welle Troggs aus den Höhlen in der Nähe von Gnomeregan auf und hat die Trolle der Frostmähnen überrannt. Die Trolle sind seitdem immer weiter nach Osten gezogen.\n\nIm Nordwesten, oben am Schimmergrat, gab es immer eine gewisse Präsenz der Frostmähnen, aber seit der Abwanderung sind wir jetzt von Trollen umgeben. Wir können nicht zulassen, dass die Trolle diesen Umstand zu ihren Gunsten ausnutzen. Meine Leute werden im Osten die Stellung halten und Ihr führt einen Schlag gegen den Schimmergrat.", sourceObjective = "Tötet 5 Seher der Frostmähnen und 7 Schneeschreiter der Frostmähnen auf Schimmergrat.", completion = "Wir sollten in der Lage sein, unsere Bemühungen auf den Rest der Trolle im Osten zu konzentrieren, aber es gibt immer noch das Problem mit den Wendigos im Graufelsbau.", sourceObjectiveStatus = "unverified-source-field" }
quests[25725] = { id = 25725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moosbuschbeeren", description = "Wir haben genügend Vorräte, aber wir benötigen Arzneien. Das halbe Lager hat einen gewaltigen Kater und ein Heilmittel wäre jetzt angebracht.\n\nZum Glück kenne ich ein gutes Hausmittel, das mir von meiner lieben alten Mutter beigebracht wurde. Wir brauchen nur ein paar hiesige Zutaten.\n\nSeid so gut und sammelt für mich ein paar Beeren von Moosbüschen. Sie wachsen hauptsächlich am Wasser im Schatten, also schaut entlang der Küste und in der Nähe anderer Pflanzen.", sourceObjective = "Sammelt 15 Handvoll Moosbeeren.", progress = "Wie viele habt Ihr gefunden?", completion = "Die sind genau richtig. Die Jungs werden bald wieder auf den Füßen sein, sobald ich das hier in etwas Essbares verwandelt habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[25726] = { id = 25726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nivellierarbeiten", description = "Also gut, Ihr müsst mir helfen, mein Nivelliergerät zu finden.\n\nWas guckt Ihr so komisch? Richtig! Ich sagte mein Nivelliergerät! Das ist ein wichtiges Vermessungsinstrument!\n\nIch hab mir den Namen nicht ausgedacht, ok? Geht und schaut es nach! Ich habe es nur kurz auf einem Felsen liegen lassen und einer dieser furchtbaren Schlammlinge hat es verschlungen. Die kriechen überall hier herum, aber einer von ihnen müsste es noch in sich haben.", sourceObjective = "Findet ein Nivelliergerät bei einem schmierigen Schlammling.", progress = "Habt Ihr das Nivelliergerät gefunden?", completion = "Oh gut, es ist unbeschädigt! Vielen Dank.\n\nIhr, äh, solltet Euch dort vielleicht ein bisschen säubern.", sourceObjectiveStatus = "unverified-source-field" }
quests[25727] = { id = 25727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drungeld Finsterblick", description = "Der Dunkeleisenklan hier führt nichts Gutes im Schilde. Und wenn Euch das überrascht, seid Ihr noch dämlicher als die Papiertiger da in dem Zelt. Muradin kann ja diesen rußgeschwärzten Schwachköpfen in Eisenschmiede gegenüber Lippenbekenntnisse ablegen, aber hier draußen zählen die nichts.\n\nLetzte Nacht gab es einen Überfall auf das Lager und ein Überfall ist einer zu viel. Ihr Anführer ist ein stämmiger Kerl mit Namen Finsterblick und er versteckt sich in der Höhle am südlichen Ufer des Flusses.\n\nBringt mir Finsterblicks Bart als Beweis, dass er keine Bedrohung mehr für uns und Eisenschmiede darstellt.", sourceObjective = "Tötet Dungeld Finsterblick und nehmt seinen Bart an Euch.", progress = "Zeigt mal her!", completion = "Ein Glück, dass wir den los sind! Ich werde das fiese Ding später verbrennen, damit es uns nicht das Lager zustinkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25728] = { id = 25728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baunzers wilder Ritt", description = "Jetzt braucht Herr Baunzer nur noch einen Engel, der ihm als Navigator dient. Würdest du dieser Engel sein, <Onkel/Tante>? Mit deiner Hilfe können wir auf die Klippe hinaus und ganz ganz viele Hordies töten! Was sagst du? Ach bitte, <Onkel/Tante>! BITTE BITTE BITTE!\n\nWenn wir genug Hordies töten, kauft Lord Brachweiher uns allen ein Eis!", sourceObjective = "Tötet 20 Goblintechniker und 5 Goblinernter.", completion = "<Lord Brachweiher hustet.>\n\nDas ist merkwürdig.\n\nIhr habt da draußen mit dem Roboter gute Arbeit geleistet. Ihr habt mich ein wenig auf dem falschen Fuß erwischt. Ich wusste nicht, dass das kleine Mädchen so...\n\n<Lord Brachweiher zeigt auf seine Schläfe und macht kleine Kreise mit seinem Finger.>\n\nBesonders ist...\n\nNaja, ist ja egal, wie die Sache erledigt wird, nicht wahr? Habe ich recht?\n\nWahrscheinlich.\n\nWollt Ihr ein Eis?", sourceObjectiveStatus = "unverified-source-field" }
quests[25729] = { id = 25729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerenzo der Verräter", description = "<Der Gnomcorder springt mit lautem Surren an.>\n\nBitte kommen, {name}! Seid Ihr da? Isch 'abe gese'en auf die Karte, dass Ihr seid in die Nä' von die Felskesselsee Wasserrad, ist das rischtisch?\n\nOffenbar 'at die Venture. Co sisch einquartiert bei die Rad. Ihr müsst umschauen Eusch, wenn Ihr dort seid. Solltet Ihr se'en die verräterische Gnom mit die Name Gerenzo Pfeifzang, Ihr müsst ihn treten kräftisch in die 'intern für misch und Gnomeregan! Isch werde zahlen fürstlisch!", sourceObjective = "Tötet Gerenzo Pfeifzang.", sourceObjectiveStatus = "unverified-source-field" }
quests[25730] = { id = 25730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "HÜTET EUCH VOR FELSKIEFER!", description = "Auf Befehl der Leute, die nicht an einem Stück von einem richtig großen Fisch verschlungen werden wollen, ist der Zutritt zum Felskesselsee VERBOTEN! Jemand hat beschlossen, einen riesigen, zwergenfressenden Fisch im See anzusiedeln.\n\nEs wird dringend empfohlen, dem See fernzubleiben. Solltet Ihr allerdings der heldenhafte Typ sein und noch ein paar Freunde haben, tut uns doch den Gefallen und tötet das verdammte Ding! Vielleicht kann ich dann hier angeln, nicht wahr?\n\nFalls es Euch wirklich gelingen sollte, sucht mich in der Scherwindfeste für eine Belohnung auf.\n\n-Der alte Eisenbock", sourceObjective = "Tötet Felskiefer und bringt Felskiefers riesigen Zahn an Euch.", progress = "Habt Ihr das Ungeheuer getötet?", completion = "Wer hätte das gedacht. Ihr habt das Ungeheuer tatsächlich erwischt? Nun, abgemacht ist abgemacht! Hier ist Eure Belohnung!", sourceObjectiveStatus = "unverified-source-field" }
quests[25731] = { id = 25731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Spatz in der Hand", description = "Es ist Zeit, dieser Sache auf den Grund zu gehen. Wir müssen die Matrone dieser Wilden befragen, Marion Wurmschwinge. Wir werden sie lebend fangen. Das ist der Plan:\n\nDie Harpyien kommunizieren mit Signalfeuern über den Gebirgskamm hinweg. Wenn wir eines davon löschen, wird Marion sicher kommen, um zu sehen, was damit los ist.\n\nKämpft mit ihr, um sie abzulenken, während ich mich von hinten anschleiche und sie mir schnappe. Die Fragen zu stellen überlasse ich dann Euch. Los, holen wir sie uns, {name}!", sourceObjective = "Löscht ein Harpyiensignalfeuer, um die Aufmerksamkeit Marion Wurmschwinges zu erregen. Kämpft mit ihr, bis Thisalee sie einfängt, und befragt die Harpyienmatrone dann.", completion = "Also sind die Harpyien Werkzeuge einer Art von Drachen, \"Sethria\".\n\nAber was tun die Drachen mit diesen Eiern? Und was ist das für ein \"besonderes\" Ei, das Sethria so unbedingt will?\n\nIch verstehe es nicht, {name}. Ich habe einen Bericht an Himmelsfürst Omnuron weitergeleitet. Er wird wissen, was als Nächstes zu tun ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[25732] = { id = 25732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Hühnchen rupfen", description = "Wir haben es geschafft!\n\nNager ist erledigt und ich habe unseren Glitzerkram gefunden!\n\nDas sind gute Nachrichten.\n\nDas Kleinod ist verflucht und verwandelt jeden, der es berührt, in ein Skelett.\n\nDas sind schlechte Nachrichten.\n\nLaut diesen verfluchten Piraten kennt der König der Gilblin jedoch das Geheimnis, wie man diesen Fluch brechen kann.\n\nDas sind gute Nachrichten.\n\nIch kann aber keinen Fuß aus diesem Riff setzen, sonst bleibe ich auf ewig verflucht.\n\nDas sind schlechte Nachrichten.", sourceObjective = "Budd möchte, dass Ihr den Zinnplätter von König Gurboggel auf Gurboggels Fels besorgt.", progress = "Also, {race}…\n\nBrecht Ihr jetzt diesen Fluch oder was?", completion = "Das ist er?\n\nWie soll das denn den… Moment mal…", sourceObjectiveStatus = "unverified-source-field" }
quests[25733] = { id = 25733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pirscht von dannen", description = "Thelgenfelsen ist hier ein wichtiger Ort. Wir brauchen ihn, um dort den felsigen Untergrund und so was zu untersuchen.\n\nDa einem nichts im Leben leicht gemacht wird, gibt es am Thelgenfelsen riesige Höhlenpirscher. Sie sind so groß wie ein Zwerg und zweimal so hungrig. Wie ich schon sagte, diese modischen Kerle sind Forscher und keine Krieger, also wenn ich möchte, dass sie überhaupt etwas geschafft bekommen, müsst Ihr mir helfen, diese Viecher zu beseitigen.\n\nTötet so viele dieser Quälgeister, wie Ihr könnt und es soll Euer Schaden nicht sein, {name}.", sourceObjective = "Tötet 7 Höhlenpirscher und 7 Egelpirscher.", completion = "Gute Arbeit! Es würde mich nicht überraschen, wenn diese schrecklichen Dinger irgendwo da drin Eier abgelegt hätten, aber für den Moment reicht es.", sourceObjectiveStatus = "unverified-source-field" }
quests[25734] = { id = 25734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unten im Thelgenfelsen", description = "Ich bin jetzt nicht mehr ganz so wackelig auf den Beinen, also werde ich anfangen, das Nivelliergerät für meine letzten Messungen aufzubauen. Eins benötige ich noch von Euch.\n\nTief im Thelgenfelsen steht ein Seismograph, um alle Bewegungen der Erde aufzuzeichnen. Wenn sich seit der Katastrophe noch etwas bewegt hat, wird er es uns zeigen.\n\nDer Seismograph ist ganz unten in der Höhle. Findet ihn und bringt den Bericht, den er aufgezeichnet hat, zu mir.", sourceObjective = "Holt den seismischen Bericht von Thelgen aus Thelgenfelsen.", progress = "Dann schauen wir mal, was wir da haben, nicht wahr?", completion = "Wunderbar, mein Freund. Das dürfte alles sein, was wir brauchen. Schauen wir mal.", sourceObjectiveStatus = "unverified-source-field" }
quests[25735] = { id = 25735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pyrophorerz", description = "Telgenfelsen dort drüben ist so eine Art Wunder der Natur. Dort liegt die weltweit einzige bekannte Quelle von Pyrophorerz.\n\nDas Zeug ist selten, heiß begehrt und einfach nur lächerlich explosiv. Wenn man mit einer Spitzhacke aus Stahl daraufschlägt, gibt es ein Feuerwerk, das einen Raum voller Goblins vor Neid erblassen ließe.\n\nZum Glück habe ich für solche Gelegenheiten eine funkenresistente Spitzhacke erschaffen. Ich werde sie Euch leihen, wenn Ihr mir ein bisschen Pyrophorerz bringt. Natürlich bekommt Ihr auch etwas vom Gewinn ab.", sourceObjective = "Findet 8 Stücke Pyrophorerz.", progress = "Nun, Ihr seht so aus, als ob Euch kein Haar gekrümmt wurde.", completion = "Großartig! Wunderschön, dieses Erz.\n\nGut, dass Ihr Eure Spitzhacke nicht verloren habt. Die letzte Person, die ich dort hinausgeschickt habe, hat das untere Ende auf dem Boden aufschlagen lassen - und der Teil ist nicht funkensicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[25736] = { id = 25736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Flutwellenkern", description = "Das ist alles, was von dem riesigen Elementar, der Euch angegriffen hat, übrig geblieben ist: eine schäumende Kugel des Wassers, die sich weiter Eures Griffes zu entziehen versucht.\n\nForba wäre über einen weiteren Beweis, dass Ihr noch eine Bedrohung vom Lager abgewendet habt, sicherlich erbaut.", sourceObjective = "Bringt den Flutwellenkern zu Forba Fliesmeißel.", progress = "Häh? Was habt Ihr da?", completion = "Das Ding hat ja immer noch Kampfeswillen! Erstaunlich!\n\nIhr seid zäh, {name}. Ich weiß das zu schätzen. Ich würde sagen, dass eine Belohnung angebracht ist, bevor Ihr fortgeht.\n\nTut weiterhin Euer Bestes für Eisenschmiede, verstanden? Und solltet Ihr jemals meiner Schwester begegnen, grüßt sie von mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[25737] = { id = 25737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorsichtige Verhandlungen", description = "Nach dem, was ich über diese Wassergoblins weiß, sollte das funktionieren.\n\nIch habe aus den Gegenständen, die Ihr mir zusammengeplündert habt, eine Haizahnkette gebastelt. Es ist nicht nur ein hübsches Schmuckstück, sondern auch eine Erinnerung an Nagers Tod. Schwer zu sagen, wie viele Gilblins dieses Monster bei lebendigem Leib verschlungen hat.\n\nBietet dem Anführer der Gilblins die Halskette an. Als Tausch benötige ich ein Artefakt, das als Zinnplätter bekannt ist.\n\nUnd beeilt Euch, <Bursche/Mädel>. Ich beginne schon, mein Fleisch zu vermissen...", sourceObjective = "Sprecht mit König Gurboggel.", sourceObjectiveStatus = "unverified-source-field" }
quests[25738] = { id = 25738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das seichte Ende des Genpools", description = "<Gurboggel untersucht die Halskette aus Nagers Zähnen einen Moment lang.>\n\nNicht schlecht, {race}. Das heißt, wenn sie wirklich echt ist. Ich werde erstmal einen meiner Jungs losschicken und schauen, ob Eure Geschichte auch wahr ist.\n\nIn der Zwischenzeit erledigt Ihr etwas für mich. Dieses kleine Kinkerlitzchen ist nämlich nicht annähernd so viel wert wie der Zinnplätter. Nicht annähernd!\n\nMein Cousin Gilblingel schielt schon seit Jahren auf meinen Thron. Er ist zwar dumm wie ein Sack Korallen, aber dennoch gefährlich.\n\nIhr schafft ihn mir vom Hals und dann reden wir.", sourceObjective = "König Gurboggel möchte, dass Ihr Gilblingel auf Gurboggels Fels tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25739] = { id = 25739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn die Horde Euch nicht erwischt...", description = "<Hauptmann Kosak hustet schwach.>\n\nWar unterwegs zum Weberpass, kam vom Basislager der Nordwachtexpedition im Süden. Hinterhalt. Nicht von Horde. Spinnen. Große, hässliche, haarige, gemeine Spinnen.\n\nDutzende in die Flucht geschlagen, vielleicht Hunderte. Konnte nicht mehr zählen. Überwältigt von der Königin. Hat ein Stück aus mir herausgebissen. Bin nur um ein Haar lebend entkommen. Sterbe vielleicht.\n\nMehr meiner Leute sind unterwegs. Muss sicheren Durchgang gewährleisten. Tötet Spinnenkönigin.\n\n<Hauptmann Kosak wird bewusstlos.>", sourceObjective = "Tötet Königin Silith.", completion = "<Hauptmann Kosak zwingt sich zu einem Lächeln.>\n\nMacht Euch um mich keine Sorgen. Jetzt, da der große Held die Spinnenkönigin getötet hat, wird alles gut.\n\nVerstärkung kann hier jetzt sicher passieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[25740] = { id = 25740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Fakten", description = "Der Drache Sethria muss aufgehalten werden. Wir wissen, dass sich ihr Nest im Süden an den südlichen Klippen des Hyjal befindet, aber das ist leider fast schon alles.\n\nIch habe Thisalee auf der Suche nach Fakten zu Sethrias Nest geschickt. Sie hat speziell um Eure Hilfe gebeten. Ihr scheint die junge Druidin schwer beeindruckt zu haben.\n\nTrefft Euch mit Thisalee direkt hinter dem Tunnel, der zu Sethrias Nest führt. Und vergesst nicht, wir sind hier auf der Suche nach Fakten. Tut bloß nichts Verrücktes!", sourceObjective = "Meldet Euch bei Thisalee am Eingang zu Sethrias Nest auf dem Hyjal.", completion = "Ah, {name}! Ich hatte gehofft, Euch hier draußen wiederzusehen.\n\nWas, Omnuron nennt dies eine \"Suche nach Fakten\"? Pah! Fakten findet man am besten bei Leichen.\n\nLasst uns etwas Schaden anrichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25741] = { id = 25741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf die Zukunft vorbereiten", description = "Vergiftete Reisende kommen um die Scherwindfeste immer häufiger vor. Gerade vor ein paar Tagen fiel ein Hauptmann der Nordwacht den Spinnen der Weberkuhle zum Opfer. Er wäre an dem Gift gestorben, wenn ich kein Gegengift gehabt hätte. Leider ist mein Vorrat an Gegengift beinahe erschöpft.\n\nWenn Ihr nach Süden in Richtung Weberkuhle unterwegs seid, würdet Ihr freundlicherweise einige Kluftmoosgiftbeutel für mich besorgen? Ihr solltet sie von Kluftmoosspinnen erhalten.", sourceObjective = "Besorgt 10 Kluftmoosgiftbeutel.", progress = "Habt Ihr die Giftbeutel, um die ich Euch gebeten hatte, bekommen?", completion = "Das dürfte uns auf absehbare Zeit mit Gegengift versorgen. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25742] = { id = 25742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was? Dieses alte Ding?", description = "Abgemacht ist abgemacht.\n\nIch überreiche Euch, <mysteriöser Fremder/mysteriöse Fremde>, den einzig wahren Zinnplätter.\n\nIhr dürft vortreten und dieses glanzvolle Geschenk an Euch nehmen.\n\nHier. Auch wenn er für ungeschulte Augen vielleicht wie ein einfacher Hammer aussehen mag, verfügt er sicher über viele geheime Mächte, die sich im richtigen Augenblick offenbaren werden.\n\nPasst gut auf diesen Schatz auf, <Fremder/Fremde>. Er ist schon seit... na ja... Tagen in meinem königlichen Besitz!", sourceObjective = "Bringt den Zinnplätter zu Harrison im Verwunschenen Riff.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[25743] = { id = 25743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entscheidungen, Entscheidungen", description = "Das ist keine magische Lösung für meinen Fluch! Das ist nur ein Hammer!\n\nIch bin vielleicht verrückt, aber ich bin nicht dumm.\n\nIch werde das hier AUF GAR KEINEN FALL benutzen, um meinen Glitzerkram kaputt zu machen! Nicht nach allem, was ich durchgemacht habe, um an ihn zu kommen!\n\n<Budd hält einen Moment inne, um nachzudenken.>\n\nAber das bedeutet, dass ich bis in alle Ewigkeit hier unten festsitze...\n\nUnd ich habe doch gerade erst gelernt, wie man segelt.\n\nOhhh... ich kann mich nicht entscheiden.\n\nHier, nehmt Ihr den Hammer. Ich stelle den Glitzerkram einfach auf den Boden und schaue weg.", sourceObjective = "Benutzt den Zinnplätter, um den Zinnpropheten zu zerstören.", completion = "Oh, wie schön hätte es sein können…", sourceObjectiveStatus = "unverified-source-field" }
quests[25744] = { id = 25744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhandlungen", description = "{name}, Ihr habt den Turbodampfer gut verteidigt! Ich habe noch eine andere Aufgabe, bei der Ihr mir helfen könnt.\n\nIch habe Crazzle Flinkspross und Kravel Kohlebart nach Nordosten geschickt, um mit den Überlebenden der Zentauren zu verhandeln, weil es in ihrer Heimat, den Spalthufanhöhen, ein Ölvorkommen gibt.\n\nIch glaube, dass diese stinkenden Halbpferde von diesem Vorkommen keine Ahnung haben, und wir werden versuchen, die Bohrrechte für das schwarze Gold so günstig wie möglich zu erhalten. Ich habe das Gefühl, dass Ihr Euch um die Verhandlungen kümmern solltet.\n\nWas haltet Ihr davon?", sourceObjective = "Sprecht mit Crazzle Flinkspross in Spalthufanhöhen in Tausend Nadeln.", completion = "<Crazzles Augen leuchten auf.>\n\nIch habe Kravel Kohlebart hochgeschickt, um mit den Häuptlingen zu verhandeln, aber jetzt da Ihr hier seid, werden wir die Bohrrechte in null Komma nichts erhalten!", sourceObjectiveStatus = "unverified-source-field" }
quests[25745] = { id = 25745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhandlungen", description = "{name}, Ihr habt den Turbodampfer gut verteidigt! Ich habe noch eine andere Aufgabe, bei der Ihr mir helfen könnt.\n\nIch habe Riznek und Rennstreckenleiter Zherin nach Nordosten geschickt, um mit den Überlebenden der Zentauren zu verhandeln, weil es in ihrer Heimat, den Spalthufanhöhen, ein Ölvorkommen gibt.\n\nIch glaube, dass diese stinkenden Halbpferde von diesem Vorkommen keine Ahnung haben, und wir werden versuchen, die Bohrrechte für das schwarze Gold so günstig wie möglich zu erhalten. Ich habe das Gefühl, dass Ihr Euch um die Verhandlungen kümmern solltet.\n\nWas haltet Ihr davon?", sourceObjective = "Sprecht mit Riznek in Spalthufanhöhen in Tausend Nadeln.", completion = "<Rizneks Augen leuchten auf.>\n\nIch habe Rennstreckenleiter Zherin hochgeschickt, um mit den Häuptlingen zu verhandeln, aber jetzt da Ihr hier seid, werden wir die Bohrrechte in null Komma nichts erhalten!", sourceObjectiveStatus = "unverified-source-field" }
quests[25746] = { id = 25746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sethrias Brut", description = "Unsere erste Aufgabe besteht darin, die Herde hier auszudünnen. An diesem Ort wimmelt es nur so von ihnen.\n\nTötet zunächst diese Drachkin und macht Euch erst später Gedanken darüber, warum wir hier sind.", sourceObjective = "Tötet 12 von Sethrias Dienern: Eine beliebige Kombination aus Zwielichtdrachkin oder Rüstungsschmieden der Zwielichtdrachkin.", completion = "Das scheint Euch zu liegen.\n\nIch mag Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[25747] = { id = 25747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Blick nach vorne", description = "Der Admiral hat die Informationen, die Ihr für ihn gesammelt habt, genutzt, um einen Vorposten unter der Terrasse im Westen einzurichten. Er bereitet sich dort auf eine Art Angriff auf die Naga vor.\n\nIhr solltet sofort zu ihm gehen und ihm von den Massen berichten, die Ihr beobachtet habt. Unsere Streitmacht ist klein. Ich mache mir Sorgen um unsere Soldaten, wenn wir uns in einen waghalsigen Angriff stürzen.\n\nNehmt mein Seepferd. Es kennt den Weg.", sourceObjective = "Sprecht mit Admiral Dvorek unter der südlichen Terrasse in den Ruinen von Vashj'ir.\n\nBenutzt Wellensprecherin Valorens Seepferd, um den Vorposten schnell zu erreichen.", completion = "Schön Euch wiederzusehen, {class}. Ich dachte schon fast, wir hätten Euch bei dem törichten Botengang für die Wellensprecherin verloren.\n\nIst dabei wenigstens etwas herausgekommen?", sourceObjectiveStatus = "unverified-source-field" }
quests[25748] = { id = 25748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deutliche Ziele", description = "Ich verstehe. Eure Nachrichten sind düster, aber ich bin nicht ganz unvorbereitet auf eine solche Lage. Ich wusste, dass unser Plan riskant ist, solange wir die genauen Zahlen der Naga nicht kennen, aber zu diesem Zweck haben wir ja diesen Vorposten eingerichtet.\n\nIch will Euch nicht belügen, {class}. Wenn wir die Naga nicht beschäftigt halten, werden sie uns angreifen. Wir haben weder die Anlagen noch die Männer, um eine geeignete Verteidigung zu errichten, daher kommt das für uns nicht in Frage.\n\nWir brauchen mehr Zeit. Könnt Ihr ihre Reihen im Süden ein wenig ausdünnen?", sourceObjective = "Tötet 10 Naga der Streitmächte, die sich unter der südwestlichen Terrasse auf der Grundebene zusammenziehen.", completion = "Auch im Süden scheinen sich mehr Naga zusammenzuziehen, als unsere Berichte angenommen haben. Wir müssen uns beeilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25749] = { id = 25749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht ganz unvorbereitet", description = "Ich habe Euer Gespräch mit dem Admiral gehört. Ich weiß, dass das, was wir tun, wahnsinnig klingt, aber wir haben einfach keine andere Wahl. Dort in der Höhle sind Leute, die sich auf uns verlassen.\n\nIch habe Aufklärer auf den verschiedenen Klippen in der Gegend aufstellen lassen. Bei den ganzen verstreuten Nagaspähern in der Gegend geht ihnen die Munition rasend schnell aus. Könntet Ihr ihnen mehr Armbrustbolzen bringen, um uns etwas Zeit zu verschaffen?", sourceObjective = "Bringt 8 Schachteln mit Armbrustbolzen zu den Aufklärern der Allianz, die sich auf den Vorsprüngen unter der südlichen Terrasse befinden.", completion = "Ihr seid wahrscheinlich das zuverlässigste Wesen, das ich je getroffen habe. Ich wünschte, meine Männer wären nur halb so gründlich wie Ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[25750] = { id = 25750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spannende Ablenkung", description = "Ha! Habt Ihr gesehen, wie der Admiral mir böse Blicke zuwirft und mich herablassend behandelt? Ich habe offen gestanden alle Hoffnung verloren, dass er versteht, welch gute Gelegenheit die Ruinen uns bieten, diesem ganzen Schlamassel etwas Positives abzugewinnen.\n\nIch habe gehofft, dass Ihr wieder auftauchen würdet. Ihr scheint <der Einzige zu sein, dem/die Einzige zu sein> der; ich vertrauen kann. Ich habe ein paar Tafeln wie diese verstreut in den Ruinen in der Nähe gesehen und ein Abpausset zusammengestellt, um sie zu abzuschreiben. Habt Ihr Lust?", sourceObjective = "Schreibt die 4 Tafeln der Hochgeborenen ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[25751] = { id = 25751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausreichende Inspiration", description = "Hallo! Ich reiße mir hier alle Beine aus, um den Angriff des Admirals vorzubereiten. Er hat große Hoffnungen und hochtrabende Pläne, um alle möglichen Dinge hoch in die Luft zu jagen! … Oder eher hoch ins Wasser? Ja, wohl eher das.\n\nAber um Dinge in die Luft zu jagen, braucht man SPRENGSTOFF! Ich habe keinen Sprengstoff. Es ist traurig. Sehr traurig.\n\nAber ich wurde ausreichend inspiriert, um eine Lösung zu finden. Die Tangblasen, die von den Ruinen hängen, enthalten ein überraschend explosives Gas. Könntet Ihr etwas davon für mich sammeln? Oh bitte, bitte!", sourceObjective = "Sammelt 8 aufgedunsene Tangblasen, die unterhalb der südwestlichen Terrasse hängen.", progress = "Tick, tack, tick, tack. Immer in Eile. Keine Zeit für neue Errungenschaften. Was würde ich nur dafür geben, wieder ein Labor zu haben!", completion = "Ihr seid wirklich mutig! Ich habe gesehen, wie Ihr alle möglichen Arten von Murlocs, Naga und spitzzähnigen Fischen bekämpft habt, aber das war nichts im Vergleich hierzu! Wie Ihr Euch diese Tangblasen einfach so unter den Arm klemmt ist eine ganz neue Ebene der Furchtlosigkeit. BUMM! Ihr könntet jede Sekunde in die Luft gehen.\n\nIhr seid ein {race} nach meinem Geschmack.", sourceObjectiveStatus = "unverified-source-field" }
quests[25752] = { id = 25752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blitzangriff", description = "Wir haben alles, was wir für den Angriff brauchen.\n\nWenn das, was Ihr sagt, wahr ist, solltet Ihr Euch während des Angriffs lieber fest an Euer Reittier klammern. Es ist sehr unwahrscheinlich, dass jemand von uns, der auf das offene Meer gerät, den Naga davonschwimmen kann.\n\nTötet so viele wie möglich. Wir werden den Angriff führen und treffen uns dann oben auf der zerbrochenen Terrasse, sobald wir die Sprengsätze aufgebraucht haben. Hoffentlich sind dann nur noch so wenige übrig, dass wir sie auf die altmodische Art erledigen können.", sourceObjective = "Sprecht mit Ingenieur Hexasept außerhalb des Gebäudes, um Euch dem Überfall anzuschließen. Benutzt dann Euren improvisierten Sprengstoff, um 100 Soldaten der Azsh'ir, 20 Wellenkreischer der Azsh'ir und 12 Archaeen der Azsh'ir zu töten.", progress = "Sprecht mit Ingenieur Hexasept, um Euch ein Reittier für den Angriff zu sichern.", completion = "Ihr habt Euch da oben großartig geschlagen! Ihr habt ihre Reihen zerschmettert, aber es waren viel mehr als geplant und die meisten unserer Truppen sind da draußen in den Massen der Naga untergegangen.\n\nWir müssen diese Position so lange wie möglich halten, um ihnen Zeit zu erkaufen. Hoffentlich schaffen es einige von ihnen noch zum Treffpunkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25753] = { id = 25753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefallen, aber nicht vergessen", description = "Das war ein Desaster! Die meisten unserer Männer sind Speeren zum Opfer gefallen, noch bevor sie überhaupt in der Nähe des Treffpunkts waren!\n\nWir werden diese Position sicher nicht mehr lange halten können, bevor die Naga uns überrennen. Wir müssen uns in den Südwesten begeben und so viele der Männer retten, wie wir nur können. Geht und tut alles, was in Eurer Macht steht.\n\nLange halten sie nicht mehr durch. Bitte, beeilt Euch!", sourceObjective = "Rettet 6 verletzte freiwillige Angreifer.", completion = "Danke. Wirklich.\n\nWir müssen diese Männer so schnell wie möglich von hier wegbringen. Ich bin mir sicher, wir begegnen uns schon bald am Vorposten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25754] = { id = 25754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einschätzung des Erfolgs", description = "Boshafte Rüpel… Sie haben mit diesen Speeren einen ganz schönen Schaden angerichtet.\n\n<Der Admiral zuckt ein bisschen, als er sich die Wunde an der Seite hält.>\n\nWir werden hier so lange wie möglich durchhalten, damit alle Männer es schaffen. Ich brauche jemanden, der ausspioniert, wie viele es noch sind. Ich möchte wissen, wie viel Schaden wir ihnen zugefügt haben. Eine ihrer größten Gruppen war um die Ecke im nordwestlichen Teil dieser runden Terrasse, die andere war etwas weiter im Norden, in einem kleinen Tunnel, der auch Teil der mittleren Ebene der Ruinen ist.\n\nSeid Ihr bereit?", sourceObjective = "Späht den nordwestlichen Teil der runden Terrasse und den Tunnel unter der Haupttreppe im Norden aus. Beide Orte befinden sich auf der Terrasse von Nar'shola, der mittleren Ebene der Ruinen.", completion = "Immer noch so viele? Sie müssen hier etwas sehr Wichtiges vorhaben, wenn sie so zahlreich auftauchen.\n\nIch will ehrlich zu Euch sein, {name}, denn das bin ich Euch schuldig: Ich weiß nicht, wie viel Hoffnung besteht. Wir werden uns in Kürze zurückziehen, aber wir werden uns nicht verteidigen können, falls sie zurückschlagen. Wir haben keinen Ort, an den wir flüchten können... Und uns gehen die Optionen aus.\n\nEs tut mir leid, ich sollte meine Gedanken für mich behalten. Tut mir einen Gefallen und erwähnt den Truppen gegenüber nichts davon. Ich werde mir etwas einfallen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25755] = { id = 25755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visionen der Vergangenheit: Das Massaker von Biel'aran", description = "Ja, ich weiß, es ist in Zeiten wie diesen viel verlangt, aber Ihr müsst Euch einen Moment lang von dieser Niederlage losreißen.\n\nIch werde mich um diese Soldaten kümmern. Ihr müsst jedoch den Ort im Westen finden, an dem die Schlacht mit dem General der Kvaldir ausgetragen wurde, von der Ihr mir erzählt habt. Von dort aus solltet Ihr mehr über die Erlebnisse der Kriegsmaid erfahren können. Ich habe das untrügliche Gefühl, dass der Schlüssel zum Sieg über die Naga in dieser Kriegsmaid liegt.\n\nBitte, beeilt Euch. Ich tue alles, was ich kann, um Euch Zeit zu verschaffen.", sourceObjective = "Werdet Zeuge des weiteren Verlaufs der Geschichte der Kriegsmaid, indem Ihr ihre gebrochene Klinge am Sterbeort des Generals der Kvaldir benutzt.", completion = "Ihr seid fertig! Gerade rechtzeitig. Ich glaube nicht, dass wir ihnen noch lange hätten standhalten können.\n\nEin Artefakt? Ist das vielleicht etwas, was wir gegen die Naga einsetzen können? Ich schätze, dann müssten wir es erstmal finden.\n\nDoch möglicherweise müssen wir uns erst dringenderen Angelegenheiten widmen, bis wir die Gelegenheit haben, dies weiter zu verfolgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25756] = { id = 25756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zehrt an Zherin!", description = "Wenn wir die Bohrrechte erhalten wollen, müssen wir wissen, was für ein Angebot die Horde unterbreiten wird. Wir können die Bohrrechte nur bekommen, wenn unser Angebot besser ist!\n\nDer Vermittler der Horde, Rennstreckenleiter Zherin, ist gerade vor Ort in Gesprächen mit den Khans. Ich schlage vor, Ihr begebt Euch auch dorthin, und überzeugt Zherin davon, das Angebot der Horde auszuhändigen.\n\nIhr müsst ihn nicht töten... wir sind ja keine Wilden! Es reicht, wenn Ihr etwas arg an seinen Nerven zehrt.", sourceObjective = "Erhaltet das Angebot der Horde.", progress = "Habt Ihr das Angebot der Horde erhalten? Was bieten sie für die Bohrrechte an?", completion = "Was?! Woher hat die Horde so viel Gold für ein Angebot?\n\nSo viel Gold haben wir nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[25757] = { id = 25757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas hart zu Kohlebart!", description = "Wenn wir die Bohrrechte erhalten wollen, müssen wir wissen, was für ein Angebot die Allianz unterbreiten wird. Wir können die Bohrrechte nur bekommen, wenn unser Angebot besser ist!\n\nDer Vermittler der Allianz, Kravel Kohlebart, ist gerade vor Ort in Gesprächen mit den Khans. Ich schlage vor, Ihr begebt Euch auch dorthin, und überzeugt Kohlebart davon, das Angebot der Allianz auszuhändigen.\n\nIhr müsst ihn nicht töten... wir sind ja keine Wilden! Es reicht, wenn Ihr ihn ein bisschen hart rannehmt.", sourceObjective = "Erhaltet das Angebot der Allianz.", progress = "Habt Ihr das Angebot der Allianz erhalten? Was bieten sie für die Bohrrechte an?", completion = "Was?! Woher hat die Allianz so viel Gold für ein Angebot?\n\nSo viel Gold haben wir nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[25758] = { id = 25758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Lücke in ihrer Rüstung", description = "Seht Ihr, was sie da tun? Sie statten ihre Drachkin mit Panzerplatten aus! Das muss Todesschwinges Idee gewesen sein.\n\nDiese Zwielichtmoloche sehen aus, als wären sie unbesiegbar, sobald sie fertig sind. Es muss doch einen Weg um diesen Panzer herum geben!\n\nGeht dorthin und holt Euch einige der Panzerplatten des Schattenhammers, die noch nicht angebracht wurden. Wir müssen herausfinden, wie wir das verhindern können!", sourceObjective = "Sammelt 8 Panzerplatten des Schattenhammers.", progress = "Habt Ihr ein paar Panzerplatten bekommen können? Musstet Ihr jemanden töten, um sie zu bekommen?\n\nIch hoffe doch sehr!", completion = "Schaut Euch diese Dinger an. Uff, die Runen schmerzen mir in den Augen. Diese hier soll Fleisch versengen? Im Ernst? Autsch! Moment mal…\n\nDiese Platten müssen direkt im Fleisch festgenietet werden. Die Schmerzen müssen unerträglich sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[25759] = { id = 25759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es hat sich ausgehammert", description = "Der Riss, der hier war, hat dieses seltsame Gerät hinterlassen, aber wieso?\n\nVielleicht hat jemand in einer der Hauptstädte mehr Informationen darüber.", sourceObjective = "Bringt das mysteriöse Gerät nach Orgrimmar, Unterstadt, Silbermond oder Donnerfels und zeigt es einem Botschafter des Irdenen Rings.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[25760] = { id = 25760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visionen der Vergangenheit: Die Invasion von Vashj'ir", description = "Das Bruchstück, das Ihr gefunden habt, scheint von Nagahand geschaffen zu sein. Ich hatte gehofft, ein starkes Fokusobjekt wie dieses für einen Zauber zu finden, an dem ich gerade arbeite. Mit diesem Zauber könnten wir einen Blick in die kürzliche Vergangenheit werfen.\n\nIch habe die Klinge verzaubert, aber Ihr müsst sie an einen Ort bringen, von dem wir wissen, dass ihr Besitzer sich dort aufgehalten hat. Ich möchte, dass Ihr zurück an die Stelle reist, wo Ihr die Klinge gefunden habt und sie dort benutzt.\n\nVielleicht können wir so mehr über die Pläne der Naga hier erfahren. Oder noch besser: Vielleicht finden wir einen ihrer Schwachpunkte, sodass wir eine bessere Chance haben, sie zu besiegen.", sourceObjective = "Benutzt die Klinge der Kriegsmaid der Naz'jar auf dem Schlachtfeld am südöstlichen Ende der Ruinen.", completion = "Eine Kriegsmaid? Davon habe ich noch nie gehört.\n\nSo wie Ihr mir die Sache schildert, scheinen die Truppen der Naga weitaus zahlreicher zu sein, als der Admiral es sich in seinen kühnsten Träumen vorstellt. Vielleicht können wir mehr von der Klinge erfahren, wenn wir andere Orte finden, an denen diese Kriegsmaid zugegen war. Ich habe nur Angst um den Admiral und seine Soldaten. Wir müssen sie warnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25761] = { id = 25761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demontage", description = "Wir müssen diese Moloche aufhalten, bevor sie komplett in Rüstung gehüllt sind. Im Augenblick sind sie noch verwundbar, aber auch nur, wenn wir an den Platten vorbei in das kranke Fleisch darunter stoßen können.\n\nNehmt mein Messer und rammt es zwischen die Platten der bewehrten Moloche, um ihnen die Rüstung zu rauben.\n\nSobald sie aus ihrer Trance erwachen, solltet Ihr Euch auf einen harten Kampf gefasst machen. Löst einfach weiter ihre Rüstung und haltet diese Moloche auf!", sourceObjective = "Benutzt Thisalees Messer, um 3 Zwielichtmoloche zu wecken und zu töten. Das Messer kann mehrfach verwendet werden, um die Rüstung eines Molochs herunterzureißen.", progress = "Oh, gut.\n\nIhr seid noch am Leben.", completion = "Das nenne ich atemberaubende Klingenkunst, {name}!\n\nUnd wieder eine Bedrohung weniger auf dem Hyjal, um die wir uns sorgen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25762] = { id = 25762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die uralte Kohlenpfanne", description = "Was haben wir denn hier? <Ein/Eine:r> {race}? Ihr seid wohl hier, um unser Land mit Süßholzraspelei und Versprechen zu stehlen?\n\nIhr könnt mich nicht täuschen. Ich habe schon viele Winter gesehen und weiß, wie man mit jemandem wie Euch umgehen muss. Die Khans hören jedoch nicht mehr auf die Ältesten, wie sie es einst taten.\n\nDa Ihr schon einmal hier seid, werde ich dafür sorgen, dass Ihr Euch nützlich macht. Als das Wasser über uns hereinbrach, hat der große Wassergeist Aquarian die uralte Kohlenpfanne in der Spalthufhöhle gelöscht.\n\nEntfacht die Kohlenpfanne wieder. Aquarian wird erscheinen. Bringt mir die heilige Flamme.", sourceObjective = "Entfacht die uralte Kohlenpfanne wieder und erhaltet die heilige Flamme.", progress = "Habt Ihr die heilige Flamme? Wagt es nicht, sonst mit mir zu sprechen, {race}!", completion = "Ihr habt mir diesen Gefallen getan, um Euch bei mir einzuschmeicheln. So leicht ist das aber nicht.\n\nIch weiß genau, was Ihr vorhabt. Das Meer hat es zwar nicht geschafft, aber der große Luftgeist wird Euch und Euer Volk für all die Vergehen bestrafen, die den Elementen gegenüber begangen wurden.\n\nVerschwindet aus meinen Augen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25763] = { id = 25763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kodex der Schatten", description = "<Dieses kunstvolle Buch besteht aus Hunderten von Seiten feinsten Pergaments und ist in Schiefer gebunden. Es ist in vielen Sprachen geschrieben, wovon Euch die meisten unbekannt sind. Aufwändig gezeichnete Bilder zeigen Zauberer oder gar ganze Gebäude, die hinter Schleiern aus Schatten verschwinden.>\n\n<Viele der Bilder zeigen magische Artefakte wie jene, die Ihr um das Lager herum seht. Ihr vermutet, dass die Drachendame Sethria etwas versteckt halten möchte. Thisalee will sicher davon erfahren!>", sourceObjective = "Meldet Thisalee Krähe bei Sethrias Nest auf dem Hyjal Eure Entdeckungen.", completion = "Sie tun was?\n\nSie verhüllen etwas? Aber natürlich! Damit unsere Späher in den Lüften es nicht mit ihren Adleraugen entdecken können!", sourceObjectiveStatus = "unverified-source-field" }
quests[25764] = { id = 25764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eierjagd", description = "Himmelsfürst Omnuron möchte, dass wir Avianas Ei finden. Ich kann Euch fast schon garantieren, dass es von einem von Sethrias Schattengeräten getarnt wird.\n\nSucht um das Lager herum nach Schattentarnungsgeneratoren und schaltet diese Dinger aus, bis Ihr das Ei gefunden habt.\n\nSobald Ihr es enttarnt habt, ruft die anderen Druiden herbei. Verteidigt das Ei, bis wir es in Sicherheit gebracht haben.\n\nLos, holt Euch das Ei, {name}!", sourceObjective = "Deaktiviert die Schattentarnungsgeneratoren, bis Ihr Avianas Ei gefunden habt. Sobald das Ei enttarnt wurde, verteidigt es, bis die Druiden der Kralle es in Sicherheit bringen können.", completion = "Wir haben es geschafft, {name}! Avianas Ei sollte bald schon sicher in den Zweigen ihres Schreins liegen.\n\nMeint Ihr, dass sie dann wirklich zu uns zurückkehren wird?", sourceObjectiveStatus = "unverified-source-field" }
quests[25765] = { id = 25765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sagt ihnen, Koko schickt Euch", description = "<Ein mächtiger/Eine mächtige:r> {race} wie Ihr wäre in Nordwacht wirklich von Nutzen. Wir haben eine Niederlage im Südlichen Brachland einstecken müssen und benötigen Eure Hilfe! Hättet Ihr Interesse daran, der Allianz behilflich zu sein?\n\nDie Bombe? Ja, sie ist ein Problem, aber das Steinkrallengebirge zeichnet sich nicht gerade durch seinen Grundstückspreis aus. Diese Gegend war schon ein Drecksloch, bevor die Horde ihre Klauen danach ausgestreckt hat!\n\nIch überlasse die Entscheidung Euch. Wenn Ihr uns im Brachland aushelfen wollt, nehmt mein Pferd Blaustahl. Er grast an der Kreuzung südlich von hier. Er wird Euch an der ersten Orcsperre vorbeitragen.", sourceObjective = "Meldet Euch bei Truppenkommandant Valen am Basislager der Nordwachtexpedition im Steinkrallengebirge.", completion = "Kosak hat Euch geschickt, ja? Erstaunlich. Ich hatte mit Sicherheit angenommen, dass er bereits tot ist.\n\nNun, wenn Ihr es an der Blockade vorbei geschafft habt, dann habt Ihr auf jeden Fall etwas, das wir brauchen können.\n\nHabt Ihr irgendwelche Neuigkeiten von der Horde? Was machen sie? Wohin gehen sie? Erzählt mir alles.", sourceObjectiveStatus = "unverified-source-field" }
quests[25766] = { id = 25766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkanes Vermächtnis", description = "Der Zorn der Elementare hat im Herzen des Steinkrallengebirges eine Stadt der Hochgeborenen ans Licht gebracht.\n\nDirekt im Südwesten vor hier, hinter dem Sishircanyon, findet Ihr die Ruinen von Eldre'thar. In den Ruinen liegen Schätze, die seit zehntausenden Jahren nicht von Sterblichen angerührt wurden!\n\nNehmt dieses Gerät und benutzt es gegen die Geister der Hochgeborenen, die die Ruinen bewohnen. Es wird... ihre Seelen zur letzten Ruhe betten und außerdem wertvolle Daten sammeln, die ich später auswerten kann.", sourceObjective = "Benutzt das Gefängnis der Hochgeborenen, um 5 Hochgeborenengeister zu binden.", completion = "Ich versichere Euch, Ihr Einfaltspinsel, die Geister, die Ihr gefangen habt, finden jetzt ihre Ruhe. Lasst Euch nicht von ihren Protesten aus der Ruhe bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25767] = { id = 25767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erinnerungen einfangen", description = "Der große Kataklysmus hat im Herzen des Steinkrallengebirges eine Stadt der Hochgeborenen ans Licht gebracht. Ihr müsst Euch nach Südwesten zu den Ruinen von Eldre'thar begeben. Wenn Ihr dort seid, durchsucht die Gegend nach uralten Relikten. Bringt die Relikte zu mir, damit ich sie untersuchen kann, {name}.\n\nLos! Wir dürfen den Arkanisten nicht warten lassen!", sourceObjective = "Besorgt 8 Relikte von Eldre'thar.", progress = "Habt Ihr die uralten Relikte gefunden?", completion = "Wunderbar! Arkanist Valdurian wird außerordentlich zufrieden sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[25768] = { id = 25768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer frei: Mirkfallonposten!", description = "Späherkommandant Barus ist am Mirkfallonposten im Nordwesten stationiert und hat die Bombe der Horde entdeckt. Der Heißluftballon von Krom'gar, an dem die Bombe angebracht ist, befindet sich momentan bei der neuen Goblintankstelle am Mirkfallonsee. Das könnte die Gelegenheit sein, die wir brauchen, um das Ding ein für alle Male zu beseitigen.\n\nNehmt Eure Siebensachen, {name}, und macht Euch auf den Weg! Späherkommandant Barus erwartet Eure Ankunft am Mirkfallonposten.\n\nUnd {name}, Eure Hartnäckigkeit macht der Stärke und Tapferkeit der Allianz alle Ehre!\n\nMöge der Ruhm mit Euch sein!", sourceObjective = "Meldet Euch bei Späherkommandant Barus am Mirkfallonposten im Steinkrallengebirge.", completion = "Ich nehme einmal an, dass Ihr den Heißluftballon von Krom'gar auf Eurem Weg hierher gesehen habt? Wenn nicht, lasst Eure Augen untersuchen. Er schwebt direkt über der Ölplattform.", sourceObjectiveStatus = "unverified-source-field" }
quests[25769] = { id = 25769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brachweiher ruft", description = "Ihr seid hier? Worauf wartet Ihr - eine persönliche, gravierte Einladung? Lord Brachweiher ruft, Narr! Geht zu ihm - jetzt!", sourceObjective = "Sprecht mit Lord Brachweiher an der Scherwindfeste im Steinkrallengebirge.", completion = "Schön, Euch wiederzusehen, {name}. Ich habe Neuigkeiten vom Mirkfallonsee.", sourceObjectiveStatus = "unverified-source-field" }
quests[25770] = { id = 25770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fasslieferung", description = "Also gut. Wir müssen dieses Bier sofort an seinen Bestimmungsort bringen!\n\nEisenschmiede hat eine Gruppe Feldmesser ausgeschickt, um den Schaden im Sumpfland zu überprüfen, der bei dem Dammbruch entstanden ist. Forba Fliesmeißel leitet die Expedition... und glaubt mir, Ihr wollt Euch nicht mit ihr anlegen!\n\nMit einer Ladung Bier bei ihr aufzutauchen, kann nicht schaden. Geht und bringt ihr das hier und sie wird Euch vielleicht bitten, die ein oder andere Arbeit für sie zu verrichten.", sourceObjective = "Bringt das Gebirgsjägerbier zu Forba Fliesmeißel an Fliesmeißels Messstation.", progress = "Ja? Was habt Ihr da für mich?", completion = "Ha! Schön, dass die hohlköpfigen Gebirgsjäger genug Grips haben, um das Bier einem richtigen Mann zu überlassen, damit die Arbeit auch erledigt wird.\n\nWillkommen in meiner Messstation. Wenn Euch der Sinn danach steht, Eisenschmiede zu helfen, indem Ihr die Jobs einiger nutzloser, fauler Säcke, die sich Zwerge nennen, übernehmt, dann seid Ihr an der richtigen Adresse!", sourceObjectiveStatus = "unverified-source-field" }
quests[25771] = { id = 25771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des einen Draeneis Plunder...", description = "Ein Bruchstück glitzernden Steins liegt vor Euch. Ihr spürt, dass dieser Gegenstand für jemand in den Verwüsteten Landen von großem Wert sein könnte.", sourceObjective = "Bringt das unvollständige Draenethystfragment zu Kum'isha dem Sammler in den Verwüsteten Landen.", progress = "Und? Draenethyst?", completion = "Nur ein Splitter? Pah! Das nützt mir gar nichts! Nehmt Eure Belohnung und geht mir aus den Augen.\n\nKlingt bekannt? Sollte es auch, weil ich es tausend Mal am Tag sage.\n\nOh, wie ich diese Welt hasse.", sourceObjectiveStatus = "unverified-source-field" }
quests[25772] = { id = 25772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kum'ishas Bemühungen", description = "Vor Euch liegt eine schimmernde Kugel. Ihr spürt, dass dieser Gegenstand für jemand in den Verwüsteten Landen von großem Wert sein könnte.", sourceObjective = "Bringt die fehlerlose Draenethystsphäre zu Kum'isha dem Sammler in den Verwüsteten Landen.", progress = "Habt Ihr eine fehlerlose Draenethystsphäre gefunden?", completion = "Einfach erstaunlich. Ich hatte so meine Zweifel, dass irgendwer noch eine Sphäre finden würde, aber hier ist sie und pulsiert in meinen Händen.\n\nGut gemacht, {name}!\n\nSolltet Ihr noch weitere finden - wobei ich glaube, dass das unmöglich ist -, dann bringt sie mir und ich werde Euch erneut belohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25773] = { id = 25773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein natürlicher Vorfall", description = "Dieser Splitter ist alles, was von dem Riss übrig geblieben ist. Die Verbindung zwischen Splitter und Riss ist uns nicht bekannt, aber vielleicht würde jemand mit mehr Weisheit uns weiterhelfen können.\n\nSucht einen Botschafter des Irdenen Rings in einer der Hauptstädte auf. Ich glaube, sie sind auf der Suche nach Gegenständen wie diesen.", sourceObjective = "Bringt den Elementarsplitter zu einem Botschafter des Irdenen Rings in Eisenschmiede, Sturmwind, Exodar oder Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[25774] = { id = 25774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Katzengold", description = "Von so viel Gold, wie die Horde anbietet, können wir NUR TRÄUMEN. {name}, wir müssen etwas unternehmen, oder wir laufen in Gefahr, die Bohrrechte nicht erhalten zu können!\n\nOh, Moment! Eine der Unterwasseruntersuchungen, die wir nach dem Kataklysmus angestellt haben, hat von einer Art Erz berichtet, das wie Gold aussieht und vom Untergrund nach oben befördert wurde. Das ist die Idee!\n\nReist zum alten Revier der Zentauren, Spalthufklippe und Spalthufhöhle westlich von hier, und grabt etwas von diesem Material aus.", sourceObjective = "Sammelt 8 Pyriterzbrocken.", progress = "Wenn Ihr genug von dem Pyrit bringt, können wir es mit schnell mit ein wenig Farbe aufarbeiten, schön stapeln, und diese Palette könnt Ihr dann dem Häuptling bringen.", completion = "Genial! Jetzt müssen wir nur die Goldfarbe finden - ich weiß, dass sie hier irgendwo ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[25775] = { id = 25775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Katzengold", description = "Von so viel Gold, wie die Allianz anbietet, können wir NUR TRÄUMEN. {name}, wir müssen etwas unternehmen, oder wir laufen in Gefahr, die Bohrrechte nicht erhalten zu können!\n\nOh, Moment! Eine der Unterwasseruntersuchungen, die wir nach dem Kataklysmus angestellt haben, hat von einer Art Erz berichtet, das wie Gold aussieht und vom Untergrund nach oben befördert wurde. Das ist die Idee!\n\nReist zum alten Revier der Zentauren, Spalthufklippe und Spalthufhöhle westlich von hier, und grabt etwas von diesem Material aus.", sourceObjective = "Sammelt 8 Pyriterzbrocken.", progress = "Wenn Ihr genug von dem Pyrit bringt, können wir es mit schnell mit ein wenig Farbe aufarbeiten, schön stapeln, und diese Palette könnt Ihr dann dem Häuptling bringen.", completion = "Genial! Jetzt müssen wir nur die Goldfarbe finden - ich weiß, dass sie hier irgendwo ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[25776] = { id = 25776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sethrias Untergang", description = "Während Ihr Sethrias Nest überfallen habt, gab es einen regen Austausch von Botschaften zwischen uns und dem Schrein. Himmelsfürst Omnuron hat sich zunächst geziert, aber schließlich konnte ich meine Druidenfreunde überreden, einen direkten Angriff auf Sethria selbst zu wagen.\n\nAlle haben meinem Plan zugestimmt... unter einer Voraussetzung. IHR sollt den Angriff anführen.\n\nNehmt diese Signalrakete und stellt Euch Sethria auf dem hinteren Sims. Wenn sie ihr wahres Ich zeigt und in ihre Drachenform wechselt, schießt die Rakete ab und fordert Verstärkung an!", sourceObjective = "Tötet den Drachen Sethria. Sobald sie ihre wahre Form offenbart, benutzt die Signalrakete, um Verstärkung zu rufen.", progress = "Wenn ein geringerer Drache wie Sethria uns schon so viele Probleme bereiten kann, möchte ich gar nicht wissen, was der Schattenhammer sonst noch auf Lager hat…", completion = "Sethria ist nicht mehr! Ich wusste, dass es das Risiko wert ist.\n\nIch bleibe hier, um nach Überlebenden zu suchen, aber ich schätze, Eure Anwesenheit wird am Schrein gewünscht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25777] = { id = 25777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorwärts nach Menethil", description = "Diese Neuigkeiten müssen so schnell wie möglich nach Menethil gelangen. Ich werde Euch mit meinem schnellsten Widder auf den Weg schicken, {name}.\n\nEr kennt den Weg - Ihr müsst nur darauf achten, dass Ihr fest im Sattel sitzt und Euch gut festhaltet.\n\nTrödelt nicht im Lager herum. Wir müssen die Nachricht schnell überbringen!", sourceObjective = "Liefert Fliesmeißels Bericht bei Hauptmann Starkfaust im Hafen von Menethil ab.", progress = "Willkommen in Menethil, Fremder. Ich hoffe, Ihr habt gute Neuigkeiten oder etwas Hochprozentiges bei Euch.", completion = "Lasst mich mal sehen.\n\nNa großartig... \"Schwerwiegende geologische Instabilität\"? \"Gefahr einer plötzlichen, massiven topologischen Destabilisierung\"?\n\nSchön zu hören, dass hier etwas Schlimmes passieren könnte. Dann sollten wir vielleicht besser unsere überflutete Stadt zusammenpacken und mit ihr irgendwo hinfliegen, wo es sicher ist!\n\nBah!", sourceObjectiveStatus = "unverified-source-field" }
quests[25778] = { id = 25778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falsches Gold für schwarzes Gold", description = "Jetzt, da das \"Gold\" fertig ist, möchte ich, dass Ihr es zu Khan Ablinh bringt. Er wird davon so überwältigt sein, dass ich fast davon ausgehe, dass er uns dabei helfen wird, die Bohrtürme aufzustellen. Die Pferdestärke könnten wir gut gebrauchen.\n\nHaha, guter Witz, was? Pferdestärke?", sourceObjective = "Bringt die Palette voller \"Gold\" zu Khan Ablinh in den Spalthufanhöhen in Tausend Nadeln.", progress = "Was ist das? Wirklich viel Gold habt Ihr da.", completion = "Stellt die Palette einfach auf den Boden, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25779] = { id = 25779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falsches Gold für schwarzes Gold", description = "Jetzt, da das \"Gold\" fertig ist, möchte ich, dass Ihr es zu Khan Blizh bringt. Er wird davon so überwältigt sein, dass ich fast davon ausgehe, dass er uns dabei helfen wird, die Bohrtürme aufzustellen. Die Pferdestärke könnten wird gut gebrauchen.\n\nHaha, guter Witz, was? Pferdestärke?", sourceObjective = "Bringt die Palette voller \"Gold\" zu Khan Blizh in den Spalthufanhöhen in Tausend Nadeln.", progress = "Was ist das? Wirklich viel Gold habt Ihr da.", completion = "Stellt die Palette einfach auf den Boden, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25780] = { id = 25780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Burg Menethil", description = "Wir hatten uns kaum nach der Flut wieder zusammengerauft, als die Dunkeleisenzwerge die Stadt angriffen. Meine Männer und ich sind der Stadtbevölkerung zu Hilfe geeilt, aber die irren Dunkeleisenzwerge haben sich in die Burg zurückgezogen.\n\nSie haben sich da richtig eingegraben und wir können die Burg nicht zerstören. Nicht jetzt, da die halbe Stadt schon in Trümmern liegt.\n\nNehmt meinen Platz ein, {name}. Ich würde mir den Anführer ja vorknöpfen, aber er hat mir einen schweren Schlag versetzt. Verschafft Euch Zugang zur Burg, tötet Horghast und bereitet allem ein Ende!", sourceObjective = "Tötet Horghast Loderwahn.", completion = "Er ist tot! Den Schöpfern sei Dank...\n\nMir gefällt gar nicht, wie die aussehen. Die Dunkeleisenzwerge, mit denen ich bisher zu tun hatte, waren niemals so verrückt. Irgendwas ist mit diesen Schwachköpfen geschehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[25781] = { id = 25781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es hat sich ausgehammert", sourceObjective = "Bereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
