quests[25788] = { id = 25788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es hat sich ausgehammert", sourceObjective = "Bereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[25789] = { id = 25789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es hat sich ausgehammert", description = "Der Riss, der hier war, hat dieses seltsame Gerät hinterlassen, aber wieso?\n\nVielleicht hat jemand in einer der Hauptstädte mehr Informationen darüber.", sourceObjective = "Bringt das mysteriöse Gerät nach Orgrimmar, Unterstadt, Silbermond oder Donnerfels und zeigt es einem Botschafter des Irdenen Rings.", sourceObjectiveStatus = "unverified-source-field" }
quests[25790] = { id = 25790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zu Crazzle", description = "Ich bin NICHT dumm!\n\nGeht zu Eurem Meister zurück und sagt ihm, dass es mit der Sache NICHTS wird! Falls Ihr überhaupt lebend bei ihm ankommen solltet.", sourceObjective = "Sprecht mit Crazzle Flinkspross in Spalthufanhöhen in Tausend Nadeln.", completion = "Sie haben WAS?!", sourceObjectiveStatus = "unverified-source-field" }
quests[25791] = { id = 25791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zu Riznek", description = "Ich bin NICHT dumm!\n\nGeht zu Eurem Meister zurück und sagt ihm, dass es mit der Sache NICHTS wird! Falls Ihr überhaupt lebend bei ihm ankommen solltet.", sourceObjective = "Sprecht mit Riznek in Spalthufanhöhen in Tausend Nadeln.", completion = "Sie haben WAS?!", sourceObjectiveStatus = "unverified-source-field" }
quests[25792] = { id = 25792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorwärts drängen", description = "Die meisten der Gebirgsjäger und Dampfpanzer in Dun Morogh kämpfen an der Frontlinie der Frostmähnen, die sich uns aus Südosten nähert. Wir können kaum die Trolle zurückhalten, geschweige denn, in ihr Dorf vorrücken und ihren Anführer angreifen.\n\nSie haben unseren Zugangspfad mit mysteriösen Totems blockiert, die allen sich nähernden Gebirgsjägern die Luft nehmen und ihre Opfer dadurch hilflos ihren Feinden überlassen. Auf diesem Stein ist eine Rune des Feuers eingraviert. Er sollte in der Lage sein, die Totems zu zerstören und unsere Gebirgsjäger zu befreien.", sourceObjective = "Benutzt die Rune des Feuers, um 4 Totems der Konstriktion an der Frontlinie der Frostmähnen zu zerstören.", completion = "Endlich gibt es mal gute Nachrichten von der Frontlinie der Frostmähnen. Ich werde dafür sorgen, dass die Gebirgsjäger sofort vorrücken und angreifen. Jetzt müssen wir unseren Gnomverbündeten am Depot signalisieren, dass sie ihren Vormarsch beginnen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[25793] = { id = 25793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ausufernden Tiefen", description = "Sinn und Zweck dieser Basis war es, im Steinkrallengebirge für Theramore Fuß zu fassen und eine Nachschublinie für die Nachtelfen zu eröffnen. Leider hat die Horde erbitterte Gegenwehr geleistet. Höllschreis Armeen sind mächtig und unnachgiebig. Ich habe so eine Heftigkeit von der Horde seit dem Zweiten Krieg nicht erlebt.\n\nJetzt scheint es so, dass die Mine, die die Forscherliga ausgehoben hat, von der Horde dazu benutzt wird, uns zu umgehen. Wir müssen die Mine versiegeln!", sourceObjective = "Sprecht mit Stahlzeh McGee an den Ausufernden Tiefen im Steinkrallengebirge.", completion = "Versiegeln? Das ist ganz schön viel Arbeit, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[25794] = { id = 25794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuflucht unter dem Meer", description = "Ich glaube, ich habe den Verfasser Eurer Notiz gefunden, Freund.\n\nWie es aussieht, braucht er dringend Hilfe, um zu überleben.\n\nIch werde eine meiner Seherkugeln vorbereiten, damit Ihr ihn selbst sehen könnt.", sourceObjective = "Benutzt Erunaks Seherkugel, um die Position der Tiefennebelgrotte zu sehen.", completion = "Wir müssen uns beeilen!\n\nWie Ihr seht, hat er nicht mehr viel Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25795] = { id = 25795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Schrein", description = "Avianas Ei sollte sicher am Schrein angekommen sein. Geht ruhig und seht es Euch an! Choluna weiß sicher, was zu tun ist.\n\nIch werde unsere Aufgabe hier noch abschließen und stoße dann später zu Euch.", sourceObjective = "Kehrt zu Choluna am Schrein von Aviana auf dem Hyjal zurück.", completion = "{name}! Ist es wahr, dass Ihr einen Angriff gegen einen Zwielichtdrachen geführt habt?\n\nIhr seid wirklich der Herold der Ahnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25796] = { id = 25796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enteignung", description = "Es ist Schicksal, das wir dieses Öl erhalten haben. Dass die Zentauren diesen Ort gewählt haben, als das Meer über uns hereingebrochen ist, ist Pech.\n\nPech für sie, sollte ich sagen.\n\nSie haben uns ins Gesicht gespuckt, {name}. Wir haben ihnen ein großzügiges Angebot unterbreitet, und es war ein Fehler, es nicht anzunehmen. Jetzt werden... werdet Ihr ihnen zeigen, worin dieser Fehler lag.\n\nVertreibt die Zentauren von den Spalthufanhöhen. Das Öl muss fließen!", sourceObjective = "Tötet 15 Zentauren der Spalthufanhöhen.", completion = "Das wird ihnen eine Lektion erteilen. Ihr habt die Zentauren so sehr eingeschüchtert, dass wir nur sehr wenig Wachen des Turbodampfers brauchen werden, um das Gebiet zu sichern.\n\nZumindest wird es so sein, nachdem wir mit ihrem angeblichen Anführer, dem Luftelementar, fertig sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[25797] = { id = 25797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enteignung", description = "Es ist Schicksal, das wir dieses Öl erhalten haben. Dass die Zentauren diesen Ort gewählt haben, als das Meer über uns hereingebrochen ist, ist Pech.\n\nPech für sie, sollte ich sagen.\n\nSie haben uns ins Gesicht gespuckt, {name}. Wir haben ihnen ein großzügiges Angebot unterbreitet, und es war ein Fehler, es nicht anzunehmen. Jetzt werden... werdet Ihr ihnen zeigen, worin dieser Fehler lag.\n\nVertreibt die Zentauren von den Spalthufanhöhen. Das Öl muss fließen!", sourceObjective = "Tötet 15 Zentauren der Spalthufanhöhen.", completion = "Das wird ihnen eine Lektion erteilen. Ihr habt die Zentauren so sehr eingeschüchtert, dass wir nur sehr wenig Wachen des Turbodampfers brauchen werden, um das Gebiet zu sichern.\n\nZumindest wird es so sein, nachdem wir mit ihrem angeblichen Anführer, dem Luftelementar, fertig sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[25798] = { id = 25798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigt den Turm!", description = "Ich werde diesen Ort nicht mit leeren Händen verlassen! Ihr etwa?\n\nIch bin mir sicher, dass Ihr Euch gefragt habt, was wohl in der riesigen Kiste ist. Nun, Ihr müsst nicht länger warten. Bringt einen unserer Bohrtürme zu den Öltümpeln, und bohrt nach Öl für uns.\n\nIhr müsst natürlich damit rechnen, dass die Zentauren angreifen werden. Verteidigt den Turm lange genug, um ein oder zwei Fässer füllen zu können.", sourceObjective = "Verteidigt den Ölbohrturm.", completion = "Öl! Schwarzes Gold! Tanaristee!\n\nWir sind reich! Jetzt müssen wir uns nur den übrigen lästigen Zentauren annehmen. Mit dem ganzen Gold, das wir verdienen werden, können wir uns sicher leisten, sie auf irgendeine andere Klippe umzusiedeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[25799] = { id = 25799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigt den Turm!", description = "Ich werde diesen Ort nicht mit leeren Händen verlassen! Ihr etwa?\n\nIch bin mir sicher, dass Ihr Euch gefragt habt, was wohl in der riesigen Kiste ist. Nun, Ihr müsst nicht länger warten. Bringt einen unserer Bohrtürme zu den Öltümpeln, und bohrt nach Öl für uns.\n\nIhr müsst natürlich damit rechnen, dass die Zentauren angreifen werden. Verteidigt den Turm lange genug, um ein oder zwei Fässer füllen zu können.", sourceObjective = "Verteidigt den Ölbohrturm.", completion = "Öl! Schwarzes Gold! Tanaristee!\n\nWir sind reich! Jetzt müssen wir uns nur den übrigen lästigen Zentauren annehmen. Mit dem ganzen Gold, das wir verdienen werden, können wir uns sicher leisten, sie auf irgendeine andere Klippe umzusiedeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[25800] = { id = 25800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn das Leben dir Krabben schenkt...", description = "Es gibt hier viel zu tun, {class}, aber wir dürfen die Augen nicht vor den Geschenken des Schicksals verschließen.\n\nAls die Flut über unsere Häuser hereinbrach, schwemmte sie viele Meeresbewohner an. Die Bucht von Menethil ist jetzt voller großer Krabben, die genau richtig sind, um sie einzusammeln.\n\nWenn das Leben dir Krabben schenkt, geh Krabbenfischen, sag ich immer. Bringt mir die größten und fleischigsten Scheren, die Ihr finden könnt und ich bezahle Euch.", sourceObjective = "Findet 5 fleischige Kriecherklauen von Hafenkriechern.", progress = "Vergesst die kleineren Scheren - das Fleisch ist die viele Arbeit, es aus den Scheren zu holen, nicht wert.", completion = "Ein herzhaftes Meeresfrüchtedinner wird die Stimmung bei allen heben und uns dabei helfen, die Stadt wieder aufzubauen. Danke für die Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25801] = { id = 25801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klauen aus der Tiefe", description = "Murlocs kriechen aus den tiefen Wassern und bauen ihre Dörfer entlang der Küste. Sie überfallen unsere Fischer und Händler und müssen aufgehalten werden.\n\nEiner dieser Murlocs, Gobbler, streift mit den anderen Murlocs der Blaukiemen umher und plündert die Händler entlang der Straße aus, wobei sie sich danach immer in die Sicherheit der nahegelegenen Hütten zurückziehen. Unsere Händler sind in Gefahr und wir sind bereit, für ihre Sicherheit zu zahlen.\n\nGobbler strolcht in der kleinen Bucht nördlich von hier herum. Findet ihn, erschlagt seine Artgenossen und bringt mir seinen Kopf.", sourceObjective = "Holt Euch Gobblers Kopf von Gobbler und tötet 12 beliebige Murlocs der Blaukiemen.", progress = "Unsere Händler werden nicht sicher sein, bis wir Gobbler und diese Murlocs losgeworden sind.", completion = "Ah, gut gemacht, {name}.\n\nBitte nehmt dies als Bezahlung für die Erfüllung Eures Vertrages mit der Handelsmarine.", sourceObjectiveStatus = "unverified-source-field" }
quests[25802] = { id = 25802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waren-Wiederbeschaffung", description = "Vor nicht allzu langer Zeit wurde ein Handelsschiff, die 'Blinde Prinzessin', von Murlocs überfallen. Obwohl das Schiff unversehrt entkam, wurde ein Großteil seiner Fracht von den Kreaturen über Bord gezogen, darunter eine äußerst wertvolle Statuette von Terenas Menethil. Wir möchten, dass die Statuette geborgen wird.\n\nDurchsucht die Hütten der Murlocs an der Küste nach Kisten, Fässern und anderen Spuren von verlorener Fracht. Findet die Statuette von Menethil und bringt sie mir wieder.", sourceObjective = "Durchsucht die Kisten und Fässer in den Murloclagern an der Küste.", completion = "Diese Kiste ist mit klauenartigen Kratzern übersät und zeigt Spuren eines Wasserschadens. Das Aufbrechen enthüllt durchnässtes und verfaultes Stroh, als wäre etwas Wertvolles in dieser Kiste aufbewahrt worden. Ihr durchwühlt das Stroh...\n\n... und findet eine Handvoll rot gefärbter Flaschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25803] = { id = 25803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche geht weiter", description = "Ihr durchsucht gründlich diese Ansammlung von Murlochütten, findet aber keine Spur der Statuette von Menethil.\n\nVielleicht gibt es in einer der beiden nahe gelegenen Hütten im Norden und Nordosten mehr Hinweise.", sourceObjective = "Sucht nach der Statuette von Menethil.", completion = "Dieses Fass ist weitgehend unberührt. Als Ihr es öffnet...\n\n... schlägt Euch der stechende Geruch von Käse entgegen. Er ist etwas feucht, aber immer noch schmackhaft!", sourceObjectiveStatus = "unverified-source-field" }
quests[25804] = { id = 25804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche in weiteren Hütten", description = "Dieses Grüppchen Murlochütten offenbart auch nach einer gründlichen Überprüfung nichts.\n\n... Aber Ihr seid Euch sicher, dass der nächste Anhaltspunkt, den Ihr findet, nützlich sein wird.\n\nEine der Hütten nördlich von hier muss die Statuette von Menethil enthalten!", sourceObjective = "Sucht weiter in den Hütten der Murlocs nach der Statuette von Menethil.", completion = "Dieses Fass ist unter Schlamm und Gras halb begraben...", sourceObjectiveStatus = "unverified-source-field" }
quests[25805] = { id = 25805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückgabe der Statuette", description = "<Nachdem Ihr das Fass aus dem Dreck gezogen und geöffnet habt, findet Ihr eine in dünnes Stroh eingepackte, silbrige Figur. Sie stellt einen jungen, langhaarigen Paladin mit erhobenem Hammer dar.\n\nDies kann nur die Statuette von Menethil sein! Ihr müsst sie nun zu Karl Boran in den Hafen von Menethil zurückbringen.>", sourceObjective = "Bringt die Statuette von Menethil zu Karl Boran im Hafen von Menethil.", progress = "Habt Ihr die Statuette?", completion = "Der Kapitän der 'Blinden Prinzessin' wird erleichtert sein zu hören, dass seine kostbare Fracht geborgen wurde. Ihr habt Euch diesen Lohn durch die geleisteten Dienste wohl verdient.\n\nEs tut gut, verlässliche Leute wie Euch zu kennen, insbesondere in so beschwerlichen Zeiten wie diesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25806] = { id = 25806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie haben die Assass in... ach, egal", description = "Ah, die Forscherliga - welche glanzvolle Gruppe von Schwachköpfen. Wir haben nicht nur die Geister der Tauren am Hals, die Forscherliga hat es ebenfalls geschafft, eine Hintertür für die Hauptbasis der Horde im Steinkrallengebirge - der Feste Krom'gar - zu öffnen.\n\nJetzt bringen Auftragsmörder von Krom'gar alle in der Mine um, ohne dass man auch nur einen Mucks hört.\n\nIhr müsst da hineingehen und aufräumen.\n\nBeinahe hätte ich vergessen, Euch diese Brille zu geben. Setzt sie sofort auf. Damit werden alle getarnten Assassinen in der Mine sichtbar.", sourceObjective = "Tötet 12 Auftragsmörder von Krom'gar.", sourceObjectiveStatus = "unverified-source-field" }
quests[25807] = { id = 25807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wiedergeburt eines Ahnen", description = "Ich bin davon überzeugt, dass IHR der Herold Avianas seid, {name}. Ihr wart es, der sie zuerst gesehen hat und ihre Essenz aus den Klauen eines Drachen errettete.\n\nJa, ich glaube, dass Aviana in diese Welt wiedergeboren wird. Und Ihr habt die Ehre, sie über die Schwelle zu führen.\n\nNehmt dieses Rauchwerk und verbrennt es vor Avianas Ei im Raum direkt über mir.\n\nDie Ahnin ist nah, {name}. Unsere Errettung steht kurz bevor!", sourceObjective = "Benutzt das Rauchwerk des Herolds vor Avianas Ei im Schrein von Aviana.", completion = "Ich… lebe.\n\nDiejenigen, die versucht haben, mich zu verderben und meine Kinder zu stehlen, werden bald den Hieb meiner Klauen spüren, {class}. Glaubt mir.\n\nDringt weiter auf den Hyjal vor. Ich werde mich sammeln und die anderen Ahnen um mich rufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25808] = { id = 25808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ist das Ding an?", description = "<Der Gnomcorder summt energiegeladen. Man hört Leutnant Paulson am anderen Ende.>\n\nDämlicher Gnomschrott... Ist da IRGENDWER? {name}, seid Ihr da?\n\nVielleicht ist <er/sie> tot.\n\nFalls Ihr mich hören könnt - wir haben gerade die Nachricht erhalten, dass eine Meisterassassine der Horde sich in den Minen befindet und die anderen Auftragsmörder befehligt. Findet sie, tötet sie und meldet Euch bei mir.\n\nPaulson Ende.", sourceObjective = "Tötet Meisterassassine Kel'istra.", completion = "Gut gemacht, {name}! Eure Arbeit in den Minen war die eines Profis. Wie wäre es, wenn Ihr mir jetzt meine Brille zurückgebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25809] = { id = 25809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst niemanden zurück!", description = "Hordenmonster!\n\n<Korporal Wocard spuckt aus.>\n\nSchaut Euch das hier an! Sie haben Unschuldige getötet! Zivilisten!\n\nHört zu, {name}, Ihr müsst uns helfen. Geht in die Ausufernden Tiefen und sucht nach überlebenden Minenarbeitern. Wenn einige überlebt haben, werden sie wohl vollkommen verängstigt sein! Sucht in allen Nischen und Winkeln der Mine. Vielleicht sogar in den Minenwagen! Es gibt ganz bestimmt Überlebende, die sich irgendwo versteckt haben.", sourceObjective = "Rettet 8 Verängstigte Minenarbeiter.", completion = "Dem Licht sei Dank! Ihr seid wahrlich ein rechtschaffendes Instrument der Macht! Die Allianz kann sich glücklich schätzen, Euch zu haben, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25810] = { id = 25810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brutstätte muss brennen", description = "{name}! Choluna hat die Wahrheit gesprochen: Die Göttin ist zurückgekehrt! Ein Wunder ist geschehen.\n\nIhr habt zwar den Zwielichtdrachen Sethria töten können, wir haben jedoch noch nicht alle Eier ausfindig gemacht, die die Harpyien ihr gebracht hatten. Thisalee und ich haben ihnen nachgespürt und sind dabei auf eine große Brutstätte in den Feuerlanden gestoßen. Sie ist nicht von dieser Welt, also kann Aviana Euch nicht begleiten.\n\nFliegt nach Süden und tretet durch das Flammentor in der Mitte des Tals. Farden Klauenwürger ist vorausgesandt worden und wird im Inneren auf Euch warten.", sourceObjective = "Reist durch das Flammentor in der Mitte der Flammenschneise auf dem Hyjal. Sprecht mit Farden Klauenwürger, sobald Ihr hindurchgegangen seid.", completion = "Also ist es wahr. Aviana ist mit Euch als Herold zurückgekehrt.\n\nEs gibt hier viel zu tun. Wir sind tief im Herzen der Feuerlande. Sethria hat gestohlene Eier vom Hyjal hierher geschmuggelt, um ihre eigenen abstoßenden Kreaturen zu züchten: Raubvögel, die für den Krieg ausgebildet sind.\n\nIch hoffe, dass Ihr bereit seid, zurückzuschlagen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25811] = { id = 25811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stilllegung", description = "Um diese Mine stillzulegen, müsst Ihr die tragenden Pfeiler in die Luft jagen. Ich kann Euch den benötigten Sprengstoff zur Verfügung stellen, aber Ihr müsst Euch an den Auftragsmördern von Krom'gar vorbeischleichen, um alle Träger zu erreichen.\n\nDie gute Nachricht - wenn man das so nennen kann - ist, dass wir die tragenden Pfeiler immer mit einem großen X markiert haben. Schaut nach diesen Markierungen und befestigt das Dynamit in ihrer Nähe. Sobald ihr das Dynamit angebracht habt, kommt wieder hier hoch und ich werde die Sprengung auslösen.\n\nKabumm!", sourceObjective = "Verankert jeweils ein Dynamitbündel am ersten, zweiten, dritten und vierten Träger.", completion = "Wird schon schiefgehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25812] = { id = 25812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höhlenforscher", description = "Schnell, {name}!\n\nBegebt Euch sofort zu dieser Höhle.\n\nWir werden Euch folgen und sicherstellen, dass Euch sonst niemand folgt.", sourceObjective = "Sprecht mit dem Gefreiten Pollard in der Tiefennebelgrotte.", completion = "Ein… ein {race}? Hier?\n\nIch muss wahnsinnig sein…", sourceObjectiveStatus = "unverified-source-field" }
quests[25813] = { id = 25813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Horn erklingen lassen", description = "Dieser alte, verbitterte Zentaur Himmelsrufer Vrakthris hat den großen Luftgeist erwähnt, ein von den Zentauren verehrtes Wesen. Uns diesem Wesen anzunehmen ist der letzte Schritt in der Sicherung der Anhöhen.\n\nIch habe gesehen, wie sie das große Horn oben auf dem Hügel erklingen haben lassen, um den Luftelementar zu rufen. Er gab ihnen Befehle und verschwand gleich darauf wieder.\n\nLasst das Horn erklingen, {name}.", sourceObjective = "Tötet Whrrrl.", completion = "Nun wird ihnen wohl kein magischer Luftzauber zu Hilfe eilen, wenn wir das Gebiet an uns nehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25814] = { id = 25814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Horn erklingen lassen", description = "Dieser alte, verbitterte Zentaur Himmelsrufer Vrakthris hat den großen Luftgeist erwähnt, ein von den Zentauren verehrtes Wesen. Uns diesem Wesen anzunehmen ist der letzte Schritt in der Sicherung der Anhöhen.\n\nIch habe gesehen, wie sie das große Horn oben auf dem Hügel erklingen haben lassen, um den Luftelementar zu rufen. Er gab ihnen Befehle und verschwand gleich darauf wieder.\n\nLasst das Horn erklingen, {name}.", sourceObjective = "Tötet Whrrrl.", completion = "Nun wird ihnen wohl kein magischer Luftzauber zu Hilfe eilen, wenn wir das Gebiet an uns nehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25815] = { id = 25815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dritte Flotte", description = "Ich war einst Erster Maat auf der 'Herrin der Meere', einem Linienschiff der Dritten Flotte von Kul Tiras, der Verlorenen Flotte. Verloren deshalb, weil die Flotte auf ihrer letzten Reise von roten Großdrachen angegriffen wurde. Großdrachen, die von Orcs geritten wurden!\n\nWir hatten keine Chance gegen das Drachenfeuer... und unsere Flotte ging just vor dieser Küste hier brennend unter. Ich bin der einzige Überlebende von diesen armen Schiffen.\n\n... Bringt mir meinen Met, {class}. Er ist unten im Keller des Gasthauses. Auch wenn ich ihn so weit von mir entfernt verstaut habe, ich komme doch nicht ohne aus.", sourceObjective = "Erhaltet Fitzsimmons' Met aus dem Keller des Gasthauses im Hafen von Menethil.", progress = "Oh, ich bin so furchtbar durstig! Wollt Ihr diesem armen, mitleiderregenden Trottel nicht einen Drink spendieren?", completion = "Ah! Das ist genau das richtige und lockert die Zunge. Danke, Kumpel!", sourceObjectiveStatus = "unverified-source-field" }
quests[25816] = { id = 25816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Umherwandeln verdammt", description = "<Gestärkt fährt Fitzsimmons mit seiner Geschichte fort...>\n\nIch bin der einzige Überlebende der unglückseligen Dritten Flotte von Kul Tiras, die vor der Küste im Norden untergegangen ist. Auf einem unserer Schiffe war ein großer und furchtbarer Schatz versteckt und seine gespenstische Macht hält die Seelen meiner Brüder gefangen in den verrottenden Schiffsrümpfen.\n\nIch werde Tag und Nacht von ihnen verfolgt. Der Erste Maat Snellig ruft mich! Er sollte eigentlich tot sein! Bitte, {name} sucht ihn bei den Schiffswracks und... sagt ihm einfach, er soll mich in Ruhe lassen!", sourceObjective = "Sprecht mit dem Geist des Ersten Maats Snellig.", completion = "Fitzsimmons hat Euch geschickt, nicht wahr? Es ist so lange her...", sourceObjectiveStatus = "unverified-source-field" }
quests[25817] = { id = 25817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verfluchte Crew", description = "Die Seeleute der Dritten Flotte sind durch einen Fluch für immer dazu verdammt, an diesen Ufern voller Qualen entlangzuwandeln. Fitzsimmons Seelenqual hängt mit uns zusammen - solange wir leiden, kann auch er nicht ruhen.\n\nIhr müsst das Leiden der Geister meiner Mannschaftskameraden beenden. Löscht ihre Geister auf dieser Ebene aus und kehrt zu mir zurück.", sourceObjective = "Tötet 5 verfluchte Seemänner und 5 verfluchte Marinesoldaten in der Verlorenen Flotte.", completion = "Die gequälten Schreie sind erstickt worden... doch die Ursache des Fluchs noch nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25818] = { id = 25818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brechen des Fluchs", description = "Um den Fluch zu brechen, muss abgerechnet werden. Kapitän Halyndor hat uns alle dazu verdammt, ein verbotenes Artefakt zu begehren, das Auge von Paleth. Sein Geist will es noch immer und wacht über die Schließtruhe seines alten Schiffes, der 'Kühnheit'.\n\nVernichtet die Seele dessen, der uns einst so verfluchte, {class}. Besiegt den Kapitän, nehmt seinen Schlüssel und bringt das Auge von Paleth weit weg von diesem Ort.", sourceObjective = "Besorgt den Geldkassettenschlüssel der 'Kühnheit' von Kapitän Halyndor.", progress = "Diese Truhe ist sicher verschlossen.", completion = "Der Schlüssel ist verrostet, passt aber einwandfrei ins Schloss.", sourceObjectiveStatus = "unverified-source-field" }
quests[25819] = { id = 25819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge von Paleth", description = "In der offenen Truhe erblickt Ihr eine geschwärzte Kugel, die in einem gruseligen Licht pulsiert. Dies muss das schändliche Auge von Paleth sein, das die Seelen dieser Seefahrer verdammt hat.\n\nSolch eine Verderbnis muss ausgemerzt werden. Vielleicht kann Euch ein Priester im Hafen von Menethil helfen.", sourceObjective = "Bringt das verfluchte Auge von Paleth zu Glorin Stahlbraue im Hafen von Menethil im Sumpfland.", progress = "Wie kann ich Euch helfen, Junge?", completion = "Das Auge von Paleth? Ihr sagt, Fitzsimmons hat Euch geschickt?\n\nBeim Lichte... nicht schon wieder. Fitzsimmons ist tot, Mädchen. Ihr seid auch nicht der erste, der so zu mir kommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25820] = { id = 25820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sorgen einer Mutter", description = "Mein Sohn Gimlok ist das Licht meines Lebens. Mein Herz geht auf, wenn ich ihn mit den anderen Kindern spielen sehe.\n\nTrotzdem mache ich mir Sorgen. Nur wenige Meter entfernt, in der Bucht, gibt es Haie. Was, wenn das Wasser so tief ist, dass einer hierher schwimmt...\n\nDer Gedanke ist unerträglich! Ihr habt sicher schon Schlimmeres bewältigt als wir Stadtbewohner, {race}. Würdet Ihr diese schrecklichen Haie für mich beseitigen? Wenigstens ein paar?", sourceObjective = "Tötet 10 Hafenschredderflossen.", completion = "Wie wundervoll, dass Ihr so etwas für eine verheiratete Frau wie mich getan habt. Ihr seid zu freundlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[25821] = { id = 25821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ganz besonderer Auftrag", description = "Ihr habt hier unten Bemerkenswertes geleistet, {name}. Truppenkommandant Valen ist das nicht entgangen. Er möchte Euch sofort sprechen. Er hat Euch für eine besondere Mission ausgewählt - eine, mit der wir die Übergriffe der Horde im Steinkrallengebirge hoffentlich endgültig stoppen werden.", sourceObjective = "Meldet Euch bei Truppenkommandant Valen im Basislager der Nordwachtexpedition im Steinkrallengebirge.", completion = "Schon bei unserer ersten Begegnung wusste ich, dass Ihr eine besondere Schneeflocke seid, {name}. So besonders, dass ich niemandem außer Euch diese Aufgabe anvertrauen würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[25822] = { id = 25822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegswerkzeug", description = "Ich muss Euch noch einmal einer Gefahr aussetzen, {name}. Im Osten gibt es eine von der Horde erbeutete Ausgrabungsstelle, die reich an Mineralien ist. Kisten mit unseren Waffen befinden sich dort. Sie sind überall verstreut. Die Horde ist erst vor kurzem dort eingefallen. Es ist unwahrscheinlich, dass sie bereits all unsere Ausrüstung gefunden haben.\n\nGeht dorthin und besorgt unseren Grimmtotemfreunden ein paar Waffen!", sourceObjective = "Sammelt 10 Waffenkisten der Allianz.", progress = "Habt Ihr das Kriegswerkzeug gefunden?", completion = "Das sollte reichen, um hundert Grimmtotems auszurüsten! Jetzt müssen wir die Waffen ihrem Häuptling übergeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25823] = { id = 25823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die unerbittliche Horde", description = "Es ist zwar äußerst wichtig, dass Ihr die Waffenkisten unverzüglich sichert, aber wir müssen die Grabstätte im Osten auch von der Horde säubern. Wir müssen vollen Zugang zur Ausgrabungsstätte erhalten, sonst können wir keine Nachschublinie für die Grimmtotemverbündeten schaffen.\n\nTötet alle Angehörigen der Horde, denen Ihr an der Grabstätte begegnet, {name}. Für den Ruhm der Allianz!", sourceObjective = "Tötet 12 Angehörige der Horde an der Grabstätte.", completion = "Ich werde der Infanterie befehlen, nachzurücken und die Zurückgebliebenen zu beseitigen. Hätten wir doch zehntausend wie Euch, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25824] = { id = 25824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befragung", description = "Dieser Soldat stand an der Schwelle zum Tod, aber ich fürchte, wir können nicht warten, bis er wieder ganz genesen ist. Er hat Informationen, die wir dringend brauchen.\n\nSeid geduldig mit ihm, aber sorgt dafür, dass er weiterredet, bis er uns alles gesagt hat.\n\nMit ein bisschen Glück erfahren wir, womit wir es hier zu tun haben.", sourceObjective = "Sprecht mit Gefreiter Pollard und erfahrt etwas über seine Tortur.", completion = "Nun, es ist nicht gerade ermutigend, aber es ist immerhin etwas.", sourceObjectiveStatus = "unverified-source-field" }
quests[25825] = { id = 25825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rohstofflieferung", description = "Also, {name}, ich will, dass Ihr das Öl zu Fizzel auf dem Turbodampfer bringt und ihm von den guten Neuigkeiten erzählt!", sourceObjective = "Bringt das Fass mit Öl zu Fizzel Kupferbolz auf Fizzels & Pozziks Turbodampfer in Tausend Nadeln.", progress = "Was ist das? Ist das Öl?!", completion = "Es ist Öl! Ihr seid ja wirklich von unschätzbarem Wert, {name}!\n\nZu schade, dass ich Euch jetzt schon wieder weiterschicken muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[25826] = { id = 25826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rohstofflieferung", description = "Also, {name}, ich will, dass Ihr das Öl zu Pozzik auf dem Turbodampfer bringt und ihm von den guten Neuigkeiten erzählt!", sourceObjective = "Bringt das Fass mit Öl zu Pozzik auf Fizzels & Pozziks Turbodampfer in Tausend Nadeln.", progress = "Hallo noch mal. Ist das Öl?!", completion = "Es ist Öl! Ihr seid wirklich richtig gut, {name}!\n\nZu schade, dass ich Euch jetzt schon wieder weiterschicken muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[25827] = { id = 25827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lo'Gosh ist bereit für die Schlacht", description = "Dank Eurer Bemühungen wandelt der große Wolfsahne erneut unter uns.\n\n{class}, Ihr müsst für mich zum Weltenbaum zurückkehren und Ysera Bescheid geben, dass Lo'Gosh bereit ist, an vorderster Front für uns zu kämpfen.\n\nIhr könnt Ysera auch fragen, wie Ihr die anderen Ahnen entfesseln könnt.\n\nLok'tar Ogar, mein Freund. Ihr seid wahrlich eine Inspiration für uns alle!", sourceObjective = "Sprecht mit Ysera am Weltenbaum auf dem Hyjal.", sourceObjectiveStatus = "unverified-source-field" }
quests[25828] = { id = 25828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldrinns Botschaft an Ysera", description = "Goldrinn wurde entfesselt und marschiert an unserer Seite! Was Ihr getan habt, kann man nur als Wunder bezeichnen.\n\nWir müssen Ysera beim Weltenbaum benachrichtigen. Die Schläferin koordiniert unsere Bemühungen, Hyjal zurückzuerobern. Es wird sie sicher freuen, dass Goldrinns legendäre Standhaftigkeit nun zu ihrer Verfügung steht.\n\nIhr könnt Ysera auch fragen, wie Ihr die anderen Ahnen entfesseln könnt.\n\nLebt wohl, {name}. Und danke. Ihr seid wahrlich eine Inspiration für uns alle!", sourceObjective = "Sprecht mit Ysera am Weltenbaum auf dem Hyjal.", sourceObjectiveStatus = "unverified-source-field" }
quests[25829] = { id = 25829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - Goldrinn Hub Complete" }
quests[25830] = { id = 25830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte lebende Wissenshüter", description = "Ihr habt die Ahnen erweckt, {name}, aber Aessina, der Geist der Wildnis, schweigt noch immer. Mit ihrer Hilfe können wir diesen Kampf zu unseren Gunsten wenden und den Schaden, den der Schattenhammer angerichtet hat, rückgängig machen.\n\nEs mag jemanden geben, der uns dabei helfen kann. Der älteste der Bäume, Nordu, stand seit Tausenden von Jahren in der Mitte dessen, was heute die Flammenschneise ist. Seine Weisheit ist so alt wie dieser Berg. Wenn dieser alte Baum noch am Leben ist, kann er uns vielleicht dabei helfen, Aessina zu erwecken. Sucht nach ihm!", sourceObjective = "Findet Nordu, das Urtum der Lehren, in der Flammenschneise auf dem Hyjal.", completion = "Ich… bin noch nicht… entschwunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25831] = { id = 25831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hamuuls Botschaft an Ysera", description = "{name}, wir haben den Boden vorbereitet und uns die Hilfe des rätselhaften Schildkrötenahns gesichert.\n\nBitte reist nach Nordrassil zum Weltenbaum und lasst Ysera wissen, dass ich bereit bin, den nächsten Schritt zu tun.\n\nEs ist wichtig, dass wir alle Ahnen wecken, die wir können. Sprecht mit Ysera, um zu erfahren, wo Ihr auf dem Hyjal gebraucht werdet.", sourceObjective = "Sprecht mit Ysera am Weltenbaum auf dem Hyjal.", sourceObjectiveStatus = "unverified-source-field" }
quests[25832] = { id = 25832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Aviana", description = "{name}, Ihr habt hier alles getan, was Ihr tun könnt. Die ganze Höhle wird bald in sich zusammenbrechen!\n\nIch treibe die letzten schwingenbewehrten Hengste zusammen und stelle sicher, dass das Flammentor hinter mir versiegelt wird.\n\nIhr solltet losgehen und Aviana berichten, dass diese abscheuliche Brutstätte der Vergangenheit angehört!", sourceObjective = "Kehrt zu Aviana am Schrein von Aviana auf dem Hyjal zurück.", completion = "<Avianas Gesicht ist wie versteinert, als Ihr ihr erzählt, was in der Brutstätte passiert ist.>\n\nSie haben meine Eier gestohlen, {class}. Sie haben sie an diesen widerlichen Ort gebracht. Sie verderbt.\n\nMeine Kinder gestohlen, gequält, in einem Flammenmeer getötet... Ja, wir werden den Schattenhammer dafür bezahlen lassen.\n\nAber ich muss zugeben, dass ein Teil von mir sich einfach in die Lüfte erheben und diese ganze... Welt... in Flammen sehen möchte.", sourceObjectiveStatus = "unverified-source-field" }
quests[25833] = { id = 25833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avianas Botschaft für Ysera", description = "Zehntausend Jahre lang schwebte ich ohne Form durch den Smaragdgrünen Traum. Und nun erwache ich in einem Alptraum.\n\n{race}, begebt Euch zur Träumerin, den Drachenaspekt, den Ihr Ysera nennt. Lasst sie wissen, dass ich zurückgekehrt bin und den Wächtern des Hyjal helfen werde, den Schattenhammer auszulöschen.\n\nIch werde ihre Himmel mit Leid trüben.", sourceObjective = "Sprecht mit Ysera am Weltenbaum auf dem Hyjal.", sourceObjectiveStatus = "unverified-source-field" }
quests[25834] = { id = 25834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stellvertreterkrieg", description = "Hört Ihr sie dort unten kämpfen, {name}? Anscheinend haben sich die Tauren der Grimmtotems mit der Horde überworfen. Ich weiß nicht, wie das geschehen ist, aber wir könnten es zu unserem Vorteil nutzen.\n\nIch werde ein Treffen mit dem Botschafter der Grimmtotems arrangieren. Ich möchte, dass Ihr eine Friedensgabe zusammenstellt.\n\n<Truppenkommandant Valen zeigt auf Kräcka.>\n\nRedet mit \"Kräcka\", {name}. Er weiß bereits, was zu tun ist.", sourceObjective = "Sprecht mit \"Kräcka\" Aschebäscha im Basislager der Nordwachtexpedition im Steinkrallengebirge.", completion = "Man nennt mich \"Kräcka\", Junge: den besten Koch von Azeroth. Der Kommandant hat mir schon gesagt, was los ist. Wir müssen ein erstklassiges Taurenmenü zusammenstellen, damit wir eine Audienz beim Häuptling der Grimmtotems bekommen.\n\nBesorgt mir die Zutaten, dann koche ich etwas, dem kein Tauren widerstehen kann. Noch nicht mal ein grimmiger Tauren, oder was immer die auch sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[25835] = { id = 25835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Freiwindposten befreien", description = "Es ist an der Zeit, dass Ihr geht. Wie schnell die Küken aus dem Nest fallen – oder so ähnlich.\n\nWie dem auch sei, Ihr habt hier gute Arbeit geleistet, aber Quentin und die Nachtelfen haben einen Hilferuf ausgestoßen und benötigen dringend Unterstützung mit den Grimmtotems im Freiwindposten nordwestlich von hier.\n\nWenn Ihr mich fragt, da ist alle Hoffnung verloren, aber wer weiß... vielleicht können sie es mit Eurer Hilfe wirklich schaffen?", sourceObjective = "Sprecht mit Quentin im Freiwindposten in Tausend Nadeln.", completion = "Ich bin froh, dass Fizzel Euch endlich hergeschickt hat. Wir helfen den Tauren dabei, den Freiwindposten zurückzuerobern und die Grimmtotems zu verdrängen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25836] = { id = 25836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Freiwindposten befreien", description = "Es sieht so aus, als sei es an der Zeit, dass sich unsere Wege trennen – zumindest vorübergehend. Nordwestlich von hier benötigen die Tauren im Freiwindposten dringend Hilfe, um den Grimmtotemklan zurückzudrängen.\n\nDa Ihr hier so großartig helfen konntet, gehe ich davon aus, dass Ihr auch dort äußerst schnell als <Held/Heldin> gefeiert sein werdet!", sourceObjective = "Sprecht mit Thalia Bernhaut im Freiwindposten in Tausend Nadeln.", completion = "Ich fühle mich geehrt, dass Ihr zu Hilfe gekommen seid, {class}. Es war sehr freundlich von Pozzik, Euch zu schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[25837] = { id = 25837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das perfekte Dinner", description = "Für eine ordentliche Friedensgabe brauche ich folgende Zutaten:\n\nEier eines Kalimdoradlers. Ihr findet sie in den Nestern der Kalimdoradler. Sucht in dem Wald im Westen danach. Widderkeulen! Und zwar die Keulen des Steinkrallenwidders.\n\nDie letzte Zutat ist zwar schwer zu bekommen, aber wir brauchen sie für unser Widderlett. Reist nach Südwesten zur Steinschlagklamm und macht die Koboldhöhlen ausfindig. Tötet die Kobolde und stehlt ihren besonderen Käse.\n\nBringt alle Zutaten zu mir, dann werde ich ein Meisterwerk kochen!", sourceObjective = "Sammelt 6 Eier von Kalimdoradlern, 8 Widderkeulen und 10 Stücke Steinschlagkäse.", progress = "Das Widderlett macht sich nicht von allein!", completion = "Bleibt zurück, {name}, gleich gibt's 'ne Geschmacksexplosion und ich will nicht, dass Ihr verletzt werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25838] = { id = 25838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe aus Stahlrosts Depot", description = "Dank Eurer Hilfe sind wir näher an die Zuflucht der Frostmähnen herangerückt. Unsere Streitkräfte werden bald in Position gehen und die Reserve der Frostmähnentrolle angreifen. Dann ist ihr Dorf ungeschützt.\n\nDas ist ein Fall für das Geheimteam Gnomeregan. Seine Techniker haben eine Möglichkeit gefunden, Kämpfer hinter die feindliche Linien zu bringen, ohne dass die Frostmähnen das bemerken. Begebt Euch zu Stahlrosts Depot nordöstlich der Stadt und sprecht mit Delber Kurbeldreh. Er wird Euch mehr darüber berichten.", sourceObjective = "Sprecht mit Delber Kurbeldreh in Stahlrosts Depot.", completion = "Ah, Ihr müsst der {class} sein, den Hauptmann Tharran schicken wollte. Ich habe einen Großteil des Geheimteams bereits mit einem Entfalt-O-Tron in Position nahe an die Zuflucht der Frostmähnen gebracht. Sie warten nur noch auf Euer Eintreffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25839] = { id = 25839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ultrasichere Personalabschussgerät!", description = "Der Kataklysmus hat unsere Feinde näher gebracht, deshalb hat mich der Chef des Geheimdienstes von Gnomeregan gebeten, ein Gerät zu konstruieren, mit dem man Personal rasch und leise in jeden Teil Dun Moroghs transportieren kann.\n\nTataa, das ultrasichere Personalabschussgerät!\n\nMit nur einem Schuss Elektrizität und dank des SPE-Fallschirmsystems, äh, sehr späte Entfaltung für Laien, bringt Euch dieses Baby direkt zur Front. Steigt ein und bereitet Euch auf den Flug vor! Slamp Wackelrad erwartet Euch in der Landezone.", sourceObjective = "Fliegt mit dem ultrasicheren Personalabschussgerät zur Zuflucht der Frostmähnen.", completion = "Keine Sorge, das Gefühl, einen Stromschlag erhalten zu haben, vergeht nach ein paar Minuten. Es gibt wirklich schlimmere Fortbewegungsmittel. An dem Fallschirmsystem muss jedoch noch gearbeitet werden. Sehr späte Entfaltung ist ernst gemeint. Manchmal zu spät. Na ja, wir haben eine Mission zu erfüllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25840] = { id = 25840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eliminiert den Widerstand", description = "Der Häuptling der Frostmähnen starb beim ersten Angriff der Troggs. Seitdem werden sie von einem sehr respektierten Krieger angeführt. Battok der Berserker war derjenige, der den Rückzug der Frostmähnen organisierte, das neue Dorf errichten ließ und die Angriffe gegen Kharanos und die Gebirgsjäger führte.\n\nWenn wir Battok beseitigen, sollte Chaos unter den Frostmähnen ausbrechen. Dann können sich die Gebirgsjäger um die Überlebenden kümmern. Battok hält sich östlich von hier im Dorf auf.", sourceObjective = "Tötet Battok den Berserker und 5 Krieger der Frostmähnen in der Zuflucht der Frostmähnen.", completion = "Sehr gute Arbeit, {name}. Ich gebe Hauptmann Tharran das Signal, dass Battok tot ist. Das sollte das Ende der Frostmähnenbedrohung sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[25841] = { id = 25841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff von oben", description = "Delbers Techniker haben Tag und Nacht gearbeitet, um uns bei den Vorbereitungen auf den Angriff zu helfen. Seine Leute haben nicht nur das Personalabschussgerät konstruiert und eingestellt, sondern auch das geheime Fliegergeschwader für den Angriff auf die Zuflucht der Frostmähnen vorbereitet. Sie warten auf das Signal zum Beginn ihrer Angriffe.\n\nNehmt dieses Leuchtfeuer und zündet es nahe der Gebäudegruppe am Nordrand des Dorfs und neben den Gebäuden am Südrand des Dorfs. Die Flugmaschinen werden an beiden Stellen zuschlagen.", sourceObjective = "Benutzt das Signalleuchtfeuer, um Luftangriffe am nördlichen und südlichen Rand der Zuflucht der Frostmähnen anzufordern.", completion = "Ihr und die Luftstaffel habt Euch vorbildlich verhalten. Die Frostmähnen werden jetzt sicherlich nicht mehr hier bleiben. Wir müssen nur noch die Überlebenden beseitigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25842] = { id = 25842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuergefecht", description = "Es ist… zu spät für mich. Bis auf den Kern ist alles verbrannt. Ich habe Äonen erlebt… und doch scheint mein Ende so plötzlich zu kommen.\n\nAus altem kann neues Leben entstehen. Ich habe immer noch meine Weisheit, die ich weitergeben kann. Bitte… Lasst nicht zu, dass sie mich wegbringen, bevor meine Arbeit getan ist.\n\nHaltet meine Peiniger zurück... nur noch eine Weile, {class}.\n\nGebt mir ein paar Minuten und ich werde es mit tausenden Jahren vergelten.", sourceObjective = "Tötet 5 feurige Peiniger, um sie von Nordu fernzuhalten.", completion = "Danke, {race}.\n\nIch bin jetzt bereit.\n\nAlles, was ich bin, und alles, was dieser Wald je war… gehört jetzt Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[25843] = { id = 25843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tortollas Rache", description = "Der Berg erblüht wieder! Wenn wir schnell handeln, können wir unseren Vorteil ausnutzen.\n\nUnser alter Freund Tortolla, der Schildkrötenahn, ist bereits auf dem Weg. In seinem eigenen Tempo natürlich…\n\nFindet Tortolla östlich von hier, am Kopf des Pfades in die Verbrannte Ebene. Unsere Festungen dort sind schon ganz zu Anfang unseres Schlachtzugs gefallen, aber vielleicht können wir sie jetzt zurückfordern.", sourceObjective = "Sprecht mit Tortolla in der Verbrannten Ebene auf dem Hyjal.", completion = "{race}.\n\nIch erinnere mich an Euch. Retter meiner Kinder.\n\nDie Zeit ist gekommen. Für Rache.", sourceObjectiveStatus = "unverified-source-field" }
quests[25844] = { id = 25844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sättigt die wilde Bestie", description = "Ihr habt den Kommandanten gehört, {name}. Bringt mir das perfekte Geschenk für den Botschafter der Grimmtotems! Er wartet mit seinem Trupp am unteren Ende des südöstlichen Pfads.\n\nDas sollte unser Ansehen bei ihrem Häuptling steigern!", sourceObjective = "Bringt Ton Windbogen am Posten der Grimmtotems die fleischige Gabe.", progress = "<Ton Windbogen schnüffelt und hebt die linke Hand.>\n\nIhr habt etwas für uns dabei?", completion = "<Ton und seine Leibwächter verschlingen die fleischige Gabe.>\n\nEtwas... etwas so Gutes habe ich noch nie gegessen. Vielleicht erweist Ihr Euch doch noch als wertvoller Verbündeter, aber bevor die Grimmtotems sich auf eine Zusammenarbeit mit der Allianz einlassen, müsst Ihr unseren Bedingungen zustimmen. Hier sind sie, so wie mein Anführer sie mir gesagt hat. Bringt sie Eurem Kommandanten. Mal sehen, ob er zustimmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25845] = { id = 25845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forderungen", description = "Die Grimmtotems brauchen Waffen! Die Horde hat dank ihres Kriegshäuptlings und der Hilfe ihrer neuen Goblinverbündeten mächtige Waffen angehäuft. Unsere Kriegswerkzeuge haben dieser Feuerkraft nichts entgegenzusetzen. Stattet die Grimmtotems mit starken Waffen aus, dann werden wir gemeinsam die Horde vernichten!\n\nDies sind unsere Forderungen! Versorgt die Grimmtotems, dann kämpfen wir für die Allianz!", sourceObjective = "Bringt die Forderungen der Grimmtotems zu Truppenkommandant Valen im Basislager der Nordwachtexpedition im Steinkrallengebirge.", progress = "Und???", completion = "Waffen, hm?\n\n<Truppenkommandant Valen seufzt.>\n\nIch werde jetzt eine spontane Entscheidung fällen, {name}. Ich hoffe, es ist die richtige, sonst wird mich König Wrynn einen Kopf kürzer machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25846] = { id = 25846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grundig Finsterwolke, Häuptling der Grimmtotems", description = "Der Häuptling der Grimmtotems erwartet Euch, {name}. Nehmt die Waffenkisten und brecht zum Posten der Grimmtotems südlich von hier auf.\n\nViel Glück, {name}. Sollte Euch etwas zustoßen, werde ich persönlich Eure Angehörigen informieren und König Wrynn wissen lassen, was Ihr für die Allianz getan habt.", sourceObjective = "Bringt die Waffenkisten der Allianz zu Grundig Finsterwolke am Posten der Grimmtotems im Steinkrallengebirge.", progress = "Habt Ihr die Waffen?", completion = "Das sind gute Waffen! Mächtiger Stahl! Mit solchen Waffen werden meine {class} unbesiegbar sein. Magatha lächelt auf Euch herab, {name}.\n\nIch möchte Euch um einen, vielleicht auch zwei Gefallen bitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25847] = { id = 25847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Überlegenheit der Grimmtotems", description = "Überall im Hochwipfeltal werden Grimmtotems von der Horde angegriffen. Höllschreis Armeen kennen weder Gnade noch Mitgefühl. Sie töten jeden, der ihnen im Weg steht.\n\nDas muss ein Ende haben! Nehmt das Kriegswerkzeug, das Ihr uns gebracht habt und sucht nach Grimmtotems, die gegen die Horde kämpfen. Gebt ihnen die Waffen der Allianz und seht zu, wie sie die Angreifer der Horde vernichten! Geht. Es gibt viel zu tun, <Verbündeter/Verbündete>.", sourceObjective = "Bewaffnet 12 Grimmtotems mit der Waffenkiste der Allianz.", progress = "Habt Ihr die Grimmtotems bewaffnet?", completion = "Der Kampf ist noch längst nicht vorbei, {name}. Die Hordengeneräle leben noch...", sourceObjectiveStatus = "unverified-source-field" }
quests[25848] = { id = 25848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untergang", description = "Als wir erfuhren, dass Höllschrei einen weiteren Orc der Mag'har ausgesandt hatte, um die Hordentruppen im südlichen Steinkrallengebirge anzuführen, war es bereits zu spät. Camp Aparaje war niedergebrannt worden, alle Grimmtotems in dem Gebiet waren in den Flammen vergangen.\n\nVier der gefürchtetsten Hordengeneräle führen die Schlacht um das Hochwipfeltal an, unter ihnen auch der Mag'hargeneral Glubgok.\n\nReist nach Süden, zu den Ruinen von Camp Aparaje, und tötet die Generäle. Wir halten die Horde JETZT auf! Kehrt zu mir mit ihrem Zeichen zurück!", sourceObjective = "Tötet die Hordengeneräle in Camp Aparaje und erbeutet das Insigne des Hordengenerals.", progress = "Sind die Generäle tot?", completion = "<Grundig zerquetscht das Insigne in seiner riesigen Faust.>\n\nIhr habt es geschafft, Verbündeter! Höllschrei wird Wochen brauchen, um sich von diesem Schlag zu erholen. Das südliche Steinkrallengebirge gehört den Grimmtotems... und der Allianz natürlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[25849] = { id = 25849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff der Archäologie", description = "Hört zu, <mein Freund/meine Liebe>, jeder gute Archäologe kennt die Risiken seines Berufs. Wenn man nicht wenigstens einmal in seiner Karriere einen uralten Dämon ausgräbt oder von einem boshaften Geist verflucht wird, dann sucht man nur nach Plunder!\n\nWahre Archäologen wissen, dass Kleinigkeiten wie versteinerte Knochen, die zu Skelettkriegern reanimiert werden, kein Grund sind, die Arbeit einzustellen.\n\nDiese versteinerten Knochen brauche ich. Erbeutet sie von den Fossilienmonstern, die in der Gegend umherstreunen und bringt sie mir. Ich werde Euch belohnen.", sourceObjective = "Erbeutet 20 versteinerte Knochen von lebenden Fossilien.", progress = "Ihr müsst Euch nicht zurückhalten! Bringt mir, so viel Ihr tragen könnt!", completion = "Seht Ihr? Nicht schlecht, oder? Ich wünschte fast, all meine Funde würden sich selbst ausgraben. Würde mir die Arbeit erleichtern!\n\nIhr habt sie natürlich auch erleichtert, {name}. Besten Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[25850] = { id = 25850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlagt die Erde!", description = "Falls es Euch entgangen sein sollte, das Land hier im Sumpfland ist ziemlich chaotisch. Überflutungen, Erdbeben... und jetzt wird auch noch der Boden wild.\n\nIch hätte nie geglaubt, dass wir einmal von unserer Grabungsstelle angegriffen werden würden, aber seit kurzem laufen Erdschollen Amok und versuchen, jeden Zwerg zu zerquetschen, den sie finden können.\n\nIhr seht jung und kräftig aus, {race}... würdet Ihr dort hinunter gehen und diesen Klumpen etwas Verstand einprügeln?", sourceObjective = "Tötet 7 paläolithische Elementare.", completion = "Ihr habt es ihnen gezeigt! Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25851] = { id = 25851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der mit den Grimmtotems tanzt", description = "Kehrt zu Eurem Anführer zurück und berichtet ihm, was Ihr für die Grimmtotems getan habt. Sagt ihm, dass unsere Grenzen von nun an für die Allianz geöffnet sind.", sourceObjective = "Meldet Euch bei Truppenkommandant Valen im Basislager der Nordwachtexpedition im Steinkrallengebirge.", completion = "Hervorragende Arbeit, {name}! Nun müssen sich unsere Streitkräfte nur noch beim Betreten des Steinkrallengebirges Sorgen wegen der Horde machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25852] = { id = 25852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles frei", description = "Packt Eure Sachen, {name}, wir werden uns jetzt den restlichen Streitkräften der Nordwacht im Südlichen Brachland anschließen. Eure erste Mission im Südlichen Brachland sollte recht unkompliziert sein.\n\nVor zwei Tagen erreichte uns ein Notruf von Kommandant Walpole. Man hat ihn und sein Bataillon auf dem Steinkrallenpass außerhalb von Ehrenwacht eingekesselt. Die Horde ist überall! Geht dorthin und helft ihm. Ich werde das Nordwachenkommando von unserer Allianz mit den Grimmtotems in Kenntnis setzen.", sourceObjective = "Meldet Euch bei Kommandant Thomas Walpole auf dem Steinkrallenpass im Südlichen Brachland.", completion = "Die Grimmtotems sind also keine Bedrohung mehr? Das ist gut, aber uns tritt hier gerade die Horde in den Hintern!", sourceObjectiveStatus = "unverified-source-field" }
quests[25853] = { id = 25853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ohne Hut und Peitsche", description = "Ich bin für die Ausrüstung dieser Ausgrabungsstätte verantwortlich. Das läuft ganz gut, aber die schnelle Abreise hat uns nicht gut getan!\n\nArchäologen brauchen schließlich Werkzeuge. Man kann unbezahlbare Antiquitäten nicht mit den Händen ausgraben. Wenn Ihr zur Ausgrabungsstätte reist, könntet Ihr uns das Werkzeug, das zurückgelassen wurde, mitbringen?", sourceObjective = "Beschafft 6 Archäologenwerkzeuge.", progress = "Sind sie vollständig? Wir haben einiges zurückgelassen.", completion = "Das erleichtert mich! Vielleicht können wir uns jetzt aus dem Mist graben, in dem wir bis zum Hals stecken.\n\nVergesst es, nur ein schlechter Scherz.", sourceObjectiveStatus = "unverified-source-field" }
quests[25854] = { id = 25854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich nenne ihn Bisschen", description = "Wusstet Ihr, dass manche Raptoren so intelligent sind, dass man sie zähmen kann? Das stimmt! Ich habe Jäger gesehen, die das getan haben.\n\nEs ist hier draußen ziemlich einsam, auch wenn Wenna mir Gesellschaft leistet... ein Haustier würde vielleicht meine Stimmung heben. Ein kleines Raptorbaby wäre toll!\n\nWenn Ihr ohnehin gerade dort draußen die Erwachsenen abschlachtet, könntet Ihr mir einige ausgebrütete Eier mitbringen? Die Eier wackeln, wenn die Babys schlüpfbereit sind.", sourceObjective = "Beschafft sechs wackelnde Raptoreneier.", progress = "Habt Ihr genug Eier? Das Risiko bei nur einem Ei ist zu hoch. Das ist statistisch erwiesen.", completion = "Wunderbar! Sie sollten noch heute schlüpfen...\n\nIch baue besser schon mal ein Gehege, bevor sie alle gleichzeitig schlüpfen. Eigentlich kann nichts schiefgehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25855] = { id = 25855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dingsdabumse", description = "In letzter Zeit fehlen mir ständig Teile für meine Ingenieurskunstprojekte, und nun habe ich den Grund dafür entdeckt. Die Moosfellgnolle stehlen sie!\n\nIch weiß nicht, was sie damit wollen, aber ich muss diese Dingsdas wiederhaben. Wahrscheinlich liegen sie überall in den Sümpfen herum. Würdet Ihr sie mir mitbringen, wenn Ihr welche seht?", sourceObjective = "Findet 7 Dingsdas der Schnellschalts.", progress = "Habt Ihr sie gefunden?", completion = "Das ist wundervoll! Ich fange direkt mit dem Zusammenbau an. Habt Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[25856] = { id = 25856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krokiliskenbälge", description = "Seit Jahren häute ich Krokis im Sumpfland, {class}. Es hat sich jedoch viel verändert.\n\nIch will nicht auf die Tränendrüse drücken, aber als der Kataklysmus den Hafen von Menethil überflutete, riss er auch unser Haus mit sich. Meine Frau und meine Kinder wissen nicht, wo sie bleiben sollen, und ich muss so viel Geld wie möglich verdienen, damit wir bald wieder ein Dach über dem Kopf haben.\n\nIch habe Krokis gehäutet, bis ich vor Müdigkeit umgefallen bin, aber ich brauche noch mehr Häute für den Verkauf. Bringt mir ein paar Krokibälge. Ich zahle Euch auch ein wenig dafür.", sourceObjective = "Erbeutet 10 Marschenkrokiliskenbälge von Sumpflandkrokilisken.", progress = "Habt Ihr Krokbälge für mich?", completion = "Ich bin Euch dankbar, {class}. Die werden meiner Familie helfen, wieder auf die Beine zu kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25857] = { id = 25857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagt Horrorkiefer", description = "Es juckt mir in den Fingern, eine große Beute zu jagen... Horrorkiefer, den größten Krokilisken dort draußen. Mit seinem Balg könnte ich meine Familie aus diesem Loch holen.\n\nAber ich bin kein Narr. Ein Fehler reicht, um ein Bein oder gar mein Leben zu verlieren. Was würden meine Frau und Kinder dann tun? Sie wären immer noch obdachlos und die Kinder hätten keinen Vater mehr, der sich um sie kümmert.\n\nIch bin nicht stolz darauf, aber für die Sicherheit meiner Familie schlucke ich meinen Stolz hinunter. Bitte, {class}... jagt Horrorkiefer für mich. Er lauert im Norden, in seinem schattigen Tümpel.", sourceObjective = "Tötet Horrorkiefer und erbeutet Horrorkiefers Haut.", progress = "Habt Ihr sie? Habt Ihr Horrorkiefers Haut?", completion = "Unglaublich! Ihr seid ein wahrer Held, {name}. Ich werde nie vergessen, was Ihr für mich und meine Familie getan habt.\n\nIch weiß, dass es nicht viel ist, aber nehmt es mit meinem Segen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25858] = { id = 25858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Namen der Lady", description = "Lady Sira'kess hat mit den Vorbereitungen für das Beschwörungsritual begonnen, aber der Schmelztiegel von Nazsharin wurde uns gestohlen. Sicher haben die Kvaldir ihn mit sich genommen, als sie sich in flachere Gewässer zurückgezogen haben.\n\nSprecht mit den Anführern der Kasten, um einen Kriegstrupp zusammenzustellen. Führt sie dann zum Biel'arangrat im Osten, um das Artefakt wiederzuholen.\n\nIch vertraue Euch, meine Kriegsmaid, denn Ihr habt mich noch nie enttäuscht, ganz gleich, welche Aufgabe ich Euch gab. So sehr die Königin mich schätzt, so sehr schätze ich Euch. Geht mit meinem Segen.", sourceObjective = "Sprecht mit Tiefenlord Zin'jatar, Lady Sira'kess und Aufseher Idra'kess.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", completion = "Verstärkung zieht sich in den Gewässern um das Riff zusammen und macht sich für einen Angriff bereit. Sie warten nur noch auf Euren Befehl.", sourceObjectiveStatus = "unverified-source-field" }
quests[25859] = { id = 25859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Vergebung", description = "Ich weiß, dass Ihr genau wie unsere ehrwürdige Lady gelegentlich leider Anflügen von Mitleid unterliegt. Am heutigen Tage möchte ich Euch jedoch raten, diese Freundlichkeiten zu unterlassen. Die Kvaldir sind stolz. Wenn wir sie nicht komplett vernichten, werden sie ganz sicher Rache nehmen. Tötet alle, die Ihr finden könnt.\n\nLeider habe ich die ruhmlose Aufgabe sicherzustellen, dass keiner in die Stadt zurückkehrt, sodass ich Euch den ganzen Spaß überlassen muss. Ich werde Euch aber natürlich anfeuern.", sourceObjective = "Tötet 20 Kvaldir auf der Vrykulklippe.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", completion = "Keiner ist zur Brücke entwischt. Nicht einer.\n\nWie langweilig. Nächstes Mal wäre ich Euch dankbar, wenn Ihr ein bisschen mit mir teilen würdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25860] = { id = 25860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Koste es, was es wolle", description = "Wir beginnen sofort mit dem Ritual. Ihr werdet Euch darum kümmern, dass niemand uns unterbricht.\n\nErschlagt alle Kvaldir, die den Tempel betreten. Achtet darauf, dass meine Priesterinnen überleben, um ihre Aufgabe zu Ende zu bringen. Koste es, was es wolle.", sourceObjective = "Tötet 20 Angreifer der Kvaldir im Tempel von Quel'Dormir.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", progress = "Ich vertraue darauf, dass Ihr uns beschützt, Kriegsmaid.", completion = "Wenn Azjentus etwas verspricht, dann hält er es auch. Lady Naz'jars Ehrenwache sollte ausreichen, um den Rest des Rituals zu überwachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25861] = { id = 25861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Exempel statuieren", description = "Die Hochschamanen befinden sich in den Gebäuden in der Nähe und singen und spotten, trauen sich aber nicht, näher zu kommen. Diese Kvaldir sind nur mutig, wenn sie sich im Nebel verstecken können. Ein erbärmliches Ärgernis unter den Wellen.\n\nIch bringe eine Nachricht. Wenn Ihr die Zeit fändet, gnädige Frau, dann bringt mir einen Hochschamanen und werft ihn mir zu Füßen, auf dass ich ihm und seinem Volk meine Nachricht überbringen kann.", sourceObjective = "Bringt einen Hochschamanen der Kvaldir zu Henker Verathress' Füßen.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", progress = "Wenn Ihr die Zeit fändet, gnädige Frau, dann bringt mir einen Hochschamanen und werft ihn mir zu Füßen, auf dass ich ihm und seinem Volk meine Nachricht überbringen kann.", completion = "Meine Sense ist gesättigt. Vielen Dank, gnädige Frau.", sourceObjectiveStatus = "unverified-source-field" }
quests[25862] = { id = 25862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlenes Eigentum", description = "Unsere ehrwürdige Lady hat mich geschickt, um Euch bei Eurer Aufgabe zu helfen. Sie möchte, dass Ihr den gestohlenen Schmelztiegel von Nazsharin wiederbeschafft und so schnell wie möglich hierher bringt.\n\nSie kann es kaum erwarten, das Beschwörungsritual durchzuführen, damit wir endlich voll und ganz mit unseren Kriegsvorbereitungen beginnen können.", sourceObjective = "Besorgt den Schmelztiegel von Nazsharin.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", completion = "<Der Schmelztiegel sieht viel zu schwer aus, als dass Ihr ihn alleine tragen könntet, aber es sind mehr als genug Streitmächte der Naga übrig, um ihn für den Transport vorzubereiten.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25863] = { id = 25863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiwillige Last", description = "Jetzt, da Ihr den Schmelztiegel von Nazsharin an Euch gebracht habt, müsst Ihr nur noch Lady Naz'jar von Eurem Erfolg berichten.", sourceObjective = "Kehrt mit Euren Nachrichten vom Schmelztiegel von Nazsharin zum westlichen Ende des Biel'arangrats zurück.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", completion = "Gut gemacht, meine Kriegsmaid.\n\nDieser Schmelztiegel wird uns als Quell der Macht für unser Beschwörungsritual dienen. Damit wird Sira'kess unsere Verbündeten aus den Tiefen rufen, um unsere ohnehin schon starke Armee zu unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25864] = { id = 25864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dinosaurierkrise", description = "Ständig erreichen uns Berichte über Raptorangriffe in der Gegend. Ich muss hier für Sicherheit sorgen, damit mehr Siedler kommen. Aus diesem Grund habe ich ein Kopfgeld auf diese Viecher ausgesetzt.\n\nViele wurden bereits beseitigt, aber die Hochlandraptoren im Norden vermehren sich stark. Aber das wird sich bald ändern, nicht wahr?\n\nErledigt ein paar Hochlandraptoren, dann gebe ich Euch eine hübsche Belohnung.", sourceObjective = "Tötet 8 beliebige Hochlandraptoren.", completion = "Gute Arbeit. Betrachtet das nicht als Belohnung von mir, sondern von Eisenschmiede. Der Erhalt von Khaz Modan geht jeden Zwerg etwas an.", sourceObjectiveStatus = "unverified-source-field" }
quests[25865] = { id = 25865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Moosfellmission", description = "Ihr wirkt vertrauenswürdig. Würdet Ihr mir bei meinem wahren Problem helfen, {name}? Eisenschmiede hat mich hierher geschickt, um eine Lieferung Goldbarren wiederzubeschaffen.\n\nDie Barren gehören zum Thronschatz von Eisenschmiede und tragen das königliche Siegel. Nur ein Narr würde sie aus Profitgier stehlen. Sie sind viel zu leicht nachzuverfolgen. Wie es der Zufall will, gibt es jede Menge Narren hier: Moosfellgnolle.\n\nIch weiß nicht, wie oft Ihr schon gegen Gnolle gekämpft habt, aber das sind üble und brutale Bestien. Sie sind gefährlich. Tötet sie und bergt die verschwundenen Barren.", sourceObjective = "Beschafft 8 Barren von Eisenschmiede von den Gnollen der Moosfelle.", progress = "Es wurden schätzungsweise acht Barren gestohlen.", completion = "Gut gemacht! Die Wache von Eisenschmiede dankt Euch, {name}. Ihr habt unserer Stadt einen großen Gefallen erwiesen.\n\nDoch es gibt neue Probleme...", sourceObjectiveStatus = "unverified-source-field" }
quests[25866] = { id = 25866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallensteller der Dunkeleisenzwerge", description = "Der Klan der Dunkeleisenzwerge ist in diesem Gebiet gesehen worden. Vielleicht sind sie Euch schon über den Weg gelaufen. Sie führen nie Gutes im Schilde, und dieses Mal scheinen sie aus irgendeinem Grund Moosfellgnolle zu entführen.\n\nIch weiß nicht, was das soll, aber wir müssen sie aufhalten, bevor noch üblere Dinge geschehen. Haltet sie auf.\n\nWenn Ihr Euch Sorgen macht, weil das unfair ist, könnt Ihr sie ja zuerst höflich fragen. Mal sehen, wie weit Ihr damit kommt.", sourceObjective = "Tötet 10 Fallensteller der Dunkeleisenzwerge.", completion = "Ich nehme an, sie sind nicht freiwillig mitgekommen? Dachte ich mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[25867] = { id = 25867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flucht der Gnolle", description = "Ich weiß, dass wir selbst gerade die Gnolle angegriffen haben, aber ich werde nicht zulassen, dass die Dunkeleisenzwerge sie als Sklaven halten. Zum einen haben wir die Diebe gefunden und unseren Besitz zurückerhalten, also wurde der Gerechtigkeit Genüge getan. Zum anderen werden die Dunkeleisenzwerge sie bestimmt nicht für gemeinnützige Arbeiten einsetzen... \n\nAlso müssen die Gnolle befreit werden. Die Fallensteller sollten die Schlüssel, mit denen man die Käfige öffnen kann, bei sich tragen.", sourceObjective = "Erbeutet den Schlüssel des Fallenstellers von Fallenstellern der Dunkeleisenzwerge und befreit damit 6 Gnolle aus den Gnollkäfigen.", completion = "Das sollte reichen! Je mehr Gnolle diese Narren jagen müssen, desto leichter wird es, sie in Schach zu halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25868] = { id = 25868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yorla Dunkelschlinge", description = "Ich habe herausgefunden, wer bei dieser Operation im Hintergrund die Fäden zieht. Yorla Dunkelschlinge führt die Dunkeleisenzwerge von einem Lager im Osten an. Wahrscheinlich hat sie den Gnollen befohlen, das Gold aus Eisenschmiede zu stehlen.\n\nAußerdem ist sie eine gesuchte Kriminelle... Schon als Magni noch lebte, schürte sie Rebellionen und Angriffe gegen Eisenschmiede.\n\nDieses Mal wird sie uns nicht durch die Lappen gehen, {name}. Schnappt sie Euch!", sourceObjective = "Tötet Yorla Dunkelschlinge.", completion = "Gute Arbeit! Ihr habt eine der größten Verbrecherinnen Eisenschmiedes der Gerechtigkeit zugeführt, {name}. Ihr habt Euch eine ziemlich große Belohnung verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[25869] = { id = 25869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimmtotems im Freiwindposten", description = "Die Reise, die vor uns liegt, beginnt damit, dass Ihr alle Eindringlinge der Grimmtotems im Freiwindposten tötet. Wenn Ihr sie hier nicht aufhalten könnt, werden wir nicht in der Lage sein, bis zu ihrem Territorium vorzudringen.", sourceObjective = "Tötet 10 Eindringlinge der Grimmtotems.", completion = "Bei dieser Aufgabe kann man wirklich nur grimmig dreinschauen.<Quentin hustet.>\n\nNein, das war nicht witzig gemeint.", sourceObjectiveStatus = "unverified-source-field" }
quests[25870] = { id = 25870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimmtotems im Freiwindposten", description = "Ihr müsst die Eindringlinge der Grimmtotems im Freiwindposten loswerden. Das haben sie sich aber selbst zuzuschreiben, diese Feiglinge!\n\nWir können nicht zulassen, dass die Schlacht in ihre eigenen Gebiete verlagert wird, und wir sprichwörtlich mit dem Rücken zu ihnen stehen. Bitte helft uns, unsere Heimat zurückzuerlangen, {class}.", sourceObjective = "Tötet 10 Eindringlinge der Grimmtotems.", completion = "Das ist schon mal ein guter Anfang! Normalerweise würde ich keiner Kreatur der Erdenmutter irgendein Leid wünschen.\n\nAber da sie uns zu einem Zeitpunkt extremer Verletzlichkeit angegriffen haben, verdienen sie den Tod!", sourceObjectiveStatus = "unverified-source-field" }
quests[25871] = { id = 25871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet die Schildwache", description = "<Brienna wedelt mit einer Notiz, die Markierungen in Taurahe aufweist.>\n\nDiese Monster haben eine unserer Schildwachen gefangen! Sie drohen damit, sie zu töten, wenn wir uns nicht zurückziehen!\n\nWir verhandeln nicht mit feigen Bestien! Bitte {class}, könnt Ihr versuchen, die Schildwache zu retten, bevor es zu spät ist?", sourceObjective = "Rettet die Schildwache von Feralas.", completion = "Danke, dass Ihr die sie befreit habt, {name}. Die Monster der Grimmtotems hätten sie sicherlich kaltblütig getötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25872] = { id = 25872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kriegerheld und die Wagemütigen", description = "<Rau wedelt verärgert mit einer Notiz, die Markierungen in Taurahe aufweist.>\n\nDiese Monster haben einen unserer Kriegerhelden gefangen! Sie drohen damit, ihn zu töten, wenn wir uns nicht zurückziehen!\n\nWir werden diesen feigen Grimmtotems nie gestatten, den Freiwindposten zu behalten! Bitte {class}, rettet ihn, bevor es zu spät ist.", sourceObjective = "Retten den Kriegerheld des Freiwindpostens.", completion = "Vielen Dank {name}, dass Ihr den Kriegerhelden befreit habt. Diese Grimmtotems hätten ihn kaltblütig getötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25873] = { id = 25873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Horn des Verräters", description = "Hier liegt der gebrochene Leichnam von Montarr, dem Bewahrer der Lehren des Freiwindpostens. Der Körper des alten Tauren ist gebrochen und in einer Pfütze seines eigenen Blutes.\n\nBlutspuren führen zurück zum Gasthaus...", sourceObjective = "Erhaltet Langhorns Horn.", progress = "Was ist das, {class}?", completion = "Ein Verräter unter den Tauren?\n\nVon so etwas habe ich noch nie etwas gehört. Rivalitäten und Kriege zwischen den Klans sind eine Sache, aber das kaltblütige Töten eines Verbündeten ist etwas anderes.\n\n<Quentin schüttelt ungläubig seinen Kopf.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25874] = { id = 25874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Horn des Verräters", description = "Hier liegt der gebrochene Leichnam von Montarr, dem Bewahrer der Lehren des Freiwindpostens. Der Körper des alten Tauren ist gebrochen und in einer Pfütze seines eigenen Blutes.\n\nBlutspuren führen zurück zum Gasthaus...", sourceObjective = "Erhaltet Langhorns Horn.", progress = "{name}? Habt Ihr Neuigkeiten?", completion = "Der Klippenbehüter war ein Spion der Grimmtotems?! Kein Wunder, dass wir nicht gewarnt wurden!\n\n<Thalia schäumt beinahe über vor Wut.>\n\nDieses verdammte Horn will ich nicht. Lasst es in den Tiefen des Wassers untergehen, und sorgt dafür, dass der Name Langhorn nie wieder erwähnt wird!", sourceObjectiveStatus = "unverified-source-field" }
quests[25875] = { id = 25875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der eingeschleuste Gnom", description = "Am Mirkfallonsee wimmelt es von der Horde. Die Goblins haben sich dort eingenistet, und sie werden erst wieder abziehen, wenn sie das gesamte Öl unter dem Steinkrallengebirge ausgesaugt haben.\n\nZum Glück konnte ich einen Gnom einschleusen, der Informationen für uns sammelt. Wenn irgendjemand weiß, was es mit dieser Bombe auf sich hat, dann mein eingeschleuster Gnom.\n\nGeht zu den Schlickwerken im Norden und findet Minx. Sie hat sich als \"Goblin\" Pumpenkontrolleur getarnt.", sourceObjective = "Sucht in den Schlickwerken im Steinkrallengebirge nach Minx. Sie hat sich als \"Goblin\" Pumpenkontrolleur getarnt.", completion = "Kommt rein und bleibt an der Wand! Meine Tarnung darf nicht auffliegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25876] = { id = 25876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie ist da oben!", description = "Ich folge dieser Bombe, seit Ihr mich im Eschental gerettet habt. Was auch immer sie damit vorhaben, wird bald geschehen.\n\nGanz oben auf der großen Ölplattform gibt es einen Kontrollraum. Im Kontrollraum werdet Ihr das Logbuch von Krom'gar finden. Dieses Logbuch ist der Schlüssel zum Ziel der Bombe. Geht nach oben und holt das Logbuch! Bringt es hierher. Ich werde es für Euch dechiffrieren.", sourceObjective = "Stehlt das Logbuch von Krom'gar.", progress = "Habt Ihr das Logbuch bekommen?", completion = "OH NEIN! Sie wollen die Bombe im Hain von Thal'darah \"testen\"! Das ist eine Schule für junge Druiden mitten im Kriegsnarbental. Ihr müsst zu Barus zurückkehren und ihn davon unterrichten! Meister Thal'darah muss gewarnt werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[25877] = { id = 25877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Zeit für Verabschiedungen!", description = "LAUFT! Verschwindet hier, {name}. Sucht Barus auf und sagt ihm, was Ihr herausgefunden habt. Er wird dafür sorgen, dass Ihr sicher durch das Kriegsnarbental zur Aussicht von Thal'darah gelangt.\n\nFür diese jungen Druiden ist es noch nicht zu spät!", sourceObjective = "Kehrt zu Späherkommandant Barus am Mirkfallonposten im Steinkrallengebirge zurück.", completion = "Verdammte Horde! Ich habe Freunde in diesem Hain. Ich hoffe, Ihr könnt auf einem Hippogryphen reiten. Ihr müsst sofort zu Meister Thal'darah an der Aussicht aufbrechen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25878] = { id = 25878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anleitung zur Sabotage", description = "Goblins... Was wäre die Welt ohne Goblins? Das kann ich Euch sagen: SAUBER!\n\nDiese schmutzigen kleinen Unholde haben überall auf dem See Ölpumpen errichtet, mit denen sie das Öl im Streinkrallengebirge bis auf den letzten Tropfen abzapfen wollen. An jeder Ölpumpe steht ein Ölpumpenkontrolleur, der darauf achtet, dass die Pumpe läuft und nichts schief geht.\n\nAber etwas wird schiefgehen.\n\nBeseitigt die Goblinpumpenkontrolleure und nehmt ihre Pumpensteuerung. Überlastet damit die Pumpen!", sourceObjective = "Zerstört 4 Goblinölpumpen mit der Goblinpumpensteuerung.", completion = "Ich konnte die Explosionen von hier sehen, {name}! Dank Euch wird die Horde keinen Treibstoff mehr vom Mirkfallonsee bekommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25879] = { id = 25879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger mit den Trampeln", description = "Schon mal einen Hobgoblin gesehen? Das ist wieder so eine eklige Schöpfung der Goblins. Nehmt einen Goblin, macht ihn noch hässlicher, fetter, größer und dümmer, und heraus kommt ein Hobgoblin. Fügt dem noch einen miesen Charakter hinzu, dann versteht Ihr das Problem.\n\nDiese Trampel lungern an den Schlickwerken und am Mirkfallonsee herum. Die Goblins setzen sie als Wächter ein.\n\nGeht dorthin und dünnt sie etwas aus. Unwiderruflich.", sourceObjective = "Tötet 10 Trampel.", completion = "Langsam, aber sicher führen wir der Horde Verluste zu. Sie werden kein Bein auf den Boden kriegen, wenn es in diesem Krieg richtig zur Sache geht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25880] = { id = 25880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warnt Meister Thal'darah", description = "Im Hain von Thal'darah leben Dutzende Schüler. Die meisten können sich nicht wehren. Man wird sie abschlachten.\n\nInformiert Meister Thal'darah über die Pläne der Horde. Er wird Euch erklären, was als Nächstes zu tun ist.\n\nFiora Mondsegler hat Euch ihren schnellsten Hippogryphen gegeben. Fliegt damit zur Aussicht von Thal'darah! Seht nicht zurück, {name}! Die Horde muss aufgehalten werden!", sourceObjective = "Meldet Euch bei Meister Thal'darah an der Aussicht von Thal'darah im Steinkrallengebirge.", completion = "Wir leben in wirklich schlimmen Zeiten, {name}. Unser Außenposten auf dem Steinkrallengipfel wurde von grausamen Kreaturen aus der Tiefe überrannt, und die Horde will uns vernichten. Wir brauchen einen Helden, {name}; einen Soldaten der Allianz, der uns sicher durch diese schweren Zeiten führt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25881] = { id = 25881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschollene Wächter", description = "Wir haben so lange durchgehalten wie es ging, {class}. Aber die Flammen… die Hitze… Wir haben die Stadt ganz verloren.\n\nHauptmann Eisenstamm hat sich geweigert, zum Rückzug zu blasen, als die Flammen uns eingeschlossen haben. Unsere Truppen sind überall verstreut. Vielleicht haben ein paar der anderen überlebt? Wir könnten einen Gegenangriff starten!\n\nReist in die Verbrannte Ebene und rettet alle verschollenen Wächter, die von ihrer Gruppe getrennt wurden. Dann sucht nach Hauptmann Eisenstamm. Er befindet sich wahrscheinlich mitten im Kampfgetümmel.", sourceObjective = "Findet und rettet 8 verschollene Wächter.", completion = "Ihr habt die Überlebenden versammelt? Gut, gut. Und der Rest des Berges… ist geheilt?\n\nHa, da brat mir einer einen Storch! Wir sind wieder an der Front!", sourceObjectiveStatus = "unverified-source-field" }
quests[25882] = { id = 25882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für das Gehöft", description = "Hauptmann Tharran hat mich gebeten, Euch seinen Dank für Eure Hilfe und seine Glückwünsche zur erfolgreichen Mission auszurichten. Er kümmert sich mit seinen Männern um die letzten Trolle und versorgt die Verwundeten.\n\nEr hat mich auch gebeten, Euch zu fragen, ob Ihr Berichten über Trollüberfälle auf dem Gehöft Bernruh im Norden nachgehen könntet. Fragt nach Unteroffizier Flinthammer, wenn Ihr dort eintrefft.", sourceObjective = "Sprecht mit Unteroffizier Flinthammer auf dem Gehöft Bernruh.", completion = "Ihr habt also Hauptmann Tharran dabei geholfen, die Frostmähnentrolle zurückzuschlagen? Ich habe Euren Namen in den Berichten gesehen. Freut mich, Euch endlich kennenzulernen. Ein {class} wie Ihr könnte zur Sicherung des Gehöfts eine echte Hilfe sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[25883] = { id = 25883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entwaffnend", description = "Nagawaffen…\n\nAls Ihr Euren Blick über die Pferche streifen lasst, seht Ihr Dutzende ähnlicher Dreizackstapel, die strategisch positioniert zu sein scheinen.\n\nIhre Waffen zu zerstören behindert sicher die bösen Pläne, die sie in dieser Gegend verfolgen...", sourceObjective = "Zerstört 6 Dreizackstapel der Naga.", sourceObjectiveStatus = "unverified-source-field" }
quests[25884] = { id = 25884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Biegen und Brechen", description = "Himmeldonnerwetter nochmal...\n\nIch weiß, dass unser Schiffbrüchiger hier es gut meint, aber der Junge ist doch schwerst traumatisiert.\n\nEs gibt nur eine Methode, wie man mit diesen verflixten Biestern fertig wird, und zwar indem man ihnen eine anständige Zwergenaxt bis zum Anschlag in den Schädel rammt.\n\nJe mehr Leichen ihrer Kameraden man vor ihnen aufstapelt, desto genauer werden sie es sich überleg'n, einem ans Leder zu geh'n.\n\nDas könnt Ihr mir glaub'n, <Kumpel/Mädel>, die Burschen mög'n den Anblick ihres eigenen Blutes genausowenig wie Ihr oder ich.\n\nUnd jetzt ab mit Euch und zeigt denen, was 'ne Harke ist!", sourceObjective = "Tötet 12 Naga des Zin'jatar in der Umklammerung im Tang'tharwald.", sourceObjectiveStatus = "unverified-source-field" }
quests[25885] = { id = 25885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Macht den Algen", description = "Wa… was IST das?!\n\nIch habe so starke Schmerzen… tief in meinem Bauch.\n\nIch glaube… uff… Sie müssen mich vergiftet haben!\n\nSie haben uns merkwürdig leuchtende Algen zu essen gegeben, die sie um ihre Festung herum anbauen…\n\nIch glaube, diese Krämpfe werden immer schlimmer, wenn ich nicht bald mehr davon bekomme...\n\nBitte, {race}. Bringt mir etwas davon!", sourceObjective = "Sammelt 7 Schlängelgrassprösslinge von Erntern der Schimmerrücken in der Umklammerung.", progress = "Konntet Ihr welche von diesen Algen für mich finden, {class}?", completion = "Ja, ja. Genau das sind sie.\n\nVielleicht kann ich mich davon entwöhnen und die Nebenwirkungen so umgehen.\n\nDanke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
